import { it, expect } from 'vitest';
import { createHash } from 'node:crypto';
import { buildExistingOpsSources } from './helpers/existing-ops-proof-builder.js';
import { readFixedExistingOpsGitFixture } from './helpers/fixed-existing-ops-git-fixture.js';
const samples = {
  "packages/brain/src/openclaw-guards.js": "/**\n * openclaw-guards.js — us-vps 零执行守卫（决策 95477a66 收编版）\n *\n * 前身是三个宿主 crontab bash（mem-guard/config-guard/session-runner-router），\n * 散装脚本不进 repo、无测试、运行舱不可见——收编为 Brain scheduler job。\n * 职责：①网关内存泄漏回收 ②配置漂移还原（对话必须进跑场池）③agent 教义补种\n * ④会话跑场探活路由。全部纯函数内核 + 注入式 IO，可单测。\n */\nimport { execFileSync } from 'child_process';\nimport { readFileSync, writeFileSync, appendFileSync, existsSync, readdirSync } from 'fs';\nimport { defaultExecAsync, buildHostCmd } from './host-exec.js';\n\nexport const DOCTRINE_MARK = '## 跑场下放铁律';\n// docker top 的 ps args 必须含 pid，否则 daemon 报 \"Couldn't find PID field in ps output\"\n// （2026-09-16 实证：-eo comm 导致观测线一直空跑，错误被 catch 吞掉）\nexport const MEMLOG_PS_ARGS = Object.freeze(['top', 'openclaw-gateway', '-eo', 'pid,comm']);\nconst STATE = '/opt/openclaw/state';\nconst WORKSPACES = '/opt/openclaw/workspaces-root';\n// 2026-09-16 escort 误伤案校正：网关多会话正常工作态 1.4-1.7G（夜间值守更高），\n// 旧阈值 1400 把正常体温当泄漏一天误摁 9 次、打断在跑 escort。默认抬到 2000，\n// 容器 cgroup 硬顶同步抬 2.29G（阈值必须 < 硬顶，否则守卫永远抢不到 OOM 前面）。\n// env 可调免发版；真泄漏判据改由 memlog 观测线甄别（会话归零后不回落=真漏）。\nconst MEM_LIMIT_MB = parseInt(process.env.OPENCLAW_MEM_LIMIT_MB || '2000', 10);\n/**\n * codex 跑场池。**顺序即优先级，role 决定谁能参与常规竞争。**\n *\n * 为什么 MMV 是 fallback 而不是主力（主理人 0920 拍板）：\n * Claude 与 Grok 的凭据只在 MMV，OpenClaw 用 auth.profiles 的 token 直连它们\n * （clawdbot.json: `xai:manual` / `anthropic:manual`）——**MMV 是这两家唯一的\n * 执行机**。而 codex 走 agentRuntime → ssh 到 session-runner 跑 CLI，哪台机都行。\n * 让 codex 去 M4/M1，MMV 就能专心伺候 Claude 和 Grok。\n *\n * 0920 实测三台的 codex 召唤链路完全等价：网关 key 都能 ssh、codex 0.151.0 都在、\n * 用网关原样命令都能起 app-server、出网 IP 同为 38.23.47.81（M4/M1 无需额外代理）；\n * 且 M4/M1 都有 ~/.codex/auth.json，MMV 反而没有。\n */\nexport const RUNNERS = Object.freeze([\n  { name: 'XIAN-M4', ip: '100.86.57.69', user: 'jinnuoshengyuan', role: 'codex-primary' },\n  { name: 'XIAN-M1', ip: '100.88.166.55', user: 'xx-macmini', role: 'codex-primary' },\n  { name: 'MMV', ip: '100.71.151.105', user: 'administrator', role: 'fallback' },\n]);\n\n/**\n * 两个 ssh 别名，**必须分开**（2026-09-20 P0 事故）。\n *\n * `session-runner` 是 `/usr/local/bin/claude` 包装脚本里写死的名字：\n *   SR='-F /root/.openclaw/ssh-router.conf session-runner'; ssh $SR ...\n * 这个名字不能改（改了要动容器里的脚本），所以让它**钉死 MMV**——\n * 凭据只在 MMV，不在 M4/M1 登录 Claude/Grok（主理人 0920 拍板）。\n *\n * `codex-runner` 是新增的，只给 codex 的 appServer 用，跟着跑场池走。\n *\n * 事故经过：此前两者共用 `session-runner`，跑场一切到 XIAN-M1，\n * Claude 被 codex 的负载均衡一起带走，而 M1 既没装 claude CLI 也没有凭据。\n * 教训：**配置不是唯一的事实来源**——clawdbot.json 里只有 1 处引用，\n * 文件系统里还藏着一个包装脚本。\n */\nexport const CLAUDE_RUNNER_HOST = 'session-runner';\nexport const CODEX_RUNNER_HOST = 'codex-runner';\n\n/** 远端负载探针命令：第一行 codex 进程数，第二行 uptime 的三个 load average。 */\nexport const RUNNER_LOAD_PROBE =\n  \"ps axo command | grep -c '[c]odex' ; sysctl -n vm.loadavg 2>/dev/null | tr -d '{}' | awk '{print $1, $2, $3}'\";\n\n/**\n * 解析 RUNNER_LOAD_PROBE 的输出。任何解析不出的形态一律返回 null ——\n * 调用方会把 null 当「最忙」处理，宁可不选它，也不拿编造的 0 去误导选机。\n */\nexport function parseRunnerLoad(raw) {\n  const lines = String(raw || '').trim().split('\\n').map((l) => l.trim()).filter(Boolean);\n  if (lines.length < 2) return null;\n  const codexSessions = Number.parseInt(lines[0], 10);\n  const load1 = Number.parseFloat(lines[1].split(/\\s+/)[0]);\n  if (!Number.isFinite(codexSessions) || !Number.isFinite(load1)) return null;\n  return { codexSessions, load1 };\n}\n\n/** 负载探测失败时的记分：排到所有真实读数之后。 */\nconst BUSIEST = { codexSessions: Number.POSITIVE_INFINITY, load1: Number.POSITIVE_INFINITY };\n\n/**\n * 切换滞后阈值：新候选要比当前跑场少这么多个 codex 会话才值得切。\n * 没有它，两台负载在伯仲之间时会每 5 分钟来回抖，正在跑的会话跟着遭殃。\n */\nconst SWITCH_HYSTERESIS_SESSIONS = 2;\n\nexport function parseMemMB(s) {\n  const t = String(s).trim();\n  if (t.endsWith('GiB')) return Math.round(parseFloat(t) * 1024);\n  if (t.endsWith('MiB')) return Math.round(parseFloat(t));\n  return null;\n}\n\n/** 判定 agent 的 cron 在整/半点执行（±3min）——该窗口内顺延重启 */\nexport function memGuardDecision({ mb, minute, limitMb = MEM_LIMIT_MB }) {\n  if (mb == null || mb < limitMb) return 'ok';\n  if (minute >= 57 || minute <= 3 || (minute >= 27 && minute <= 33)) return 'defer';\n  return 'restart';\n}\n\nfunction findAppServer(o) {\n  if (o && typeof o === 'object') {\n    for (const [k, v] of Object.entries(o)) {\n      if (k === 'codex' && v?.config?.appServer && typeof v.config.appServer === 'object') {\n        return v.config.appServer;\n      }\n      const r = findAppServer(v);\n      if (r) return r;\n    }\n  }\n  return null;\n}\n\n// 本机 embedded runtime 的模型（无 agentRuntime:codex）= 会话在网关同机跑。\n// 跑场池模型走 ssh 管子到 MMV/M4/M1。sol 只允许出现在 fallbacks（断池保命）。\nconst LOCAL_EMBEDDED_MODEL = 'openai/gpt-5.6-sol';\nconst POOL_MODEL = 'openai/gpt-5.6-terra';\n\nfunction primaryOf(model) {\n  if (!model) return null;\n  return typeof model === 'string' ? model : model.primary ?? null;\n}\n\n/** 返回 null=形状合规；否则返回漂移描述 */\nexport function checkConfigDrift(cfg) {\n  const primary = cfg?.agents?.defaults?.model?.primary;\n  if (primary !== POOL_MODEL) return `primary回落:${primary}`;\n  // agent 级覆盖会绕过 defaults（2026-09-16 实证 6 个 agent 仍在本机跑）——逐个点名\n  const local = Object.entries(cfg?.agents?.entries || {})\n    .filter(([, a]) => primaryOf(a.model) === LOCAL_EMBEDDED_MODEL)\n    .map(([name]) => name);\n  if (local.length > 0) return `agent本机embedded漏网:${local.join(',')}`;\n  const a = findAppServer(cfg);\n  if (!a || a.command !== '/usr/bin/ssh') return 'appServer非ssh下放形态';\n  // 必须是 codex-runner；还写着 session-runner 就是事故前的老形态（会把 Claude 一起带走）\n  if (!(a.args || []).join(' ').includes(CODEX_RUNNER_HOST)) return `appServer未走跑场池别名(应为 ${CODEX_RUNNER_HOST})`;\n  return null;\n}\n\nexport function restoreConfigShape(cfg) {\n  const d = JSON.parse(JSON.stringify(cfg));\n  d.agents.defaults.model.primary = POOL_MODEL;\n  d.agents.defaults.model.fallbacks = [LOCAL_EMBEDDED_MODEL];\n  // agent 级 sol 覆盖一并拉回池（保留原 fallbacks 作断池兜底）\n  for (const a of Object.values(d.agents.entries || {})) {\n    if (primaryOf(a.model) !== LOCAL_EMBEDDED_MODEL) continue;\n    const prevFallbacks = (typeof a.model === 'object' && a.model.fallbacks) || [];\n    a.model = {\n      primary: POOL_MODEL,\n      fallbacks: prevFallbacks.length ? prevFallbacks : [LOCAL_EMBEDDED_MODEL],\n    };\n  }\n  const a = findAppServer(d);\n  if (a) {\n    a.command = '/usr/bin/ssh';\n    a.args = ['-F', '/root/.openclaw/ssh-router.conf', CODEX_RUNNER_HOST,\n      'env', 'CODEX_HOME=$HOME/.codex-gwremote',\n      '/opt/homebrew/bin/codex', '-c', 'cli_auth_credentials_store=\"ephemeral\"',\n      'app-server', '--listen', 'stdio://'];\n  }\n  return d;\n}\n\n/** 缺教义的工作区 → 补种计划（content=null 表示无 AGENTS.md，整份新建） */\nexport function doctrineSeedPlan({ template, workspaces }) {\n  const idx = template.indexOf(DOCTRINE_MARK);\n  if (idx < 0) return [];\n  const doctrine = template.slice(idx);\n  return workspaces\n    .filter((w) => !(w.content || '').includes(DOCTRINE_MARK))\n    .map((w) => ({ dir: w.dir, append: `\\n${doctrine}\\n` }));\n}\n\n/**\n * 触达线活性判据（2026-09-16 空转 22h 静默案）：\n * 读 xian-m4 ~/outreach.log 尾部，看最近若干 tick 是否「只失败不出单」。\n * 拟人跳过/无待触达是正常态（idle），不得误报；有成功单即 healthy。\n */\nexport function parseOutreachHealth(logTail) {\n  const lines = String(logTail || '').split('\\n').map((l) => l.trim()).filter(Boolean);\n  if (lines.length === 0) return { verdict: 'unknown', stalledTicks: 0, reason: null };\n  let stalled = 0;\n  let reason = null;\n  for (const l of lines) {\n    if (/单#\\d+:/.test(l) || /已发送|发送成功/.test(l)) {\n      return { verdict: 'healthy', stalledTicks: 0, reason: null };\n    }\n    const m = l.match(/话术缺失: (\\S+)|发送失败|锁获取失败|异常/);\n    if (m) { stalled += 1; reason = reason || (m[1] ? `NO_SCRIPT(${m[1].replace('NO_SCRIPT ', '')})` : m[0]); }\n  }\n  if (stalled >= 3) return { verdict: 'stalled', stalledTicks: stalled, reason };\n  if (stalled > 0) return { verdict: 'degraded', stalledTicks: stalled, reason };\n  return { verdict: 'idle', stalledTicks: 0, reason: null };\n}\n\n/**\n * 选 codex 跑场。\n *\n * 规则（依次）：\n *  1. 只在 `codex-primary`（M4/M1）里竞争——MMV 再闲也不抢，它要留给 Claude/Grok\n *  2. 活着的主力里选最闲的：先比 codex 会话数，打平再比 load average\n *  3. 负载探不到的机器按最忙处理（宁可不选，也不拿编造的 0 误导）\n *  4. 滞后：当前跑场仍健康时，新候选要少 SWITCH_HYSTERESIS_SESSIONS 个会话才值得切\n *  5. 主力全不可达才回落 MMV；全灭返回 null（调用方保持现状，不写坏路由）\n *\n * @param {(target:string)=>boolean} probeFn 探活\n * @param {{loadFn?:(target:string)=>({codexSessions:number,load1:number}|null), current?:string}} [opts]\n *   不传 loadFn 时退化为「按顺序取第一个探活成功的」（向后兼容旧调用）\n */\nexport function pickRunner(probeFn, opts = {}) {\n  const { loadFn, current } = opts;\n  const alive = RUNNERS.filter((r) => probeFn(`${r.user}@${r.ip}`));\n  if (alive.length === 0) return null;\n\n  const primaries = alive.filter((r) => r.role === 'codex-primary');\n  // 主力全挂才回落 fallback（MMV）——兜底的意义是保住 codex 可用，不是让它常驻\n  if (primaries.length === 0) return alive[0];\n  if (!loadFn || primaries.length === 1) return primaries[0];\n\n  const scored = primaries.map((r) => ({ runner: r, load: loadFn(`${r.user}@${r.ip}`) || BUSIEST }));\n  const busier = (a, b) => (a.load.codexSessions - b.load.codexSessions) || (a.load.load1 - b.load.load1);\n  scored.sort(busier);\n  const best = scored[0];\n\n  // 滞后：当前跑场还活着且没明显更优时，维持现状，别为了一点点差距打断正在跑的会话\n  const incumbent = scored.find((s) => s.runner.name === current);\n  if (incumbent && incumbent !== best) {\n    const saved = incumbent.load.codexSessions - best.load.codexSessions;\n    if (!(saved >= SWITCH_HYSTERESIS_SESSIONS)) return incumbent.runner;\n  }\n  return best.runner;\n}\n\nexport function renderRouterConf({ name, ip, user }) {\n  // claude 那条钉死 MMV：凭据只在 MMV，M4/M1 不登录 Claude/Grok\n  const claudeHost = RUNNERS.find((r) => r.role === 'fallback');\n  const block = (host, h) => `Host ${host}\n  HostName ${h.ip}\n  User ${h.user}\n  IdentityFile /root/.openclaw/mmv_key\n  BatchMode yes\n  StrictHostKeyChecking accept-new\n  ServerAliveInterval 15\n  ServerAliveCountMax 4\n`;\n  return `# 会话跑场路由（Brain openclaw-guards 自动改写; 当前=${name}）\n#\n# 两条路由分开走（2026-09-20 P0 事故后）：\n#   ${CLAUDE_RUNNER_HOST}：/usr/local/bin/claude 包装脚本用，钉死 MMV\n#   ${CODEX_RUNNER_HOST}：codex appServer 用，跟跑场池走（当前=${name}）\n${block(CLAUDE_RUNNER_HOST, claudeHost)}\n${block(CODEX_RUNNER_HOST, { ip, user })}`;\n}\n\n// ——— 运行时组装（IO 全注入，默认真实现）———\nconst defaultIO = {\n  exec: (cmd, args, opts = {}) => execFileSync(cmd, args, { encoding: 'utf8', timeout: 20_000, ...opts }),\n  read: (p) => (existsSync(p) ? readFileSync(p, 'utf8') : null),\n  write: writeFileSync,\n  append: appendFileSync,\n  listDirs: (p) => (existsSync(p) ? readdirSync(p).filter((n) => n.startsWith('clawd')) : []),\n  now: () => new Date(),\n  log: (m) => console.log(`[openclaw-guards] ${m}`),\n};\n\nlet lastRunAt = 0;\nconst INTERVAL_MS = parseInt(process.env.OPENCLAW_GUARDS_INTERVAL_MS || String(5 * 60 * 1000), 10);\n\n/** US 退役本地网关职责，只保留独立触达观测；不读取旧state密钥或写工作区。 */\nasync function runRemoteOutreach(opts) {\n  const out = { local: { status: 'retired', reason: 'gateway_moved_to_macstudio' } };\n  try {\n    const command = \"ssh -o BatchMode=yes -o ConnectTimeout=20 mmv \"\n      + \"\\\"ssh -o BatchMode=yes -o ConnectTimeout=8 jinnuoshengyuan@100.86.57.69 'tail -12 ~/outreach.log'\\\"\";\n    const tail = await (opts.remoteExecFn ?? defaultExecAsync)(\n      buildHostCmd(command, opts.inContainer ?? existsSync('/.dockerenv')), { timeoutMs: 30_000 });\n    out.outreach = parseOutreachHealth(tail);\n  } catch {\n    out.outreach = { verdict: 'unknown', error: 'outreach_evidence_unavailable' };\n  }\n  if (out.outreach.verdict === 'stalled' && opts.raiseFn) {\n    await opts.raiseFn('P1', 'outreach_stalled',\n      `触达线空转 ${out.outreach.stalledTicks} 轮：${out.outreach.reason}。检查飞书话术表「启用状态」。`,\n      { debounce: { windowMin: 180, threshold: 1 } });\n  }\n  return out;\n}\n\nexport async function runOpenclawGuards(_pool, opts = {}) {\n  const mode = (opts.env ?? process.env).OPENCLAW_GUARD_MODE ?? 'local';\n  if (!['local', 'remote'].includes(mode)) throw new Error('invalid_openclaw_guard_mode');\n  const now = opts.nowMs ?? Date.now();\n  if (now - lastRunAt < INTERVAL_MS) return { skipped: true };\n  lastRunAt = now;\n  if (mode === 'remote') return runRemoteOutreach(opts);\n  const io = { ...defaultIO, ...(opts.io || {}) };\n  const out = {};\n\n  // ① 内存守卫\n  try {\n    const raw = io.exec('docker', ['stats', '--no-stream', '--format', '{{.MemUsage}}', 'openclaw-gateway']);\n    const mb = parseMemMB(String(raw).split('/')[0]);\n    const decision = memGuardDecision({ mb, minute: io.now().getMinutes() });\n    // 泄漏甄别观测线（escort 案后立）：会话数归零后 mem 不回落基线才是真泄漏。\n    try {\n      const ps = io.exec('docker', MEMLOG_PS_ARGS);\n      const lines = String(ps).split('\\n');\n      const sessions = lines.filter((l) => /^openclaw$/.test(l.trim())).length;\n      const mcp = lines.filter((l) => l.includes('node')).length;\n      io.log(`memlog mem=${mb}MB sessions=${sessions} nodeprocs=${mcp} decision=${decision}`);\n    } catch { /* 观测失败不影响守卫 */ }\n    if (decision === 'restart') {\n      io.log(`gateway 内存 ${mb}MB 超阈，温和重启回收泄漏`);\n      io.exec('docker', ['restart', 'openclaw-gateway'], { timeout: 120_000 });\n    }\n    out.mem = { mb, decision };\n  } catch (e) { out.mem = { error: e.message }; }\n\n  // ② 配置漂移\n  try {\n    const confPath = `${STATE}/clawdbot.json`;\n    const cfg = JSON.parse(io.read(confPath));\n    const drift = checkConfigDrift(cfg);\n    if (drift && !io.read(`${STATE}/.allow-local-primary`)) {\n      io.log(`配置漂移(${drift})，自动还原铁律形状并重启网关`);\n      io.write(confPath, JSON.stringify(restoreConfigShape(cfg), null, 2));\n      io.exec('docker', ['restart', 'openclaw-gateway'], { timeout: 120_000 });\n    }\n    out.config = { drift: drift || null };\n  } catch (e) { out.config = { error: e.message }; }\n\n  // ③ 教义补种\n  try {\n    const template = io.read(`${WORKSPACES}/clawd/AGENTS.md`) || '';\n    const workspaces = io.listDirs(WORKSPACES).map((n) => ({\n      dir: `${WORKSPACES}/${n}`, content: io.read(`${WORKSPACES}/${n}/AGENTS.md`),\n    }));\n    const plan = doctrineSeedPlan({ template, workspaces });\n    for (const p of plan) {\n      io.append(`${p.dir}/AGENTS.md`, p.append);\n      io.log(`教义补种 -> ${p.dir}`);\n    }\n    out.doctrine = { seeded: plan.length };\n  } catch (e) { out.doctrine = { error: e.message }; }\n\n  // ④ 跑场路由\n  try {\n    const probe = (target) => {\n      try {\n        io.exec('ssh', ['-i', `${STATE}/mmv_key`, '-o', 'BatchMode=yes', '-o', 'ConnectTimeout=5',\n          '-o', 'StrictHostKeyChecking=accept-new', target, 'true'], { timeout: 10_000 });\n        return true;\n      } catch { return false; }\n    };\n    // 负载探针：codex 会话数 + load average。探不到返回 null，pickRunner 会按最忙处理。\n    const loadFn = opts.loadFn || ((target) => {\n      try {\n        return parseRunnerLoad(io.exec('ssh', ['-i', `${STATE}/mmv_key`, '-o', 'BatchMode=yes',\n          '-o', 'ConnectTimeout=5', '-o', 'StrictHostKeyChecking=accept-new', target,\n          RUNNER_LOAD_PROBE], { timeout: 12_000 }));\n      } catch { return null; }\n    });\n    const confPath = `${STATE}/ssh-router.conf`;\n    const cur = io.read(confPath) || '';\n    // 从现有 conf 反解当前跑场，供滞后判断（别为一点点负载差打断正在跑的会话）\n    const current = RUNNERS.find((r) => cur.includes(`HostName ${r.ip}`))?.name;\n\n    const runner = pickRunner(opts.probeFn || probe, { loadFn, current });\n    if (runner) {\n      if (!cur.includes(`HostName ${runner.ip}`)) {\n        io.write(confPath, renderRouterConf(runner));\n        io.log(`跑场切换 ${current || '(无)'} -> ${runner.name} (${runner.ip})`);\n      }\n      out.router = { runner: runner.name, previous: current || null };\n    } else {\n      out.router = { runner: null };\n      io.log('全部跑场不可达，保持现状');\n    }\n  } catch (e) { out.router = { error: e.message }; }\n\n  // ⑤ 触达线活性（空转必须上浮，不再静默）\n  try {\n    const target = 'jinnuoshengyuan@100.86.57.69';\n    const tail = io.exec('ssh', ['-i', `${STATE}/mmv_key`, '-o', 'BatchMode=yes', '-o', 'ConnectTimeout=8',\n      '-o', 'StrictHostKeyChecking=accept-new', target, 'tail -12 ~/outreach.log 2>/dev/null || true']);\n    const health = parseOutreachHealth(tail);\n    out.outreach = health;\n    if (health.verdict === 'stalled') {\n      io.log(`触达线空转 ${health.stalledTicks} 轮（${health.reason}）——告警上浮`);\n      if (opts.raiseFn) {\n        await opts.raiseFn('P1', 'outreach_stalled',\n          `触达线空转 ${health.stalledTicks} 轮：${health.reason}。检查飞书话术表「启用状态」。`,\n          { debounce: { windowMin: 180, threshold: 1 } });\n      }\n    }\n  } catch (e) { out.outreach = { error: e.message }; }\n\n  return out;\n}\n",
  "packages/brain/src/host-exec.js": "/**\n * host-exec.js — 容器内 ssh 逃逸宿主执行的共享三件套\n * 提取自 launchd-patrol.js（ops-collector 复用，重复第2处即提取）。行为不变。\n */\nimport { existsSync } from 'fs';\nimport { execSync, exec as execCb } from 'child_process';\nimport { promisify } from 'util';\nimport { homedir } from 'os';\n\nconst execAsync = promisify(execCb);\n\nexport const EXEC_TIMEOUT_MS = 20_000;\n// execSync 默认 maxBuffer 仅 1MB，采集类命令早已超出（n8n 画布导出 2.1MB、\n// 执行历史 JSON 数 MB），超限抛 ENOBUFS 且**报错不含真实原因**——2026-09-06 实证\n// 第4腿（n8n workflow）因此静默转 parse_error。给足余量，宁可占内存不可丢数据。\nexport const EXEC_MAX_BUFFER = 128 * 1024 * 1024;\n\n/**\n * @param {string} cmd\n * @param {{timeoutMs?:number}} [opts] 重命令（如拉 24MB 阶段执行数据）可放宽超时——\n *   默认 20s 会 ETIMEDOUT（2026-09-08 实证：阶段归因拉 300×80KB 必超）。超时机制本身保留。\n */\nexport function defaultExec(cmd, opts = {}) {\n  return execSync(cmd, {\n    encoding: 'utf8',\n    timeout: opts.timeoutMs ?? EXEC_TIMEOUT_MS,\n    maxBuffer: EXEC_MAX_BUFFER,\n    stdio: ['ignore', 'pipe', 'pipe'],\n  });\n}\n\n/**\n * defaultExec 的异步孪生。语义（encoding/timeout/maxBuffer/stdio、抛错对象带\n * status+stderr）与同步版逐条对齐，唯一区别是**不阻塞事件循环**。\n *\n * 为什么必须有它（2026-09-20 实证，任务 424d9dd2）：ops-model-accounts-collector\n * 串行探 8 个账号，单账号超时 30s，最坏 240s。execSync 期间事件循环整段停摆——\n * dispatch tick 不跑、HTTP 不响应、kernel 租约续不上、心跳停。而 scheduler 给\n * job 配的 `timeoutMs` 走的是 Promise.race（scheduler-jobs.js:129-135），\n * **对同步阻塞完全无效**：定时器根本没机会跑。也就是说那道超时闸是纸糊的，\n * 唯一的解法是不要在事件循环里同步阻塞。\n *\n * 新代码一律用本函数；`defaultExec` 保留只为不惊动既有调用方。\n *\n * @param {string} cmd\n * @param {{timeoutMs?:number}} [opts]\n * @returns {Promise<string>} stdout\n */\nexport async function defaultExecAsync(cmd, opts = {}) {\n  const { stdout } = await execAsync(cmd, {\n    encoding: 'utf8',\n    timeout: opts.timeoutMs ?? EXEC_TIMEOUT_MS,\n    maxBuffer: EXEC_MAX_BUFFER,\n  });\n  return stdout;\n}\n\n/** 密钥发现式回退（照 spawn/host-executor.js 先例）：宿主实际只有 id_rsa，硬编码 ed25519 会 Permission denied */\nexport function discoverSshKey(keyExistsFn = existsSync) {\n  const dir = `${homedir()}/.ssh`;\n  for (const name of ['id_ed25519', 'id_rsa']) {\n    const candidate = `${dir}/${name}`;\n    if (keyExistsFn(candidate)) return candidate;\n  }\n  return `${dir}/id_ed25519`;\n}\n\n/** 容器内包 ssh 逃逸宿主，宿主直跑原样返回 */\nexport function buildHostCmd(cmd, inContainer, keyExistsFn) {\n  if (!inContainer) return cmd;\n  const target = process.env.CECELIA_HOST_EXEC_SSH || 'administrator@host.docker.internal';\n  const key = discoverSshKey(keyExistsFn);\n  const quoted = `'${cmd.replace(/'/g, `'\\\\''`)}'`;\n  return `ssh -i ${key} -o StrictHostKeyChecking=no -o UserKnownHostsFile=/dev/null -o BatchMode=yes -o ConnectTimeout=10 ${target} ${quoted}`;\n}\n",
  "packages/brain/src/notion-push-sync.js": "import {syncTaskProgress,findCreatedTaskPage,TASK_PROGRESS_FIELDS} from './projection/task-progress.js';\nimport {syncManagedBodyBlock} from './projection/workflow-body.js';\nimport { notionReq, getToken } from './recurring-notion-sync.js';\nimport { createRoutedTask } from './work-routing-store.js';\nimport { finalizeTask } from './lib/task-terminal.js';\nimport { execFileSync as nodeExecFileSync } from 'child_process';\nimport { sshTargetFor } from './machine-registry.js';\nimport { readDispatchTemplate } from './lib/openclaw-dispatch-template.js';\nimport { computeProgress } from './advancement-progress.js';\nimport { buildWorkflowPageBlocks } from './ops-collector.js';\nimport { pushRegisteredRows, resolveDbId, isPageGoneError, isWrongDatabaseError } from './lib/notion-projection-engine.js';\nimport {formatWorkflowFailure} from './lib/workflow-failure.js';\nimport { OPS_DB_PROPS, buildTaskRunDbProps, buildTasksDbProps, buildStepLinkDbProps, diffMissingProps } from './ops-notion-schema.js';\nimport { buildStepLinkNotionProperties } from './notion-probe-projection.js';\nimport {\n  ensureOpsDbProps, inferProviderFromModelId, pickProviderQuota, buildQuotaProps,\n} from './ops-quota-notion.js';\nimport { PUSH_EXCLUDED_TASK_TYPES } from './lib/task-type-registry.js';\nimport { startRun, finishRun } from './lib/task-run.js';\nimport { SSH_BASE_ARGS } from './lib/ssh-args.js';\nimport { readPageContent } from './lib/notion-page-content.js';\nimport { qiumiSourceFromNotion } from './lib/qiumi-source.js';\nimport { QIUMI_STATUS_MAP } from './lib/qiumi-status-map.js';\nimport { toStartIso, toEndIso, isFuture, scheduledNote } from './lib/qiumi-schedule.js';\nimport { parseEnPage, parseZhPage, GTD_DB_ID, EN_NATIVE_MARK } from './notion-gtd-sync.js';\nimport { TREE_NODES_SQL, treeNodeTable } from './lib/tree-nodes-sql.js';\nimport { observedRun } from './projection/workflow-observation.js';\n\n// journeys / journey_features 不再硬编码库常量：AI Journey / AI Feature 两库 2026-09-19 进回收站，\n// 迁移 480 把注册表两行归档（决策 24a37029：停推，不恢复不重建）。这两张表只认 notion_projection_map\n// 的 active 推送行（resolveDbId），没有就停推——不再每 5 分钟推失败刷 notion_sync_log。\nconst ISSUES_DB  = 'a17c40c2-ba63-82fb-9888-8152cefe29ec';\n// AI Notes DB — decisions 用 Type=Decision，initiative_contracts 用 Type=Contract\nconst DECISIONS_DB           = '185c40c2-ba63-828c-973f-81a9c4582cd6';\nconst INITIATIVE_CONTRACTS_DB = '185c40c2-ba63-828c-973f-81a9c4582cd6';\n\n// Notion 任务编排库（2026-09-13 双向·push 半边接线；库早已存在但 Brain 从未接）\n// PR2 起导出：notion-gtd-sync.js 的 EN_TASKS_DB 需与此同值（Task 4 起改为唯一真源）。\nexport const NOTION_TASKS_DB = 'd5bc40c2-ba63-82ef-965a-8153b7ad81a0';\n// 排单分流 OpenClaw（2026-09-14 v2 数据驱动）：Tasks 库 relation「Workflow」「Agent」\n// 指向运行舱四表的真实 Notion 行（workflows_db/graph_db，见 working_memory.ops_notion_dbs），\n// pull 反查 ops_workflows/ops_agents.notion_id 拿 dispatch 人工列（migration 444）：\n//   workflow.dispatch.webhook_url  = 派发入口（缺省回退 env.N8N_V4_WEBHOOK_URL）\n//   agent.dispatch.template        = 租户任务模板文件名（OPENCLAW_DISPATCH_DIR 下）\n// 禁止在代码里枚举执行方——排单可选项即两张 ops 表本身（决策：主理人 2026-09-14 纠正）。\n\n// 与中文 GTD 表一一对应的英文 Tasks 库 Status（2026-10-10）；与 lib/qiumi-status-map.js 的 en 列保持一致（测试钉住）。\n// pending/archived 不在表里：buildTaskNotionProperties 兜底 Planned。\nexport const TASK_STATUS_TO_NOTION = Object.freeze({\n  queued: 'Queued',\n  in_progress: 'In Progress',\n  blocked: 'Blocked',\n  paused: 'Blocked',\n  quota_exhausted: 'Blocked',\n  pending_postdeploy: 'Blocked',\n  completed: 'Done',\n  completed_no_pr: 'Done',\n  failed: 'Failed',\n  quarantined: 'Failed',\n  dep_failed: 'Failed',\n  canceled: 'Cancelled',\n  cancelled: 'Cancelled',\n});\n\nconst SKILL_REGISTRY_DB  = '353c40c2-ba63-81bf-ae3e-f0e6fa3753d7';\n// 「承诺地图格子」（迁移 479）：旧 Backbone-Step Map 369c… 2026-09-19 进回收站（GET 200 写入 404），09-27 换库\nconst STEP_LINKS_DB      = '3e8c40c2-ba63-8194-a47c-dcf5f4b508bb';\n\n/** 代码硬编码的库常量（brain_table → id）。守夜 A9 断言它们 == notion_projection_map；全绿后 resolveDbId 才翻转为注册表优先。 */\nexport const LEGACY_DB_CONSTANTS = Object.freeze({\n  issues: ISSUES_DB,\n  decisions: DECISIONS_DB, initiative_contracts: INITIATIVE_CONTRACTS_DB,\n  tasks: NOTION_TASKS_DB, skill_registry: SKILL_REGISTRY_DB, activity_cells: STEP_LINKS_DB,\n});\n\n/**\n * 注册表停推提示只在进程内出一次（每表一条）：archived/none 的登记是运维终态，不是瞬时错误，\n * 每 5 分钟刷一遍日志正是 09-19~09-27 那周\"推失败一周无人知\"的噪音来源。\n */\nconst stopNoticed = new Set();\nasync function activePushDbId(pool, table) {\n  const dbId = await resolveDbId(pool, table);\n  if (!dbId && !stopNoticed.has(table)) {\n    stopNoticed.add(table);\n    console.info(`[notion-push-sync] ${table} 停推：注册表无 active 推送行（archived/none，见迁移 480 / 决策 24a37029），本进程不再推`);\n  }\n  return dbId;\n}\n\n// 2026-09-13 实测修复：旧 6 个 ID 对 Notion API 全 404（页面早已不存在），\n// 导致每条 brain/engine issue 推送 404 → isStaleRelationError 静默标已同步\n// （notion_id 为空）= 无声丢弃。真 ID 取自 Sub Area 库\n// 300c40c2-ba63-82d5-9ec1-81990d181950 实查（承诺地图分区），映射按 repo 区归就近价值区。\nconst SUB_AREA_NOTION_IDS = {\n  brain:         '7e7c40c2-ba63-839d-b0bc-017f1cc7d49d', // Cecelia\n  engine:        '7e7c40c2-ba63-839d-b0bc-017f1cc7d49d', // Cecelia\n  cecelia:       '7e7c40c2-ba63-839d-b0bc-017f1cc7d49d', // Cecelia\n  'multi-agent': '7e7c40c2-ba63-839d-b0bc-017f1cc7d49d', // Cecelia\n  zenithjoy:     'cf5c40c2-ba63-82c8-a00a-015c593f6268', // ZenithJoy\n  dashboard:     'a17c40c2-ba63-83e2-b922-8197b09af030', // Dashboard\n};\n\nfunction buildRichText(text) {\n  if (!text) return [];\n  return [{ type: 'text', text: { content: String(text).slice(0, 2000) } }];\n}\n\n/**\n * 把一条 decision 映射成 Notion AI Notes 库的 properties。\n * 纯函数 — 不打 Notion 网络，可独立确定性验证（合同 Golden Path Step 2 oracle）。\n *\n * - level → Level 属性\n * - scope → Scope 属性\n * - ability 的 notion_id → Ability relation（链到对应 ability 页）\n *\n * @param {object} decision  decisions 裸行（含 level/scope/topic/decision...）\n * @param {string|null} abilityNotionId  target ability 的 journey_features.notion_id\n * @param {object} schemaProps  可选：AI Notes 库的 properties schema（{ Level: {type}, Scope: {type} }）。\n *   用于把 Level/Scope 发成库实际属性类型（status vs select）—— 参照 Feature 库 Status 必须用\n *   status 类型的教训（发错类型 Notion 返回 400）。schema 取不到时回退 select。\n */\nexport function buildDecisionNotionProperties(decision = {}, abilityNotionId = null, schemaProps = {}) {\n  const title = decision.topic\n    || (decision.decision ? String(decision.decision).slice(0, 100) : '')\n    || String(decision.id || '');\n  const properties = {\n    Title: { title: [{ text: { content: title } }] },\n    Type: { select: { name: 'Decision' } },\n  };\n  // 按库实际属性类型发 Level/Scope；schema 缺失时默认 select（多数自定义属性为 select）\n  const typedValue = (propName, value) =>\n    schemaProps?.[propName]?.type === 'status'\n      ? { status: { name: value } }\n      : { select: { name: value } };\n  if (decision.level) properties.Level = typedValue('Level', decision.level);\n  if (decision.scope) properties.Scope = typedValue('Scope', decision.scope);\n  // ability relation —— 属性名优先用 schema 里的 relation 字段名，回退 'Ability'\n  if (abilityNotionId) {\n    const relProp = Object.keys(schemaProps || {}).find(\n      (k) => schemaProps[k]?.type === 'relation' && /abilit/i.test(k)\n    ) || 'Ability';\n    properties[relProp] = { relation: [{ id: abilityNotionId }] };\n  }\n  return properties;\n}\n\n// 404 \"Could not find page\" = stale relation ID，永久标记为已同步阻止无限重试\nfunction isStaleRelationError(err) {\n  return err.message && err.message.includes('Could not find page');\n}\n\nasync function logSyncError(pool, errMsg) {\n  await pool.query(\n    `INSERT INTO notion_sync_log (direction, records_synced, records_failed, error_message)\n     VALUES ('to_notion', 0, 1, $1)`,\n    [errMsg]\n  ).catch(() => {});\n}\n\nasync function pushJourneys(pool, token) {\n  const dbId = await activePushDbId(pool, 'journeys');\n  if (!dbId) return;\n  const { rows } = await pool.query(`\n    SELECT j.*, a.notion_id AS area_notion_id\n    FROM ${TREE_NODES_SQL} j\n    LEFT JOIN areas a ON a.id = j.area_id\n    WHERE j.notion_synced_at IS NULL OR j.updated_at > j.notion_synced_at\n    ORDER BY j.notion_synced_at NULLS FIRST, j.updated_at\n    LIMIT 10\n  `);\n  if (rows.length === 0) return;\n  await pushRegisteredRows(pool, token, {\n    table: (j) => treeNodeTable(j.parent_journey_id), dbId, rows, notionReq, logSyncError, isStaleRelationError, isWrongDatabaseError, label: 'journey',\n    buildProps: (j) => {\n      const properties = {\n        Name: { title: [{ text: { content: j.name } }] },\n        Description: { rich_text: buildRichText(j.description) },\n        'Journey Type': { select: { name: j.journey_type } },\n        Maturity: { select: { name: j.maturity } },\n        Status: { select: { name: j.status || 'active' } },\n      };\n      // E2E Test Path 字段在 Notion Journey DB 不存在，不推\n      if (j.area_notion_id) properties['Area'] = { relation: [{ id: j.area_notion_id }] };\n      return properties;\n    },\n  });\n}\nasync function pushJourneyFeatures(pool, token) {\n  const dbId = await activePushDbId(pool, 'journey_features');\n  if (!dbId) return;\n  const { rows } = await pool.query(`\n    SELECT f.*, j.notion_id AS journey_notion_id, a.notion_id AS area_notion_id\n    FROM journey_features f\n    LEFT JOIN ${TREE_NODES_SQL} j ON j.id = f.journey_id\n    LEFT JOIN areas a ON a.id = f.area_id\n    WHERE (f.notion_synced_at IS NULL OR f.updated_at > f.notion_synced_at)\n      AND (f.journey_id IS NULL OR j.notion_id IS NOT NULL)\n    ORDER BY f.notion_synced_at NULLS FIRST, f.updated_at\n    LIMIT 10\n  `);\n  if (rows.length === 0) return;\n  await pushRegisteredRows(pool, token, {\n    table: 'journey_features', dbId, rows, notionReq, logSyncError, isStaleRelationError, isWrongDatabaseError, label: 'feature',\n    buildProps: (f) => {\n      const properties = {\n        Name: { title: [{ text: { content: f.name } }] },\n        // Kind: Notion select 选项首字母大写；DB 小写 → 映射，避免自动创建重复小写选项\n        Kind: { select: { name: (f.kind || 'feature') === 'ability' ? 'Ability' : 'Feature' } },\n        // Status: Notion Feature 库该属性是 status 类型（非 select）\n        Status: { status: { name: f.status || 'planned' } },\n      };\n      if (f.thickness) properties['Thickness'] = { select: { name: f.thickness } };\n      if (f.journey_notion_id) properties['Journey'] = { relation: [{ id: f.journey_notion_id }] };\n      if (f.area_notion_id) properties['Area'] = { relation: [{ id: f.area_notion_id }] };\n      if (f.unit_test_path) properties['Unit Test Path'] = { rich_text: buildRichText(f.unit_test_path) };\n      return properties;\n    },\n  });\n}\n/**\n * Notion Issues 库 Status（status 类型）只有 Open / Triage / In progress / Closed。\n * issues 表历史值有 Backlog / Done / open / closed 等 → 映射到合法选项，未知值归 Open；\n * 否则 400「Invalid status option」每轮重推失败。\n */\nconst ISSUE_NOTION_STATUSES = ['Open', 'Triage', 'In progress', 'Closed'];\nconst ISSUE_STATUS_ALIASES = { backlog: 'Open', done: 'Closed' };\nexport function issueStatusToNotion(status) {\n  const key = String(status || '').trim().toLowerCase();\n  const legal = ISSUE_NOTION_STATUSES.find((s) => s.toLowerCase() === key);\n  return legal || ISSUE_STATUS_ALIASES[key] || 'Open';\n}\n\nexport function buildIssueNotionProperties(issue) {\n  const properties = {\n    Issue: { title: [{ text: { content: issue.title } }] },\n    Priority: { select: { name: issue.priority || 'P2' } },\n    Status: { status: { name: issueStatusToNotion(issue.status) } },\n  };\n  if (issue.sub_area && SUB_AREA_NOTION_IDS[issue.sub_area]) {\n    properties['Sub Area'] = { relation: [{ id: SUB_AREA_NOTION_IDS[issue.sub_area] }] };\n  }\n  return properties;\n}\n\nasync function pushIssues(pool, token) {\n  const { rows } = await pool.query(\n    `SELECT * FROM issues\n      WHERE notion_synced_at IS NULL OR updated_at > notion_synced_at\n      ORDER BY notion_synced_at NULLS FIRST, updated_at LIMIT 10`);\n  if (rows.length === 0) return;\n  const dbId = ISSUES_DB || await resolveDbId(pool, 'issues');\n  await pushRegisteredRows(pool, token, {\n    table: 'issues', dbId, rows, notionReq, logSyncError, isStaleRelationError, isWrongDatabaseError, label: 'issue',\n    buildProps: buildIssueNotionProperties,\n    buildChildren: (issue) => issue.body ? [{\n      object: 'block', type: 'paragraph', paragraph: { rich_text: buildRichText(issue.body) },\n    }] : undefined,\n  });\n}\n/**\n * Brain tasks → Notion Tasks 库（d5bc40c2）。\n * 三条纪律：\n *  1. 范围=活任务(queued/in_progress/blocked)+近7天终态，历史不进驾驶舱；\n *  2. 幂等指纹 notion_props.pushed_status——tasks.updated_at 被 tick 定时 touch\n *     不能当增量判据，status 未变不重推；\n *  3. 13483 条历史 notion_id 是旧时代遗产指向别处：仅当 notion_props 带本指纹\n *     才 PATCH，否则一律 create 新页并覆盖（防打错对象）。\n */\n/**\n * pushTasks 的取数（导出供守卫测试断言，不要内联回去）。\n *\n * device_job 必须排除在外：它是安卓工作机（手机）的活，四台机一天约 90 单，\n * 每单至少 queued→in_progress→completed 三次状态翻转 ≈ 270 次推送。而本查询\n * 每轮只推 LIMIT 10，Notion API 又限流 3 req/s——手机单一旦涌进来就会把投影\n * 窗口整个挤占，连累 harness/决策/任务的 Notion 同步（延迟已实测最长 3090s，\n * 账本债近三天发作过三次）。\n *\n * 手机的活在 Notion 上走**每机每天一条汇总**的独立通道（独立 push 函数 + 独立\n * 日配额），逐单明细只留在工作机页；这里一条都不推。\n */\nconst TASK_RESULT_SQL = `(SELECT COALESCE(jsonb_object_agg(key,value),'{}'::jsonb) FROM jsonb_each(CASE WHEN jsonb_typeof(t.result)='object' THEN t.result WHEN jsonb_typeof(t.result)='string' THEN jsonb_build_object('summary',t.result) ELSE '{}'::jsonb END) WHERE key=ANY(ARRAY[${TASK_PROGRESS_FIELDS.map(key=>`'${key}'`).join(',')}]::text[]))`;\nconst TASK_CONTENT_HASH_SQL = `md5(jsonb_build_array(t.title,t.description,${TASK_RESULT_SQL},t.priority,t.status)::text)`;\nconst TASK_PROJECT_SQL = \"COALESCE(NULLIF(project.notion_props->>'notion_id',''),proj.notion_id)\";\nexport const PUSH_TASKS_QUERY = `\n    SELECT t.id, t.title, t.status, t.priority, t.task_type, t.kind, t.notion_id, t.notion_props,\n           ${TASK_PROJECT_SQL} AS project_notion_id,\n           t.description,t.result,${TASK_CONTENT_HASH_SQL} AS content_hash,\n           blk.ids AS blocker_notion_ids\n      FROM tasks t\n      LEFT JOIN projects project ON project.id=t.project_id\n      LEFT JOIN tasks proj ON proj.id = t.parent_task_id AND proj.task_type = 'project'\n      -- Blocked by：hard 依赖里「已投影且带本系统指纹」的前置任务（旧时代遗产 notion_id 指向别处，不能当 relation 目标）\n      LEFT JOIN LATERAL (\n        SELECT COALESCE(array_agg(b.notion_id ORDER BY b.notion_id), ARRAY[]::text[]) AS ids\n          FROM task_dependencies d\n          JOIN tasks b ON b.id = d.to_task_id\n         WHERE d.from_task_id = t.id\n           AND d.edge_type = 'hard'\n           AND d.gap_id IS NULL\n           AND b.notion_id IS NOT NULL\n           AND (b.notion_props->>'pushed_status') IS NOT NULL\n      ) blk ON true\n     WHERE (\n             (t.notion_props->>'pushed_status') IS DISTINCT FROM t.status\n             -- 根后建页 / 依赖后加：status 没变也要重推（$1=Blocked by 投影未被 flag-off 时才看依赖指纹）\n             OR COALESCE(t.notion_props->>'pushed_project','') IS DISTINCT FROM COALESCE(${TASK_PROJECT_SQL},'')\n             OR (t.notion_props->>'pushed_content') IS DISTINCT FROM ${TASK_CONTENT_HASH_SQL}\n             OR ($1::boolean AND COALESCE(t.notion_props->>'pushed_blockers', '') IS DISTINCT FROM array_to_string(blk.ids, ','))\n           )\n       AND NOT (t.task_type = ANY(ARRAY[${PUSH_EXCLUDED_TASK_TYPES.map((t) => `'${t}'`).join(',')}]::text[]))\n       AND t.task_type <> 'project'\n       AND (\n         t.status IN ('queued','in_progress','blocked')\n         OR (t.status IN ('completed','failed','canceled','cancelled')\n             AND t.updated_at > NOW() - INTERVAL '7 days')\n       )\n     ORDER BY t.updated_at DESC\n     LIMIT 10`;\n\n// ── Tasks 库 Blocked by 投影的 flag-off 状态（链 bf5088a3 棒5·PR B）──────────────────────────\n// 缺列先补；补不上 / 推送含 Blocked by 报错 → 本进程停投影该列一个 TTL（默认 active，条件 SQL 里 $1）。\n// Project 列是库既有列，不在此开关内。\nconst TASKS_PROJECTION_TTL_MS = 10 * 60 * 1000;\nconst tasksProjectionState = { ensuredAt: 0, disabledUntil: 0 };\n\nexport function isTasksBlockedByActive(now = Date.now()) {\n  return now >= tasksProjectionState.disabledUntil;\n}\n\nexport function resetTasksProjectionStateForTest() {\n  tasksProjectionState.ensuredAt = 0;\n  tasksProjectionState.disabledUntil = 0;\n}\n\n/**\n * 缺列即补（幂等）。库的 id 用推送用的同一常量（守夜 A9 断言它 == notion_projection_map 的 tasks 行）。\n * @returns {Promise<boolean>} Blocked by 是否可投影；失败只记日志、进入 TTL 冷却，绝不抛。\n */\nexport async function ensureTasksProjection(pool, token, now = Date.now()) {\n  if (now < tasksProjectionState.disabledUntil) return false;\n  if (now - tasksProjectionState.ensuredAt < TASKS_PROJECTION_TTL_MS && tasksProjectionState.ensuredAt > 0) return true;\n  try {\n    const { added } = await ensureOpsDbProps(token, NOTION_TASKS_DB, buildTasksDbProps(NOTION_TASKS_DB), { notionReq });\n    if (added.length) console.log(`[tasks-push] Tasks 库补列: ${added.join(', ')}`);\n    tasksProjectionState.ensuredAt = now;\n    return true;\n  } catch (err) {\n    tasksProjectionState.disabledUntil = now + TASKS_PROJECTION_TTL_MS;\n    await logSyncError(pool, `[tasks-push] Tasks 库补列失败，Blocked by 投影暂停 10 分钟: ${err.message}`);\n    return false;\n  }\n}\n\nasync function pushTasks(pool, token) {\n  const { rows } = await pool.query(PUSH_TASKS_QUERY, [isTasksBlockedByActive()]);\n  if (rows.length === 0) return;\n  const blockedBy = await ensureTasksProjection(pool, token);\n  await pushTaskRows(pool, token, rows, { blockedBy });\n}\n\n/** 可测内核：对给定行执行推送（导出仅供测试注入行数据） */\nexport async function pushTasksForTest(pool, token, rows, opts = {}) {\n  return pushTaskRows(pool, token, rows, opts);\n}\n\n/**\n * 一个任务 → Notion Tasks 库 properties（纯函数，可独立验证）。\n * Blocked by 只在 blockedBy 开启时发：有前置 → relation；前置被清空（指纹里曾有）→ 发空 relation 清掉；从没有过 → 不发。\n */\nexport function buildTaskNotionProperties(t, { blockedBy = false } = {}) {\n  const notionStatus = TASK_STATUS_TO_NOTION[t.status] || 'Planned';\n  const blockers = Array.isArray(t.blocker_notion_ids) ? t.blocker_notion_ids : [];\n  const hadBlockers = Boolean(t.notion_props?.pushed_blockers);\n  return {\n    Name: { title: [{ text: { content: `[${t.priority || 'P2'}] ${String(t.title || '').slice(0, 180)}` } }] },\n    Status: { status: { name: notionStatus } },\n    // kind 真列（决策 df67a9d6）进 Description 文本，不给 Notion 加列（缺列即整条推送红）；\n    // `brain:<id>` 标记位置不变，各 ingest 用 includes('brain:') 判定不受影响。\n    Description: { rich_text: buildRichText(`${t.task_type || 'task'}${t.kind ? ` · ${t.kind}` : ''} · brain:${t.id}`) },\n    // 接力棒：子任务挂回 Projects 里的根页（根由 notion-relay-projection 推）\n    ...((t.project_notion_id || t.notion_props?.pushed_project) ? { Project: { relation: t.project_notion_id ? [{ id: t.project_notion_id }] : [] } } : {}),\n    // 依赖：Blocked by 自关联（task_dependencies hard 边，前置必须已投影）\n    ...(blockedBy && (blockers.length > 0 || hadBlockers)\n      ? { 'Blocked by': { relation: blockers.map((id) => ({ id })) } }\n      : {}),\n  };\n}\n\nasync function pushTaskRows(pool, token, rows, { blockedBy = false } = {}) {\n  for (const t of rows) {\n    let propertiesComplete=false;\n    try {\n      const properties = buildTaskNotionProperties(t, { blockedBy });\n      // 指纹：status 之外再记 Project 根 / 前置任务集合，根后建页、依赖后加才会重推。\n      // blockedBy 关闭时不碰 pushed_blockers，等列恢复后条件 SQL 会自然把它们重新选出来。\n      const fpProject = t.project_notion_id || '';\n      const fpBlockers = (Array.isArray(t.blocker_notion_ids) ? t.blocker_notion_ids : []).join(',');\n      let fpSql = blockedBy\n        ? `jsonb_build_object('pushed_status', $2::text, 'pushed_project', $3::text, 'pushed_blockers', $4::text)`\n        : `jsonb_build_object('pushed_status', $2::text, 'pushed_project', $3::text)`;\n      const fpParams = blockedBy ? [t.status, fpProject, fpBlockers] : [t.status, fpProject];\n      fpParams.push(t.content_hash || null);\n      fpSql += ` || jsonb_build_object('pushed_content', $${fpParams.length+1}::text)`;\n      const managed = t.notion_props && t.notion_props.pushed_status && t.notion_id;\n      if (managed) {\n        await notionReq(token, `/pages/${t.notion_id}`, 'PATCH', { properties });\n        propertiesComplete=true;\n        await syncTaskProgress(token,t.notion_id,t,notionReq);\n        await pool.query(\n          `UPDATE tasks SET notion_props = COALESCE(notion_props,'{}'::jsonb) || ${fpSql}, notion_synced_at=NOW() WHERE id=$1`,\n          [t.id, ...fpParams],\n        );\n      } else {\n        const recovered=await findCreatedTaskPage(token,NOTION_TASKS_DB,t.id,notionReq);\n        const page = recovered || await notionReq(token, '/pages', 'POST', {\n          parent: { database_id: NOTION_TASKS_DB },\n          properties,\n        });\n        if(recovered)await notionReq(token,`/pages/${page.id}`,'PATCH',{properties});\n        propertiesComplete=true;\n        // 页身份先保存，正文失败重试复用同页，不重复建页。\n        await pool.query(`UPDATE tasks SET notion_id=$2,notion_props=COALESCE(notion_props,'{}'::jsonb)||jsonb_build_object('pushed_status','pending_body') WHERE id=$1`,[t.id,page.id]);\n        await syncTaskProgress(token,page.id,t,notionReq);\n        // 页 id 是 $2，指纹参数顺延一位\n        const createFpSql = fpSql.replace(/\\$(\\d+)::text/g, (_m, n) => `$${Number(n) + 1}::text`);\n        await pool.query(\n          `UPDATE tasks SET notion_id=$2, notion_props = COALESCE(notion_props,'{}'::jsonb) || ${createFpSql}, notion_synced_at=NOW() WHERE id=$1`,\n          [t.id, page.id, ...fpParams],\n        );\n      }\n    } catch (err) {\n      console.warn(`[notion-push-sync] task ${t.id} 推送失败: ${err.message}`);\n      await logSyncError(pool, err.message);\n      // 推送因 Blocked by 列报错：只暂停该列投影，绝不走下面的「清 notion_id 重建」——\n      // 400 会被 isWrongDatabaseError 误判成错库，重建 = 每个有依赖的任务多出一页重复页\n      if (blockedBy && /Blocked by/i.test(err.message)) {\n        tasksProjectionState.disabledUntil = Date.now() + TASKS_PROJECTION_TTL_MS;\n        continue;\n      }\n      // 我方页面被人在 Notion 删除(404)、页/库进回收站(400 archived ancestor)，\n      // 或 legacy id 绑到错库(400 schema 不符) → 清指纹与 id，下轮 create 重建到正确的库\n      if (!propertiesComplete && ((isPageGoneError(err) && t.notion_props?.pushed_status) || isWrongDatabaseError(err))) {\n        await pool.query(\n          `UPDATE tasks SET notion_id=NULL, notion_props = notion_props - 'pushed_status' WHERE id=$1`,\n          [t.id],\n        ).catch(() => {});\n      }\n    }\n  }\n}\n\n/**\n * 拉取 Notion 页面正文（blocks API）作为任务 prompt（2026-09-17；0928 改为全读，见 lib/notion-page-content.js）。\n * 主理人把任务描述写在排单页正文里 → 送达执行体。任何异常都不阻塞排单主流程。\n */\nexport async function fetchNotionPageContent(token, pageId) {\n  try {\n    return await readPageContent(pageId, { request: (path) => notionReq(token, path, 'GET') });\n  } catch (err) {\n    console.warn(`[notion-pull] 页面正文拉取失败 ${pageId}（不阻塞排单）: ${err.message}`);\n    return '';\n  }\n}\n\nconst richText = (arr) => (arr ?? []).map((t) => t.plain_text ?? t.text?.content ?? '').join('');\n\nfunction tenantFor(env, zhDbId) {\n  try {\n    const map = JSON.parse(env.NOTION_TENANT_MAP || '{}');\n    return map[zhDbId] ?? map[String(zhDbId).replace(/-/g, '')] ?? 'default';\n  } catch { return 'default'; }\n}\n\n/** 同步标记不是正文：入账算\"有没有描述\"时必须先把它们摘掉 */\nconst SYNC_MARK_RE = /\\[(?:zh|en):[0-9a-f]{32}\\]|\\[en-native\\]/g;\n\n/**\n * 入账描述兜底。dispatcher pre-flight（pre-flight-check.js）对非系统类型要求\n * description.trim().length >= 20，不够长就是一条 issue → 任务连吃三振进 blocked。\n * 秋米行的\"正文\"经常整条都是同步标记（[zh:<id32>] / [en-native]），摘掉标记后往往剩不下\n * 20 个字，甚至一个字都不剩——那就用标题把描述撑成一句人能读的话，而不是把任务送去撞墙。\n */\nexport function qiumiDescription(rawBody, title, pageId) {\n  const body = String(rawBody ?? '').replace(SYNC_MARK_RE, '').trim().slice(0, 2000);\n  if (body.length >= 20) return body;\n  const label = title || `页 ${pageId}`;\n  const hint = `来自秋米中文任务表「${label}」（${body ? '正文过短' : '页面正文为空'}，按标题执行）`;\n  return [body, hint].filter(Boolean).join(' · ');\n}\n\n/** 英文页 [en:<id32>] 反查中文行（反向回填生成的中文行备注带该标记） */\nasync function findZhPageByEnMark(token, enId32) {\n  const resp = await notionReq(token, `/databases/${GTD_DB_ID}/query`, 'POST', {\n    page_size: 1, filter: { property: '备注', rich_text: { contains: `[en:${enId32}]` } },\n  });\n  return resp?.results?.[0] ?? null;\n}\n\n/**\n * 秋米标记行（[zh:<id32>] 或 [en-native]）→ Brain qiumi_task。\n * 页 id 只进 payload（notion_page_id=英文页，为 458 去重豁免键；notion_zh_page_id=中文页），\n * 绝不写 tasks.notion_id（canonical 投影会覆盖）。tenant 由 NOTION_TENANT_MAP 给。\n */\n/**\n * 委派人：中文「委派人」/英文 Delegated By 写了就用；空着按页面创建者补——人用 Notion 名字，\n * 集成机器人（Agent 经 API 建的行）记「Agent（未标注）」。Agent 委派 Agent 时应自己写上名字。\n */\nasync function resolveDelegator(token, zh, en) {\n  if (zh?.delegatedBy || en.delegatedBy) return { name: zh?.delegatedBy || en.delegatedBy, inferred: false };\n  if (!zh?.createdById) return { name: null, inferred: false };\n  const user = await notionReq(token, `/users/${zh.createdById}`, 'GET').catch(() => null);\n  if (user?.type === 'person' && user.name) return { name: user.name, inferred: true };\n  return { name: user?.type === 'bot' ? 'Agent（未标注）' : null, inferred: true };\n}\n\nasync function ingestQiumiPage(pool, token, page, en, { env, now = () => new Date() }) {\n  const enBody = await fetchNotionPageContent(token, page.id);\n  let zhPage = null;\n  if (en.zhId32) {\n    const zhId = en.zhId32.replace(/^(.{8})(.{4})(.{4})(.{4})(.{12})$/, '$1-$2-$3-$4-$5');\n    zhPage = await notionReq(token, `/pages/${zhId}`, 'GET');\n  } else {\n    zhPage = await findZhPageByEnMark(token, en.id32);\n  }\n  const zh = zhPage ? parseZhPage(zhPage) : null;\n  const zhBody = zh ? await fetchNotionPageContent(token, zh.id) : '';\n  const title = (zh?.title || en.name.replace(/^\\[P[0-3]\\]\\s*/, '')).trim();\n  const priority = zh?.priority ?? (en.name.match(/^\\[(P[0-2])\\]/)?.[1] ?? 'P2');\n  const dueAt = zh?.dueAt ?? en.planDate ?? null;\n  // 预期开始时间 → next_run_at（派发器没到点不派），预期结束时间 → due_at（决策 51c09285）\n  const startIso = toStartIso(zh?.startAt ?? en.planDate ?? null);\n  const endIso = toEndIso(zh?.endAt ?? en.planEnd ?? null);\n  const scheduled = isFuture(startIso, now());\n  const delegator = await resolveDelegator(token, zh, en);\n  const tenantId = zh ? tenantFor(env, env.NOTION_GTD_DB_ID || GTD_DB_ID) : 'default';\n  const routed = await createRoutedTask(pool, {\n    source: 'inbox',\n    source_id: page.id,\n    title,\n    description: qiumiDescription(zhBody || enBody || en.description, title, page.id),\n    requested_task_type: 'qiumi_task',\n    mutation_intent: 'none',\n    declared_domain: 'operations',\n    map_scope_hint: ['F2', 'execution_pool'],\n    metadata: {\n      source: 'notion_gtd',\n      origin: en.zhId32 ? 'zh' : 'en',\n      notion_page_id: page.id,            // 信息字段，不承担去重语义\n      notion_zh_page_id: zh?.id ?? null,\n      dedup_by_notion_page: 'true',       // 461 idx_tasks_dedup_active 豁免键（同名中文行不撞）\n      tenant_id: tenantId,\n      // 第一道闸：门没放开就写 true，任务落地即被 tick 候选 SQL 排除（谓词见 dispatch-helpers.js）。\n      // 放开后写 false（与不写等价），由 dispatcher.dispatchQiumiTask 接管派发。\n      headed_manual: env.QIUMI_DISPATCH_ENABLED !== 'true',\n      qiumi_source: qiumiSourceFromNotion({ title, zh, en, zhBody, enBody, dueAt }),\n      ...(startIso ? { next_run_at: startIso, scheduled_start: startIso } : {}),\n      ...(delegator.name ? { delegated_by: delegator.name } : {}),\n    },\n    task: { priority, status: 'queued', trigger_source: 'manual', executor_kind: 'openclaw-agent' },\n  });\n  const taskId = routed?.task?.id ?? routed?.task_id;\n  if (!taskId) throw new Error('routed_task_id_missing');\n  // due_at 只来自「预期结束时间」：它是截止（手机忙排队的等待上限读它，lib/qiumi-device-busy.js）。\n  // 旧列「预期完成日期」/ 英文 Plan Date 起点现在都是开始时间，落进 due_at 会让任务一忙就判过期。\n  // due_at 是 timestamp without time zone，直接存真实 UTC 时刻（任务 19684870：db.js 全局\n  // setTypeParser 已经把这一类列的读取修正为按 UTC 解析，这里不再需要\"故意存上海墙钟数字、\n  // 靠读取 bug 纠正回来\"的补偿写法——与 recurring.js:111 / decision-executor.js:507 两处\n  // 本来就写真实 UTC 的路径统一语义）。\n  if (endIso) {\n    await pool.query(\n      'UPDATE tasks SET due_at=$2::timestamptz, updated_at=NOW() WHERE id=$1', [taskId, endIso],\n    );\n  }\n  // 458 给 tasks 建了 tenant_id 列，路由账房不认这个字段 → 不补写就恒 NULL，\n  // 按列过滤的看板/查询一条秋米任务都看不见，租户隔离形同虚设。payload 里有不算数。\n  await pool.query('UPDATE tasks SET tenant_id=$2, updated_at=NOW() WHERE id=$1', [taskId, tenantId]);\n  if (zh) {\n    // 任务此刻是 queued → 中文写排队中；没到预期开始时间时结果栏另写已排期提示，到点派发后由回写翻成进行中\n    await notionReq(token, `/pages/${zh.id}`, 'PATCH', { properties: {\n      'OpenClaw任务号': { rich_text: [{ type: 'text', text: { content: `brain:${taskId}` } }] },\n      '状态': { status: { name: QIUMI_STATUS_MAP.queued.zh } },\n      ...(scheduled ? { 'OpenClaw结果': { rich_text: [{ type: 'text', text: { content: scheduledNote(startIso) } }] } } : {}),\n      ...(delegator.inferred && delegator.name ? { '委派人': { select: { name: delegator.name } } } : {}),\n    } });\n  }\n  await writeStatusReceipt(token, page, en.description, `brain:${taskId} ✓已接管`);\n  console.log(`[notion-gtd] 入账 \"${title}\" → qiumi_task ${taskId}`);\n  return { taskId, kind: 'qiumi_task' };\n}\n\n/**\n * 一页 Delegated 的完整接手逻辑（从 pullNotionTasks 抽出；非标记行逐字保持原行为）。\n * 主理人在 Notion 新建行并把 Status 拖到 Delegated 即\"排单\"：\n *  · 只认 Status=Delegated 且 Description 不含 brain: 标记的页（幂等防重复接手）\n *  · 带 [zh:<id32>] 或 [en-native] 标记的秋米行 → 直落 qiumi_task（queued，见 ingestQiumiPage）\n *  · 其余非标记行接手落 status='blocked'——map 扫描器未迁 us-vps 前 kernel 准入不通，\n *    直接 queued 会被 tick 抓去撞墙三连 autoblock；error_message 注明等待路由。\n *    map 刀落地后由 unblock 流程放行。\n *  · notion_props.pushed_status 写入=当前 status，防 pushTasks 反手改用户的 Delegated\n *  · Name 前缀 [P0-3] 解析 priority，缺省 P2；回执 `brain:<id> ✓已接管` PATCH 回页面\n * @returns {{taskId: string|null, kind: 'qiumi_task'|'dev'|'openclaw'|'skipped'}}\n */\nexport async function ingestDelegatedPage(pool, token, page, opts = {}) {\n  const props = page.properties ?? {};\n  const name = richText(props.Name?.title).trim();\n  const desc = richText(props.Description?.rich_text);\n  if (!name) return { taskId: null, kind: 'skipped' };\n  if (/brain:/.test(desc)) return { taskId: null, kind: 'skipped' }; // 已接手，幂等跳过\n  if (/run:notion-/.test(desc)) return { taskId: null, kind: 'skipped' }; // OpenClaw 已派发，幂等跳过\n\n  const en = parseEnPage(page);\n  if (en.zhId32 || en.enNative) {\n    return ingestQiumiPage(pool, token, page, en, { env: opts.env ?? process.env, ...(opts.now ? { now: opts.now } : {}) });\n  }\n\n  // ─── 以下为原 pullNotionTasks 循环体，逐字搬入，非标记行行为不变 ───\n  const wfRelation = (props.Workflow?.relation ?? [])[0]?.id ?? null;\n  if (wfRelation) {\n    // 排班员 v1a·时间窗：Plan Date 在未来 = 意图排期，到点后自然进派发流程\n    const planStart = props['Plan Date']?.date?.start ?? null;\n    if (planStart && new Date(planStart).getTime() > Date.now()) {\n      await writeStatusReceipt(token, page, desc, `🕐 已排期 ${planStart}，到点自动派发`);\n      return { taskId: null, kind: 'skipped' };\n    }\n    await dispatchOpenClawFromNotion({\n      pool, token, page, desc,\n      pageContent: await fetchNotionPageContent(token, page.id),\n      workflowNotionId: wfRelation,\n      agentNotionId: (props.Agent?.relation ?? [])[0]?.id ?? null,\n      env: opts.env ?? process.env,\n      readTemplateFn: opts.readTemplateFn ?? defaultReadTemplate,\n      fetchFn: opts.fetchFn ?? globalThis.fetch,\n      execFn: opts.execFn,\n    });\n    return { taskId: null, kind: 'openclaw' };\n  }\n\n  const m = name.match(/^\\[(P[0-3])\\]\\s*(.+)$/);\n  const priority = m ? m[1] : 'P2';\n  const title = m ? m[2] : name;\n  // 页面正文=主理人写的任务描述/prompt（拉取失败返回 ''，回落固定文案）\n  const pageContent = await fetchNotionPageContent(token, page.id);\n\n  // 建任务必须走原子路由账房（task-creation-inventory 守卫），获得 Routing Receipt。\n  // source_id=Notion 页 id → 账房自带幂等（同页重放拿回同一 task）。\n  // 2026-09-14 实吃第一单踩出的四个路由参数（work-router 硬校验）：\n  // source 枚举无 notion_tasks_db → 归 inbox（主理人收件箱语义）；\n  // mutation_intent 必填（排单默认 write）；repo_hint 必须唯一匹配仓库事实。\n  const routed = await createRoutedTask(pool, {\n    source: 'inbox',\n    source_id: page.id,\n    title,\n    description: pageContent.slice(0, 2000) || '来自 Notion Tasks 编排（主理人排单）',\n    requested_task_type: 'dev',\n    declared_change_kind: 'capability_change',\n    mutation_intent: 'write',\n    repo_hint: 'cecelia',\n    metadata: { source: 'notion_tasks_db', notion_page_id: page.id },\n    map_scope_hint: ['F2', 'execution_pool'],\n    task: { priority, status: 'queued' },\n  });\n  const taskId = routed?.task?.id ?? routed?.task_id;\n  if (!taskId) throw new Error('routed_task_id_missing');\n  // 接手先落 blocked——map 扫描器未迁 us-vps 前 kernel 准入不通，直接 queued\n  // 会被 tick 抓去三连 autoblock；同步写 notion 列与幂等指纹（防 pushTasks\n  // 反手改用户设的 Delegated）。map 刀后由 unblock 放行。\n  await pool.query(\n    `UPDATE tasks SET status='blocked',\n            blocked_at=NOW(),\n            error_message='awaiting_execution_route: map 扫描器迁移后由 unblock 放行',\n            notion_id=$2,\n            notion_props = COALESCE(notion_props,'{}'::jsonb)\n              || jsonb_build_object('pushed_status','blocked','origin','notion'),\n            updated_at=NOW()\n      WHERE id=$1`,\n    [taskId, page.id],\n  );\n  const receipt = `${desc ? desc + ' · ' : ''}brain:${taskId} ✓已接管`;\n  await notionReq(token, `/pages/${page.id}`, 'PATCH', {\n    properties: { Description: { rich_text: [{ type: 'text', text: { content: receipt.slice(0, 1900) } }] } },\n  });\n  console.log(`[notion-pull] 接手排单 \"${title}\" → task ${taskId}`);\n  return { taskId, kind: 'dev' };\n}\n\n/** 只拉带秋米标记的 Delegated 行（notion-gtd-sync 30s 轮用；与 legacy pullNotionTasks 共用入账函数，幂等） */\nexport async function pullMarkedNotionTasks(pool, token, opts = {}) {\n  let ingested = 0; let skipped = 0;\n  for (const mark of ['[zh:', EN_NATIVE_MARK]) {\n    let resp;\n    try {\n      resp = await notionReq(token, `/databases/${NOTION_TASKS_DB}/query`, 'POST', {\n        page_size: 50,\n        filter: { and: [\n          { property: 'Status', status: { equals: 'Delegated' } },\n          { property: 'Description', rich_text: { contains: mark } },\n        ] },\n      });\n    } catch (err) {\n      console.warn(`[notion-gtd] Tasks 库查询失败(${mark}): ${err.message}`);\n      continue;\n    }\n    for (const page of resp?.results ?? []) {\n      try {\n        const r = await ingestDelegatedPage(pool, token, page, opts);\n        if (r.kind === 'qiumi_task') ingested += 1; else skipped += 1;\n      } catch (err) {\n        console.warn(`[notion-gtd] 页面 ${page?.id} 入账失败: ${err.message}`);\n        await logSyncError(pool, err.message);\n      }\n    }\n  }\n  return { ingested, skipped };\n}\n\n/**\n * Notion Tasks 库 → Brain 接手（双向·pull 半边，2026-09-14；PR2 起收敛为对 ingestDelegatedPage 的循环）。\n */\nasync function pullNotionTasks(pool, token, opts = {}) {\n  let resp;\n  try {\n    resp = await notionReq(token, `/databases/${NOTION_TASKS_DB}/query`, 'POST', {\n      page_size: 20,\n      filter: { property: 'Status', status: { equals: 'Delegated' } },\n    });\n  } catch (err) {\n    console.warn(`[notion-pull] Tasks 库查询失败: ${err.message}`);\n    return;\n  }\n  for (const page of resp?.results ?? []) {\n    try {\n      await ingestDelegatedPage(pool, token, page, opts);\n    } catch (err) {\n      console.warn(`[notion-pull] 页面 ${page?.id} 接手失败: ${err.message}`);\n      await logSyncError(pool, err.message);\n    }\n  }\n}\n\n/** 正式入口：由 legacy-notion-push-scheduler 与 push 并联周期调用 */\nexport async function runNotionTaskPull(pool) {\n  const token = getToken();\n  if (!token) return;\n  await pullNotionTasks(pool, token);\n  await syncOpenClawRuns(pool, token);\n  await reapSshWorkflowRuns(pool, token);\n}\n\n// ssh 直派公共参数：定义已抽到 lib/ssh-args.js（终审 I6，解除 executor-contracts.js\n// 对本文件的分层倒置依赖）；本文件仍是原调用方，import 后行为不变。\nfunction defaultSshExec(args) {\n  return nodeExecFileSync('ssh', args, { encoding: 'utf8', timeout: 30_000 });\n}\n\n// 状态回执尾巴（⚠/⏸/🕐/▶）可被下一轮覆盖——剥离后再拼，防 desc 滚雪球\nconst STATUS_TAIL_RE = /\\s*·?\\s*(?:▶ 已派发|⚠ 派发[未失][成败]|⏸ 排队|🕐 已排期)[\\s\\S]*$/;\nfunction stripStatusTail(desc) {\n  return String(desc || '').replace(STATUS_TAIL_RE, '').trim();\n}\n\n/**\n * 状态回执 PATCH——截 base 而非整串，保证尾巴（` · <status>`，含 brain:<id> 标记）\n * 永远完整：长正文时若对 `base + tail` 整串 slice(0,1900)，超长 base 会把尾巴挤出\n * 截断窗口，下一轮 `/brain:/` 判不出已接手 → 每轮重复入账（PR2 审查 Important #1）。\n */\nasync function writeStatusReceipt(token, page, desc, status) {\n  const base = stripStatusTail(desc);\n  const tail = base ? ` · ${status}` : status;\n  const content = `${base.slice(0, Math.max(0, 1900 - tail.length))}${tail}`;\n  await notionReq(token, `/pages/${page.id}`, 'PATCH', {\n    properties: {\n      Description: { rich_text: [{ type: 'text', text: { content } }] },\n    },\n  });\n}\n\nfunction defaultReadTemplate(dir, file) {\n  return readDispatchTemplate(dir, file);\n}\n\n/**\n * OpenClaw 排单派发（relation 版）：Notion relation 页 id → 反查 ops_workflows /\n * ops_agents（notion_id 归一去杠比对）→ dispatch 人工列取入口与模板 →\n * 注入唯一 run_id（内嵌 pageid32 供终态反解）→ POST n8n webhook。\n * 一切缺配置都写 ⚠ 回执到页面（不含幂等标记，修好配置下轮自动重派）。\n */\nasync function dispatchOpenClawFromNotion({\n  pool, token, page, desc, pageContent = '', workflowNotionId, agentNotionId, env, readTemplateFn, fetchFn, execFn: execFnIn,\n}) {\n  const norm = (id) => String(id).replace(/-/g, '');\n  const failReceipt = async (why) => {\n    await writeStatusReceipt(token, page, desc, `⚠ 派发未成(${String(why).slice(0, 80)})`);\n    console.warn(`[notion-pull] OpenClaw 派发未成 page=${page.id}: ${why}`);\n  };\n  // 先建单再派（任务 f38e7cc2）：账先落、再动手——建单失败就不派（否则执行机在跑、Brain 无账）；\n  // 派发失败把刚建的单收成 failed（不留无主 in_progress 镜像，lost-deadline 要 4.5h 才判）。\n  const createRunTask = async (spec) => {\n    try {\n      const created = await createRoutedTask(pool, spec);\n      const id = created?.task_id ?? created?.task?.id ?? null;\n      return id ? { id } : { error: 'no_task_id' };\n    } catch (err) {\n      return { error: err.message };\n    }\n  };\n  const failRunTask = async (taskId, reason) => {\n    try {\n      await finalizeTask(pool, taskId, 'failed', { set: { error_message: reason }, onlyIfStatus: 'in_progress' });\n    } catch (err) {\n      console.warn(`[notion-pull] 派发失败收单异常 task=${taskId}: ${err.message}`);\n    }\n  };\n  // 只认 n8n 业务流程：09-24 起 ops_workflows 也装 Brain 调度 job（source='scheduler'），人在\n  // relation 里误选 ci-patrol 之类不能回退到默认 webhook 真派出去，查不到即走 workflow 不在 ops 的回执\n  const { rows: wfRows } = await pool.query(\n    `SELECT wf_id, name, dispatch FROM ops_workflows WHERE replace(notion_id::text,'-','') = $1 AND source = 'n8n' LIMIT 1`,\n    [norm(workflowNotionId)],\n  );\n  const wf = wfRows[0];\n  if (!wf) return failReceipt('workflow_not_in_ops：所选行不是 n8n 业务流程（Brain 调度 job 不可排单），请改选 source=n8n 的工作流');\n  let agent = null;\n  if (agentNotionId) {\n    const { rows } = await pool.query(\n      `SELECT name, dispatch FROM ops_agents WHERE replace(notion_id::text,'-','') = $1 LIMIT 1`,\n      [norm(agentNotionId)],\n    );\n    agent = rows[0] ?? null;\n    if (!agent) return failReceipt('agent_not_in_ops：所选行不在 ops_agents 账上');\n  }\n  const executorLabel = agent ? `${wf.name}·${agent.name}` : wf.name;\n  // 排班员 v1b·在途互斥：同 workflow 已有 in_progress run（物理资源相同）→ 排队。\n  // Delegated 行本身就是队列：不改 Status，下轮 pull 自动重试 = 资源释放自动放行。\n  const { rows: busyRows } = await pool.query(\n    `SELECT id, payload->>'run_id' AS run_id FROM tasks\n      WHERE task_type='workflow_run' AND status='in_progress'\n        AND payload->>'wf_id' = $1 LIMIT 1`,\n    [wf.wf_id],\n  );\n  if (busyRows[0]) {\n    // 文案禁写 run: 前缀——会命中 pull 幂等跳过正则 /run:notion-/，排队行永不重试（09-14 实证死锁）\n    await writeStatusReceipt(token, page, desc,\n      `⏸ 排队：${wf.name} 在途(${busyRows[0].run_id ?? busyRows[0].id})，完成后自动派发`);\n    return;\n  }\n  // ssh 直派通道（决策 2026-09-15：任务自动填机器直接下派）——直驾线入口。\n  // 派发=目标机 nohup 起后台批，exit code 落 ~/brain-runs/<run_id>.exit 由收割器回收。\n  if (wf.dispatch?.channel === 'ssh') {\n    const machine = wf.dispatch.machine;\n    const command = wf.dispatch.command;\n    if (!machine) return failReceipt(`no_machine：给 ops_workflows(${wf.wf_id}).dispatch 配 machine`);\n    if (!command) return failReceipt(`no_command：给 ops_workflows(${wf.wf_id}).dispatch 配 command`);\n    let target;\n    try { target = sshTargetFor(machine); } catch (err) { return failReceipt(err.message); }\n    const pageId32ssh = String(page.id).replace(/-/g, '');\n    const runIdSsh = `notion-${pageId32ssh}-${Date.now()}`;\n    const exitPath = `~/brain-runs/${runIdSsh}.exit`;\n    const logPath = `~/brain-runs/${runIdSsh}.log`;\n    // 页面正文=执行 prompt：base64 先写达目标机 prompt 文件（base64 经 ssh 传输零注入面），\n    // command 里的 {PROMPT_FILE} 字面量替换为该路径；无占位符则 prompt 文件照写供 command 自取。\n    let promptFile = null;\n    let promptSetup = '';\n    let effectiveCommand = command;\n    if (pageContent) {\n      promptFile = `~/brain-runs/${runIdSsh}.prompt`;\n      const promptB64 = Buffer.from(pageContent).toString('base64');\n      promptSetup = `printf '%s' '${promptB64}' | base64 -d > ${promptFile} && `;\n      effectiveCommand = command.split('{PROMPT_FILE}').join(promptFile);\n    }\n    const remote = `mkdir -p ~/brain-runs && ${promptSetup}nohup sh -c '${effectiveCommand.replace(/'/g, `'\\\\''`)}; echo $? > ${exitPath}' > ${logPath} 2>&1 & echo DISPATCHED`;\n    // execFile 参数数组：remote 作为 ssh 的单个 argv 传递，本地 shell 零解释\n    // （dispatch.command 本就是\"要执行的命令\"数据行，写入权=运维权；这里只堵本地注入面）\n    const sshArgs = [...SSH_BASE_ARGS, target, remote];\n    const execFn = execFnIn ?? defaultSshExec;\n    const runTask = await createRunTask({\n      source: 'inbox',\n      source_id: runIdSsh,\n      title: `[run] ${wf.name}@${machine}`,\n      description: '来自 Notion 排单的直驾 run（ssh 直派）',\n      mutation_intent: 'none',\n      declared_domain: 'operations',\n      requested_task_type: 'workflow_run',\n      metadata: {\n        run_id: runIdSsh, wf_id: wf.wf_id, channel: 'ssh', machine,\n        notion_page_id: page.id, exit_path: `brain-runs/${runIdSsh}.exit`,\n        ...(pageContent ? { prompt_preview: pageContent.slice(0, 500), prompt_file: promptFile } : {}),\n      },\n      task: { status: 'in_progress', priority: 'P2' },\n    });\n    if (!runTask.id) return failReceipt(`建单失败，未派发: ${String(runTask.error).slice(0, 60)}`);\n    try {\n      execFn(sshArgs);\n    } catch (err) {\n      const why = `ssh_dispatch_failed(${machine}): ${String(err.message).slice(0, 60)}`;\n      await failRunTask(runTask.id, why);\n      return failReceipt(why);\n    }\n    // 脚本步 run 原语：一次执行 = 一行 task_runs（fail-open）。终态由 reapSshWorkflowRuns 读 .exit 补齐。\n    await startRun({\n      taskId: runTask.id,\n      runId: runIdSsh,\n      source: 'ssh-workflow',\n      context: { wf_id: wf.wf_id, machine },\n    }, { pool });\n    const baseSsh = stripStatusTail(desc);\n    await notionReq(token, `/pages/${page.id}`, 'PATCH', {\n      properties: {\n        Description: { rich_text: [{ type: 'text', text: { content: `${baseSsh ? baseSsh + ' · ' : ''}▶ 已派发 ${wf.name}@${machine} run:${runIdSsh}`.slice(0, 1900) } }] },\n        Status: { status: { name: 'In Progress' } },\n      },\n    });\n    console.log(`[notion-pull] ssh 直派成功 ${wf.wf_id}@${machine} run=${runIdSsh}`);\n    return;\n  }\n  const webhookUrl = wf.dispatch?.webhook_url || env.N8N_V4_WEBHOOK_URL;\n  if (!webhookUrl) return failReceipt(`no_webhook_url：给 ops_workflows(${wf.wf_id}).dispatch 配 webhook_url`);\n  const template = agent?.dispatch?.template || wf.dispatch?.default_template || null;\n  if (!template) return failReceipt('no_template：给所选 Agent 的 ops_agents.dispatch 配 template（或 workflow 配 default_template）');\n  const dispatchDir = env.OPENCLAW_DISPATCH_DIR || null;\n  let payload;\n  try {\n    payload = readTemplateFn(dispatchDir, template);\n  } catch (err) {\n    return failReceipt(`template_read_failed(${template}): ${err.message}`);\n  }\n  const pageId32 = String(page.id).replace(/-/g, '');\n  const runId = `notion-${pageId32}-${Date.now()}`;\n  payload = { ...payload, run_id: runId, attempt_id: 'a1' };\n  if (pageContent) payload.prompt = pageContent.slice(0, 4000); // 页面正文=执行 prompt 随 webhook 送达\n  const runTask = await createRunTask({\n    source: 'inbox',\n    source_id: runId,\n    title: `[run] ${executorLabel}`,\n    description: '来自 Notion 排单的业务流程 run',\n    mutation_intent: 'none',\n    declared_domain: 'operations',\n    requested_task_type: 'workflow_run',\n    metadata: {\n      run_id: runId, wf_id: wf.wf_id, agent_name: agent?.name ?? null,\n      notion_page_id: page.id,\n    },\n    task: { status: 'in_progress', priority: 'P2' },\n  });\n  if (!runTask.id) return failReceipt(`建单失败，未派发: ${String(runTask.error).slice(0, 60)}`);\n  let ok = false;\n  let detail = '';\n  try {\n    const resp = await fetchFn(webhookUrl, {\n      method: 'POST',\n      headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify(payload),\n      signal: AbortSignal.timeout(90_000),\n    });\n    ok = !!resp?.ok;\n    if (!ok) detail = `http_${resp?.status}`;\n  } catch (err) {\n    detail = err.message;\n  }\n  if (ok) {\n    // 一切执行进 tasks 账（决策 2dbabb48）：run 已先入账 workflow_run；终态由 syncOpenClawRuns 回写。\n    // 脚本步 run 原语（fail-open）：终态由 syncOpenClawRuns 依 ops_runs 回写时补齐。\n    await startRun({\n      taskId: runTask.id,\n      runId,\n      source: 'openclaw-webhook',\n      context: { wf_id: wf.wf_id, agent: agent?.name ?? null },\n    }, { pool });\n  } else {\n    await failRunTask(runTask.id, `webhook_dispatch_failed: ${String(detail).slice(0, 60)}`);\n  }\n  const base = stripStatusTail(desc);\n  const receipt = ok\n    ? `${base ? base + ' · ' : ''}▶ 已派发 ${executorLabel} run:${runId}`\n    : `${base ? base + ' · ' : ''}⚠ 派发失败(${detail.slice(0, 60)})，请重试或联系 Brain`;\n  const properties = {\n    Description: { rich_text: [{ type: 'text', text: { content: receipt.slice(0, 1900) } }] },\n  };\n  if (ok) properties.Status = { status: { name: 'In Progress' } };\n  await notionReq(token, `/pages/${page.id}`, 'PATCH', { properties });\n  console.log(`[notion-pull] OpenClaw 派发${ok ? '成功' : '失败'} ${executorLabel} run=${runId}`);\n}\n\n/**\n * ssh 直派收割器：轮询 in_progress 的 ssh 型 workflow_run，去目标机读\n * ~/brain-runs/<run_id>.exit —— 有 exit code 即收账（0→completed/Done，\n * 非零→failed/Cancelled）；无 exit 且开跑超 6 小时判 failed(timeout)。\n * 目标机零反向依赖：不需要它能回连 Brain，收割是 Brain 主动伸手。\n */\nasync function reapSshWorkflowRuns(pool, token, opts = {}) {\n  const execFn = opts.execFn ?? defaultSshExec;\n  let rows;\n  try {\n    ({ rows } = await pool.query(`\n      SELECT id, payload->>'run_id' AS run_id, payload->>'machine' AS machine,\n             payload->>'notion_page_id' AS notion_page_id,\n             (created_at < NOW() - INTERVAL '6 hours') AS is_stale\n        FROM tasks\n       WHERE task_type='workflow_run' AND status='in_progress'\n         AND payload->>'channel' = 'ssh'\n       LIMIT 20`));\n  } catch (err) {\n    console.warn(`[notion-pull] ssh 收割查询失败: ${err.message}`);\n    return;\n  }\n  for (const r of rows ?? []) {\n    try {\n      let exitCode = null;\n      try {\n        const target = sshTargetFor(r.machine);\n        const out = execFn([...SSH_BASE_ARGS, target, `cat ~/brain-runs/${r.run_id}.exit 2>/dev/null || echo NO_EXIT`]);\n        const trimmed = String(out).trim();\n        if (/^\\d+$/.test(trimmed)) exitCode = parseInt(trimmed, 10);\n      } catch (err) {\n        console.warn(`[notion-pull] ssh 收割 ${r.run_id} 探测失败: ${err.message}`);\n      }\n      let status = null;\n      let note = '';\n      if (exitCode !== null) {\n        status = exitCode === 0 ? 'completed' : 'failed';\n        note = `exit=${exitCode}`;\n      } else if (r.is_stale) {\n        // 时区案（2026-09-15）：判据在 SQL 内比较，禁 JS 解析无时区 created_at\n        status = 'failed';\n        note = 'timeout>6h';\n      }\n      if (!status) continue;\n      await finalizeTask(pool, r.id, status, { mergeResult: { run_status: note }, onlyIfStatus: 'in_progress' });\n      // 脚本步 run 补终态：只认真实 exit（0→success，非 0→failed）；无 exit 仅在 SQL 判定超 6h 时记 timeout，\n      // 未超时探不到 exit 的 run 保持 running（上面 continue），绝不伪造终态。\n      await finishRun({\n        runId: r.run_id,\n        status: exitCode !== null ? (exitCode === 0 ? 'completed' : 'failed') : 'timeout',\n        exitCode: exitCode !== null ? exitCode : undefined,\n        error: exitCode === 0 ? undefined : note,\n      }, { pool });\n      if (r.notion_page_id) {\n        await notionReq(token, `/pages/${r.notion_page_id}`, 'PATCH', {\n          properties: { Status: { status: { name: status === 'completed' ? 'Done' : 'Cancelled' } } },\n        }).catch((err) => console.warn(`[notion-pull] ssh 收割回写 ${r.notion_page_id} 失败: ${err.message}`));\n      }\n      console.log(`[notion-pull] ssh 收割 ${r.run_id} → ${status}(${note})`);\n    } catch (err) {\n      console.warn(`[notion-pull] ssh 收割 ${r.run_id} 失败: ${err.message}`);\n    }\n  }\n}\n\nexport async function reapSshWorkflowRunsForTest(pool, token, opts = {}) {\n  return reapSshWorkflowRuns(pool, token, opts);\n}\n\n/** OpenClaw run 终态 → 反解 page id 推 Notion Status（Done/Cancelled） */\nasync function syncOpenClawRuns(pool, token) {\n  let rows;\n  try {\n    ({ rows } = await pool.query(`\n      SELECT run_id, status FROM ops_runs\n       WHERE run_id LIKE 'notion-%'\n         AND status IN ('success','completed','failed','error','cancelled')\n         AND (stopped_at IS NULL OR stopped_at > NOW() - INTERVAL '2 days')\n       LIMIT 20`));\n  } catch (err) {\n    console.warn(`[notion-pull] ops_runs 查询失败: ${err.message}`);\n    return;\n  }\n  for (const r of rows ?? []) {\n    const m = String(r.run_id).match(/^notion-([0-9a-f]{32})-/);\n    if (!m) continue;\n    const pageId = m[1].replace(/^(.{8})(.{4})(.{4})(.{4})(.{12})$/, '$1-$2-$3-$4-$5');\n    const done = ['success', 'completed'].includes(r.status);\n    // 事件账闭环：workflow_run task 随 run 终态收账（幂等：仅 in_progress 行）\n    try {\n      await finalizeTask(pool, null, done ? 'completed' : 'failed', {\n        mergeResult: { run_status: r.status },\n        onlyIfStatus: 'in_progress',\n        where: { sql: `task_type = 'workflow_run' AND payload->>'run_id' = $1`, params: [r.run_id] },\n      });\n    } catch (err) {\n      console.warn(`[notion-pull] workflow_run task 收账失败 ${r.run_id}: ${err.message}`);\n    }\n    // 脚本步 run 补终态（run 原语，fail-open；已终态不覆盖）\n    await finishRun({\n      runId: r.run_id,\n      status: done ? 'completed' : 'failed',\n      error: done ? undefined : `ops_runs:${r.status}`,\n    }, { pool });\n    try {\n      await notionReq(token, `/pages/${pageId}`, 'PATCH', {\n        properties: { Status: { status: { name: done ? 'Done' : 'Cancelled' } } },\n      });\n    } catch (err) {\n      console.warn(`[notion-pull] run 终态回写 ${pageId} 失败: ${err.message}`);\n    }\n  }\n}\n\n/** 可测导出 */\nexport async function syncOpenClawRunsForTest(pool, token) {\n  return syncOpenClawRuns(pool, token);\n}\n\n/** 可测内核导出（直接注入 token） */\nexport async function pullNotionTasksForTest(pool, token, opts = {}) {\n  return pullNotionTasks(pool, token, opts);\n}\n\n// pushSkillRegistry 已迁出（Skill 台账投影 PR1b，任务 47def5bb）：改由独立 job skill-registry-projection.js 推，\n// 列级分权 + 列账 + 三方基线 + advisory lock；旧实现只推 4 列且挂在无防重入的 setInterval 上。\n\n\n// pushJourneySteps 已摘除（2026-09-19，决策 297ffee5）：journey_steps 自 2026-06-09 废弃只读，\n// 主链却仍每 5 分钟往 AI Steps 推死数据。注册表 notion_projection_map 中该库标 archived/none。\n\n/**\n * journey_step_links → Backbone-Step Map（棒4-2，决策 10a68212）：格子行（cell_kind 非空，承诺地图）与旧连接行一起推，\n * 增量 = 新行 或 updated_at > notion_synced_at（迁移 478 触发器：cell_status 等非记账列变化才抬）。\n * 每轮最多 50 行：283 个格子首推约 30 分钟排空，之后每轮只有翻色的行；指纹不变的行引擎只抬 synced 不打 Notion。\n * 格子列 CellKind/CellKey/CellStatus/AssertionRef + Journey（文本）缺列即补；不要求 step/journey notion_id\n * （AI Steps 已废弃；AI Journey 库 358c… 在回收站，journeys.notion_id 全指向死页，不能做 relation）。\n */\nasync function pushJourneyStepLinks(pool, token) {\n  const { rows } = await pool.query(`\n    SELECT l.*, j.name AS journey_name, s.name AS step_name\n    FROM activity_cells l\n    JOIN ${TREE_NODES_SQL} j ON j.id = l.journey_id\n    LEFT JOIN activities s ON s.id = l.step_id\n    WHERE l.notion_synced_at IS NULL OR l.updated_at > l.notion_synced_at\n    ORDER BY l.updated_at\n    LIMIT 50\n  `);\n  if (rows.length === 0) return;\n  const dbId = STEP_LINKS_DB || await resolveDbId(pool, 'activity_cells');\n  let schemaProps = {};\n  try {\n    // 只读一次 schema：既判 Order 列有无，也算缺列（有缺才 PATCH，不重发已有列）\n    const schema = await notionReq(token, `/databases/${dbId}`, 'GET');\n    schemaProps = { ...(schema?.properties || {}) };\n    const missing = diffMissingProps(schemaProps, buildStepLinkDbProps());\n    const added = Object.keys(missing);\n    if (added.length) {\n      await notionReq(token, `/databases/${dbId}`, 'PATCH', { properties: missing });\n      Object.assign(schemaProps, missing);\n      console.log(`[step_link] Backbone-Step Map 补列: ${added.join(', ')}`);\n    }\n  } catch (err) {\n    await logSyncError(pool, `[step_link] 补列/读 schema 失败: ${err.message}`);\n  }\n  await pushRegisteredRows(pool, token, {\n    table: 'activity_cells', dbId, rows, notionReq, logSyncError, isStaleRelationError, isWrongDatabaseError, label: 'step_link',\n    buildProps: (l) => buildStepLinkNotionProperties(l, schemaProps),\n  });\n}\nasync function pushDecisions(pool, token) {\n  // 三面定稿（决策 297ffee5）：AI Notes 是决策的机器镜子；「决策」库(f93e)是人写入口（PR②b 接 ingest）。\n  // LEFT JOIN journey_features 取 target ability 的 notion_id，供映射成 Notion relation 链\n  const { rows } = await pool.query(\n    `SELECT d.*, jf.notion_id AS ability_notion_id\n       FROM decisions d\n       LEFT JOIN journey_features jf\n         ON jf.id = d.target_id AND d.target_type = 'journey_feature'\n      WHERE (d.notion_synced_at IS NULL OR d.updated_at > d.notion_synced_at)\n        AND d.status <> 'pending'\n      ORDER BY d.notion_synced_at NULLS FIRST, d.updated_at\n      LIMIT 10`\n  );\n  if (rows.length === 0) return;\n  const dbId = DECISIONS_DB || await resolveDbId(pool, 'decisions');\n  // 取一次库 schema：Level/Scope/ability relation 等自定义属性只在库里真实存在时才发，\n  // 否则 Notion 400「is not a property that exists」\n  let schemaProps = {};\n  try {\n    const schema = await notionReq(token, `/databases/${dbId}`, 'GET');\n    schemaProps = schema?.properties || {};\n  } catch {\n    schemaProps = {};\n  }\n  await pushRegisteredRows(pool, token, {\n    table: 'decisions', dbId, rows, notionReq, logSyncError, isStaleRelationError, isWrongDatabaseError, label: 'decision',\n    buildProps: (d) => {\n      const mapped = buildDecisionNotionProperties(d, d.ability_notion_id, schemaProps);\n      const properties = {};\n      for (const [k, v] of Object.entries(mapped)) {\n        if (k === 'Title' || k === 'Type' || k in schemaProps) properties[k] = v;\n      }\n      if (d.created_at) {\n        properties.Date = { date: { start: d.created_at.toISOString?.() || d.created_at } };\n      }\n      return properties;\n    },\n    buildChildren: (d) => {\n      const bodyLines = [\n        d.decision && `**决策**: ${d.decision}`,\n        d.reason && `**原因**: ${d.reason}`,\n        d.category && `**分类**: ${d.category}`,\n      ].filter(Boolean).join('\\n\\n');\n      return bodyLines ? [{ object: 'block', type: 'paragraph', paragraph: { rich_text: buildRichText(bodyLines) } }] : [];\n    },\n  });\n}\nasync function pushInitiativeContracts(pool, token) {\n  const { rows } = await pool.query(\n    `SELECT * FROM initiative_contracts\n      WHERE notion_synced_at IS NULL OR updated_at > notion_synced_at\n      ORDER BY notion_synced_at NULLS FIRST, updated_at LIMIT 10`);\n  if (rows.length === 0) return;\n  const dbId = INITIATIVE_CONTRACTS_DB || await resolveDbId(pool, 'initiative_contracts');\n  await pushRegisteredRows(pool, token, {\n    table: 'initiative_contracts', dbId, rows, notionReq, logSyncError, isStaleRelationError, isWrongDatabaseError, label: 'initiative_contract',\n    buildProps: (ic) => {\n      const title = `Contract ${String(ic.initiative_id).slice(0, 8)} v${ic.version}`;\n      return {\n        Title: { title: [{ text: { content: title } }] },\n        Type: { select: { name: 'Contract' } },\n        ...(ic.approved_at ? { Date: { date: { start: ic.approved_at.toISOString?.() || ic.approved_at } } } : {}),\n      };\n    },\n    buildChildren: (ic) => {\n      const bodyLines = [\n        ic.status && `**状态**: ${ic.status}`,\n        ic.review_rounds != null && `**GAN 轮次**: ${ic.review_rounds}`,\n        ic.prd_content && `**Sprint PRD**:\\n${ic.prd_content.slice(0, 1800)}`,\n      ].filter(Boolean).join('\\n\\n');\n      return bodyLines ? [{ object: 'block', type: 'paragraph', paragraph: { rich_text: buildRichText(bodyLines) } }] : [];\n    },\n  });\n}\nasync function pushAdvancementItems(pool, token) {\n  // ability 页住在 AI Feature 库：该库登记 archived（迁移 480）时 PATCH 只会 404，一并停推\n  const featureDbId = await activePushDbId(pool, 'journey_features');\n  if (!featureDbId) return;\n  // 按 ability 聚合该 ability **全部**推进项的累积进度（非仅未同步子集）——\n  // WHERE 子查询只用来判断\"这个 ability 这一轮有没有变化值得推\"，\n  // 但 COUNT 必须覆盖全量行，否则 done/total 只反映本轮新增/变化的子集，\n  // 会把之前已推的正确进度（如 2/4=50%）覆盖成错误的子集进度（如 0/1=0%）。\n  const { rows } = await pool.query(`\n    SELECT ai.ability_id, jf.notion_id AS ability_notion_id,\n           COUNT(*) FILTER (WHERE ai.status='done')  AS done,\n           COUNT(*) FILTER (WHERE ai.status='doing') AS doing,\n           COUNT(*) FILTER (WHERE ai.status='todo')  AS todo\n    FROM advancement_items ai\n    JOIN journey_features jf ON jf.id = ai.ability_id\n    WHERE jf.notion_id IS NOT NULL\n      AND ai.ability_id IN (\n        SELECT ability_id FROM advancement_items WHERE notion_synced_at IS NULL\n      )\n    GROUP BY ai.ability_id, jf.notion_id\n    LIMIT 10\n  `);\n  if (rows.length === 0) return;\n\n  // 取一次 Feature 库 schema：只有目标属性真实存在才 PATCH，避免对未建列的库 400\n  // （同 pushDecisions 的 schema-check 安全模式）\n  let schemaProps = {};\n  try {\n    const schema = await notionReq(token, `/databases/${featureDbId}`, 'GET');\n    schemaProps = schema?.properties || {};\n  } catch {\n    schemaProps = {};\n  }\n  const progressProp = Object.keys(schemaProps).find((k) => /advancement.*progress/i.test(k));\n\n  for (const r of rows) {\n    try {\n      if (progressProp) {\n        const { done, total, pct } = computeProgress({\n          done: Number(r.done), doing: Number(r.doing), todo: Number(r.todo),\n        });\n        await notionReq(token, `/pages/${r.ability_notion_id}`, 'PATCH', {\n          properties: {\n            [progressProp]: { rich_text: buildRichText(`${done}/${total} 完成 (${pct}%)`) },\n          },\n        });\n      }\n      // 无论是否真的发了 PATCH（属性不存在时跳过），都标记已同步——\n      // 属性缺失是\"Notion 库未建列\"的运维状态，不是\"应无限重试\"的瞬时错误\n      // 已知限制（PR3 前提）：PATCH /api/brain/advancements/:itemId（routes/abilities.js）\n      // 改 status 时不会把 notion_synced_at 重置回 NULL，所以已同步过的推进项状态再变化\n      // 不会触发下一轮重新推送——这需要改 abilities.js 的 PATCH 端点（本 PR 范围外，不动\n      // 现有三个 advancement 端点），留给 PR3 军师上游 producer 一并接线。\n      await pool.query(\n        `UPDATE advancement_items SET notion_synced_at=NOW() WHERE ability_id=$1 AND notion_synced_at IS NULL`,\n        [r.ability_id]\n      );\n    } catch (err) {\n      console.warn(`[notion-push-sync] advancement ability ${r.ability_id} 推送失败: ${err.message}`);\n      await logSyncError(pool, err.message);\n    }\n  }\n}\n\n// ─── ops 运行舱两库（指挥舱 G1 S1 刀1，task 6fcb5356）───────────────────────────\n// DB id 不硬编码：来自 working_memory key='ops_notion_dbs'（scripts/ops/create-ops-notion-dbs.js 一次性写入）。\n// kv 缺失=库未创建（运维状态，静默跳过不刷错误）；value.disabled=true 为终止态（库被删，禁自动重建防平行库）。\n\nexport function isMissingDatabaseError(err) {\n  return !!(err?.message && err.message.includes('Could not find database'));\n}\n\n// 合并单库「Ops 运行图谱」：一行=一个运行单元（agent 或排程），role/workflow/schedule 都是属性。\nexport function buildOpsUnitNotionProperties(u) {\n  const p = {\n    Name: { title: [{ text: { content: String(u.name).slice(0, 200) } }] },\n    Source: { select: { name: u.source } },\n    Machine: { select: { name: u.host_alias } },\n    Status: { select: { name: u.status || 'active' } },\n    Role: { select: { name: u.role || 'solo' } },\n    Repeat: { checkbox: !!u.schedule_desc },          // 有调度=定时重复\n  };\n  // Suspicious（死排程）当前唯一数据源是 recurring_tasks，而 brain_recurring 因 notion_page_id\n  // 已被 recurring-notion-sync 占用不推本库——故 Notion 图谱不设该列（避免恒 false 误导）。\n  // 死排程识别在 /agent-ops/graph API 层保留（Dashboard 刀3 消费），Notion 是过渡展示子集。\n  if (u.agent_type) p.Type = { rich_text: buildRichText(u.agent_type) };\n  if (u.schedule_desc) p.Schedule = { rich_text: buildRichText(u.schedule_desc) };\n  if (u.next_run_utc) p.NextRun = { date: { start: new Date(u.next_run_utc).toISOString() } };\n  if (u.last_seen_at) p.LastSeen = { date: { start: new Date(u.last_seen_at).toISOString() } };\n  // Members/Workflow 是同库 relation，需目标页 id → 第二阶段 buildOpsRelationProperties 补。\n  // Kind 列已删（45/67 为空，信息量太低）。\n  return p;\n}\n\n/**\n * 第二阶段：同库 relation 自关联。Members = 它编排谁（relation → 本库）；\n * Workflow（谁编排它）由 Notion dual_property 反向自动生成，不手工发——\n * 故共享 agent（如 dev 被 main+work-commander 编排）只需两个父各自发一次，\n * dev 那行的 Workflow 自动出现两个值，数据仍只存一份。\n * @param {{name:string, orchestrates?:string[]}} u\n * @param {Map<string,string>} idByName  agent 名 → 已建 Notion 页 id\n */\nexport function buildOpsRelationProperties(u, idByName) {\n  const ids = (u.orchestrates || [])\n    .map((child) => idByName.get(child))\n    .filter(Boolean)                    // 下级页尚未建 → 跳过，不发 undefined id\n    .map((id) => ({ id }));\n  return { CanCall: { relation: ids } }; // 空数组=清掉历史残留关系\n}\n\n\n/** run 记录行（刀6）：一次执行 = 一行。crashed 无耗时则不发 Minutes（禁编造 0）。 */\nexport function buildOpsRunNotionProperties(r, wfName) {\n  const when = r.started_at ? new Date(r.started_at) : null;\n  const label = `${wfName || r.wf_id} · ${when ? when.toISOString().slice(5, 16).replace('T', ' ') : r.run_id}`;\n  const p = {\n    Name: { title: [{ text: { content: label.slice(0, 200) } }] },\n    Status: { select: { name: r.status || 'unknown' } },\n    RunId: { rich_text: buildRichText(String(r.run_id)) },\n  };\n  if (r.machine) p.Machine = { select: { name: r.machine } };\n  if (r.mode) p.Mode = { select: { name: r.mode } };\n  if (typeof r.duration_sec === 'number') p.Minutes = { number: Math.round(r.duration_sec / 60) };\n  if (when) p.StartedAt = { date: { start: when.toISOString() } };\n  return p;\n}\n\nasync function getOpsNotionDbs(pool) {\n  const { rows } = await pool.query(`SELECT value_json FROM working_memory WHERE key = 'ops_notion_dbs'`);\n  return rows[0]?.value_json || null;\n}\n\nasync function disableOpsPush(pool, errMsg) {\n  await pool.query(\n    `UPDATE working_memory SET value_json = value_json || '{\"disabled\":true}'::jsonb, updated_at = NOW()\n     WHERE key = 'ops_notion_dbs'`);\n  await logSyncError(pool, `[ops-push] Notion 库不可访问已停推（终止态，禁自动重建）: ${errMsg}`);\n}\n\nasync function upsertOpsRows(pool, token, { table, dbId, rows, buildProps }) {\n  // 委托统一引擎：指纹同不打 Notion；库不可达 → 停推（终止态，禁自动重建）\n  await pushRegisteredRows(pool, token, {\n    table, dbId, rows, buildProps, notionReq, logSyncError, isStaleRelationError, isWrongDatabaseError,\n    onFatal: (err) => { if (isMissingDatabaseError(err)) { disableOpsPush(pool, err.message).catch(() => {}); return true; } return false; },\n  });\n}\n/**\n * 运行舱专用推送入口（scheduler-jobs 的 ops-notion-push 调这个）。\n *\n * 为什么不复用 runNotionPushSync：那条链的唯一入口是 legacy-notion-push-scheduler，\n * 既没人 import 又要 NOTION_LEGACY_PUSH_ENABLED=true 才跑——等于整条链没接电\n * （2026-09-08 查实：Notion 运行舱四库停更两天就是这个原因）。而启用整条 legacy 链\n * 会连带推 journeys/issues/decisions 等 8 条已被有意停用的投影，风险不可控。\n * 故只把 ops 这一段接到现代调度层。\n */\nexport async function runOpsNotionPush(pool) {\n  let token;\n  try {\n    token = getToken();\n  } catch {\n    return { ok: false, reason: 'no_token' };\n  }\n  // run 投影独立于运行舱四库配置：库未登记时 pushTaskRuns 自己 flag-off 跳过\n  await pushTaskRunsSafe(pool, token);\n  const dbs = await getOpsNotionDbs(pool);\n  if (!dbs?.graph_db) return { ok: false, reason: 'not_configured' };\n  if (dbs.disabled) return { ok: false, reason: 'disabled' };\n  await pushOpsGraph(pool, token);\n  return { ok: true };\n}\n\n/** 四库缺列即补；单库失败只记 sync log 不阻塞（推送本身仍会因缺列 400，下轮再补）。 */\nasync function ensureOpsDbsProps(pool, token, dbs) {\n  const pairs = [\n    ['graph', dbs.graph_db], ['workflows', dbs.workflows_db],\n    ['skills', dbs.skills_db], ['runs', dbs.runs_db],\n  ];\n  for (const [lib, dbId] of pairs) {\n    if (!dbId || !OPS_DB_PROPS[lib]) continue;\n    try {\n      const { added, retitled } = await ensureOpsDbProps(token, dbId, OPS_DB_PROPS[lib], { notionReq, title: lib === 'graph' ? '闹钟总账' : null });\n      if (added.length) console.log(`[ops-push] ${lib} 库补列: ${added.join(', ')}`);\n      if (retitled) console.log(`[ops-push] ${lib} 库改名: 闹钟总账`);\n    } catch (err) {\n      await logSyncError(pool, `[ops-push] ${lib} 库补列失败: ${err.message}`);\n    }\n  }\n}\n\n// 合并推送：agent 行（带 role/workflow/合并调度）+ 孤儿排程行，全推同一个 graph_db。\nasync function pushOpsGraph(pool, token) {\n  const dbs = await getOpsNotionDbs(pool);\n  if (!dbs?.graph_db || dbs.disabled) return;\n\n  // 0. 缺列即补（幂等）：ops-notion-schema 的列定义此前只在新建库时生效，既有库加列\n  //    （如刀2 配额三列）推送会 400 被逐行 catch 吞掉 → 静默停更。每轮先补，只发缺的。\n  await ensureOpsDbsProps(pool, token, dbs);\n\n  // 0.5 模型账号配额（刀2）：agent 行按 meta.model 的 provider 取该 provider 最紧张账号。\n  //     表不存在/查询失败 → 空数组，不影响其余推送。\n  let modelAccounts = [];\n  try {\n    modelAccounts = (await pool.query(\n      `SELECT account_id, provider, status, five_hour_pct, seven_day_pct, last_checked_at FROM ops_model_accounts`,\n    )).rows;\n  } catch (err) {\n    await logSyncError(pool, `[ops-push] ops_model_accounts 读取失败（配额列本轮留空）: ${err.message}`);\n  }\n\n  // 全局：算 orchestrated_by（child→[parents]）+ active schedule 索引（供 agent 行合并 + 孤儿判定）\n  const allAgents = (await pool.query(`SELECT name, meta FROM ops_agents`)).rows;\n  const orchestratedBy = new Map();\n  for (const a of allAgents) {\n    for (const child of a.meta?.orchestrates || []) {\n      if (!orchestratedBy.has(child)) orchestratedBy.set(child, []);\n      orchestratedBy.get(child).push(a.name);\n    }\n  }\n  const allSched = (await pool.query(`SELECT * FROM ops_schedule_entries WHERE active = TRUE`)).rows;\n  const schedByKey = new Map(allSched.map((s) => [`${s.source}|${s.host_alias}|${s.label}`, s]));\n  const agentKeys = new Set((await pool.query(`SELECT source, host_alias, name FROM ops_agents`)).rows\n    .map((a) => `${a.source}|${a.host_alias}|${a.name}`));\n\n  // 1. agent 行（合并对应调度）\n  const agentRows = (await pool.query(\n    `SELECT * FROM ops_agents\n     WHERE notion_synced_at IS NULL OR updated_at > notion_synced_at\n     ORDER BY updated_at LIMIT 50`)).rows;\n  await upsertOpsRows(pool, token, {\n    table: 'ops_agents', dbId: dbs.graph_db, rows: agentRows,\n    buildProps: (a) => {\n      const orchestrates = a.meta?.orchestrates || [];\n      const parents = orchestratedBy.get(a.name) || [];\n      const sched = schedByKey.get(`${a.source}|${a.host_alias}|${a.name}`);\n      const quota = pickProviderQuota(modelAccounts, inferProviderFromModelId(a.meta?.model));\n      return {\n        ...buildOpsUnitNotionProperties({\n          source: a.source, host_alias: a.host_alias, name: a.name, agent_type: a.agent_type,\n          status: a.status, last_seen_at: a.last_seen_at,\n          role: orchestrates.length ? 'orchestrator' : (parents.length ? 'member' : 'solo'),\n          orchestrated_by: parents,\n          kind: sched?.kind ?? null, schedule_desc: sched?.schedule_desc ?? null, next_run_utc: sched?.next_run_utc ?? null,\n        }),\n        ...buildQuotaProps(quota),\n      };\n    },\n  });\n\n  // 2. 孤儿排程行（无对应 agent，如 gha）→ 独立行 role=scheduled\n  const orphanRows = (await pool.query(\n    // 闹钟总账自有行（Brain job/recurring 落表行、盘点静态快照）不是\"运行图谱\"里的运行单元，不推——\n    // 否则 70+ 行 job 每分钟刷新 updated_at 会把本查询的 LIMIT 50 吃光（任务 fe10d1a0，Notion 推送另立任务）。\n    `SELECT * FROM ops_schedule_entries\n     WHERE active = TRUE AND (notion_synced_at IS NULL OR updated_at > notion_synced_at)\n       AND source <> 'inventory-20261004'\n       AND COALESCE(registered_via, '') NOT IN ('brain-job', 'brain-loop', 'recurring')\n     ORDER BY updated_at LIMIT 50`)).rows\n    .filter((s) => !agentKeys.has(`${s.source}|${s.host_alias}|${s.label}`));\n  await upsertOpsRows(pool, token, {\n    table: 'ops_schedule_entries', dbId: dbs.graph_db, rows: orphanRows,\n    buildProps: (s) => buildOpsUnitNotionProperties({\n      source: s.source, host_alias: s.host_alias, name: s.label, agent_type: 'schedule',\n      status: 'active', role: 'scheduled', orchestrated_by: [],\n      schedule_desc: s.schedule_desc, next_run_utc: s.next_run_utc,\n    }),\n  });\n\n  // 3. relation 阶段：所有页建完后，给编排者补 Members（同库自关联）。\n  // 必须在建页之后——relation 需要目标页的 notion_id。Workflow（反向）由 Notion 自动生成。\n  await syncOpsMembersRelation(pool, token);\n  await pushOpsWorkflows(pool, token);   // 业务流程库（刀4）\n  await pushOpsRuns(pool, token);        // run 记录库（刀6）\n  await pushOpsSkills(pool, token);      // 技能池（此前无任何推送代码，靠手动灌数据）\n}\n\n// ─── 技能池「Ops Skills」──────────────────────────────────\n// 此前这个库只存在于 Notion：19 条 notion_id 是早前一次性手动脚本灌的，\n// 仓库里没有任何代码维护它——与 Notion 停更同一类病（手动做的事没固化）。\nasync function pushOpsSkills(pool, token) {\n  const dbs = await getOpsNotionDbs(pool);\n  if (!dbs?.skills_db || dbs.disabled) return;\n  const rows = (await pool.query(\n    `SELECT * FROM ops_skills\n     WHERE notion_synced_at IS NULL OR updated_at > notion_synced_at\n     ORDER BY updated_at LIMIT 50`)).rows;\n  await upsertOpsRows(pool, token, {\n    table: 'ops_skills', dbId: dbs.skills_db, rows,\n    buildProps: buildOpsSkillNotionProperties,\n  });\n}\n\n// ─── 业务流程库「Ops Workflows」（刀4）────────────────────────────────\n// 与图谱库的区别：workflow=业务流程（智能获客8阶段），agent=执行资源。\n// 主理人 2026-09-06 纠正：allowAgents 是\"谁能召唤谁\"的权限，不是 workflow。\n\nexport function buildOpsWorkflowNotionProperties(w) {\n  const p = {\n    Name: { title: [{ text: { content: String(w.name).slice(0, 200) } }] },\n    Source: { select: { name: w.source || 'n8n' } },  // 采集器行未带 source 时按来源默认\n    Active: { checkbox: w.active === true },\n    Stages: { number: w.stage_count ?? 0 },\n  };\n  const stages = w.meta?.stages || [];\n  if (stages.length) p.Flow = { rich_text: buildRichText(stages.join(' → ')) }; // 流程长什么样\n  // 健康汇总（刀6）：无 run 数据时不发，避免显示假 0\n  if (w.machine) p.Machine = { select: { name: w.machine } };\n  if (typeof w.run_total === 'number') p.Runs = { number: w.run_total };\n  if (typeof w.run_success_rate === 'number') p.SuccessRate = { number: w.run_success_rate };\n  if (typeof w.run_avg_sec === 'number') p.AvgMinutes = { number: Math.round(w.run_avg_sec / 60) };\n  if (w.last_run_at) p.LastRun = { date: { start: new Date(w.last_run_at).toISOString() } };\n  if (w.last_run_status) p.LastStatus = { select: { name: w.last_run_status } };\n  if (w.node_count != null) p.Nodes = { number: w.node_count };\n  if (w.wf_id) p.WfId = { rich_text: buildRichText(w.wf_id) };\n  // 活性（443）：看板要一眼看出\"还会不会跑\"，不能让人拿最后运行时间自己去减。\n  // 起因：业务流程停跑 20.4 小时，四表全绿因为它们只答\"跑过多少次\"。\n  if (w.liveness) {\n    p.Liveness = { select: { name: LIVENESS_LABEL[w.liveness] || LIVENESS_LABEL.cold } };\n    if (typeof w.silent_sec === 'number') {\n      p.SilentFor = { rich_text: buildRichText(formatSilentFor(w.silent_sec)) };\n    }\n  }\n  // 人工列（owner/note/priority/starred/enable_intent）一律不发：\n  // Notion 是它们的真相源，推回去会把主理人刚改的冲掉。\n  return p; // Agents（跨库 relation）第二阶段补\n}\n\n/** 活性灯：手机上扫一眼就能挑出红的 */\nconst LIVENESS_LABEL = {\n  ok: '🟢 正常',\n  warn: '🟡 放缓',\n  dead: '🔴 失联',\n  cold: '⚪ 数据不足',\n};\n\n/** 静默时长按量级换单位——固定用小时会出现\"停了 0.0 小时\"这种废话 */\nexport function formatSilentFor(sec) {\n  const s = Number(sec);\n  if (!Number.isFinite(s) || s < 0) return '';\n  if (s < 60) return `停了 ${Math.round(s)} 秒`;\n  if (s < 3600) return `停了 ${Math.round(s / 60)} 分钟`;\n  if (s < 86400) return `停了 ${(s / 3600).toFixed(1)} 小时`;\n  return `停了 ${(s / 86400).toFixed(1)} 天`;\n}\n\n/**\n * 技能池机器列。人工列（Stage/Owner/Note/Priority/Starred）一律不发——\n * Stage 正是主理人推翻自动判定的地方，推回去就把人改的冲掉了。\n */\nexport function buildOpsSkillNotionProperties(s) {\n  const p = {\n    Name: { title: [{ text: { content: String(s.name ?? '').slice(0, 200) } }] },\n    Source: { select: { name: s.source || 'openclaw' } },\n    UsedBy: { number: Array.isArray(s.used_by) ? s.used_by.length : 0 },\n  };\n  if (s.generation != null) p.Generation = { number: s.generation };\n  if (typeof s.eval_score === 'number') p.EvalScore = { number: s.eval_score };\n  // 无运行数据的不发假 0——19 个 skill 里 17 个还没有阶段归因数据\n  if (typeof s.runs === 'number') p.Runs = { number: s.runs };\n  if (typeof s.run_success_rate === 'number') p.SuccessRate = { number: s.run_success_rate };\n  if (typeof s.run_avg_sec === 'number') p.AvgSeconds = { number: s.run_avg_sec };\n  if (s.disco_stage) p.DiscoStage = { select: { name: s.disco_stage } };\n  // 判定依据必须一起给：只给档位不给理由，人没法判断该不该推翻它\n  if (s.stage_reason) p.StageReason = { rich_text: buildRichText(String(s.stage_reason).slice(0, 500)) };\n  // 探针未知（null）不发——false 会被误读成\"已确认没有探针\"\n  if (typeof s.has_postcondition === 'boolean') p.HasProbe = { checkbox: s.has_postcondition };\n  return p;\n}\n\n/** DisCo 合法档位——人工覆盖只认这三个，乱填一律忽略免得把档位写脏 */\nconst VALID_STAGES = new Set(['software3', 'disco', 'code']);\n\n/**\n * 从 Notion 页面读回**人工列**。机器列即使人改了也一概不读——\n * 它们的真相源在 n8n/OpenClaw，下一轮推送会覆盖回去。\n * 空值读成 null（不是 undefined）：人主动清空一个字段必须能传达到 Brain。\n */\nexport function buildOpsManualReadback(page) {\n  const props = page?.properties;\n  if (!props || typeof props !== 'object') return {};\n  const out = {};\n  const text = (k) => {\n    const rt = props[k]?.rich_text;\n    if (!Array.isArray(rt)) return undefined;\n    const v = rt.map((x) => x?.plain_text ?? '').join('').trim();\n    return v || null;\n  };\n  const select = (k) => {\n    if (!(k in props)) return undefined;\n    return props[k]?.select?.name ?? null;\n  };\n  const check = (k) => (typeof props[k]?.checkbox === 'boolean' ? props[k].checkbox : undefined);\n\n  const owner = text('Owner'); if (owner !== undefined) out.owner_manual = owner;\n  const note = text('Note'); if (note !== undefined) out.note_manual = note;\n  const org = text('Org'); if (org !== undefined) out.org_manual = org;\n  const role = text('RoleManual'); if (role !== undefined) out.role_manual = role;\n  const prio = select('Priority'); if (prio !== undefined) out.priority_manual = prio;\n  const star = check('Starred'); if (star !== undefined) out.starred = star;\n  const stage = select('Stage');\n  if (stage !== undefined && (stage === null || VALID_STAGES.has(stage))) out.stage_manual = stage;\n  const enabled = check('Enabled'); if (enabled !== undefined) out.enable_intent = enabled;\n  return out;\n}\n\n/** 生效档位：人工优先，人工空则用自动判定值 */\nexport function effectiveStage(skill = {}) {\n  return skill.stage_manual ?? skill.disco_stage ?? null;\n}\n\n/** workflow → 它用到的 agent（跨库 relation 指向图谱库） */\nexport function buildWorkflowAgentsRelation(w, agentIdByName) {\n  const ids = (w.uses_agents || [])\n    .map((n) => agentIdByName.get(n))\n    .filter(Boolean)\n    .map((id) => ({ id }));\n  return { Agents: { relation: ids } };\n}\n\nasync function pushOpsWorkflows(pool, token) {\n  const dbs = await getOpsNotionDbs(pool);\n  if (!dbs?.workflows_db || dbs.disabled) return;\n  const { rows } = await pool.query(\n    `SELECT * FROM ops_workflows\n     WHERE notion_synced_at IS NULL OR updated_at > notion_synced_at\n     ORDER BY updated_at LIMIT 50`);\n  const dbId = dbs.workflows_db || await resolveDbId(pool, 'ops_workflows');\n  // 建页时带正文 children（流程图 mermaid + 阶段清单 + 画布构成）；raw 画布存 meta.raw_nodes\n  await pushRegisteredRows(pool, token, {\n    table: 'ops_workflows', dbId, rows, notionReq, logSyncError, isStaleRelationError, isWrongDatabaseError, label: 'workflow',\n    buildProps: (w) => buildOpsWorkflowNotionProperties(w),\n    buildChildren: (w) => (w.meta?.canvas ? buildWorkflowPageBlocks(w.meta.canvas, w) : undefined),\n    onFatal: (err) => { if (isMissingDatabaseError(err)) { disableOpsPush(pool, err.message).catch(() => {}); return true; } return false; },\n  });\n  // 跨库 relation：workflow → agent（需图谱库页 id）\n  const agentIdByName = new Map(\n    (await pool.query(`SELECT name, notion_id FROM ops_agents WHERE notion_id IS NOT NULL`)).rows\n      .map((r) => [r.name, r.notion_id]));\n  const withAgents = (await pool.query(\n    `SELECT wf_id, uses_agents, notion_id FROM ops_workflows\n     WHERE notion_id IS NOT NULL AND jsonb_array_length(uses_agents) > 0`)).rows;\n  for (const w of withAgents) {\n    try {\n      const props = buildWorkflowAgentsRelation(w, agentIdByName);\n      if (!props.Agents.relation.length) continue;\n      await notionReq(token, `/pages/${w.notion_id}`, 'PATCH', { properties: props });\n    } catch (err) {\n      if (isMissingDatabaseError(err)) return;\n      console.warn(`[notion-push-sync] workflow relation ${w.wf_id} 失败: ${err.message}`);\n      await logSyncError(pool, err.message);\n    }\n  }\n}\n\n\n/**\n * run 推送（刀6）：只推**业务流程**的 run（有阶段的，日均 10-21 轮）；\n * 通道/触发器类（日均 154-234 次、4 秒一次）只在流程行上看汇总，不推明细——\n * 否则 2800 条 4 秒记录会把视线淹没（主理人 2026-09-06 定调）。\n */\nasync function pushOpsRuns(pool, token) {\n  const dbs = await getOpsNotionDbs(pool);\n  if (!dbs?.runs_db || dbs.disabled) return;\n  // ops_runs 无 updated_at：run 记录只增不改，保持 IS NULL 增量\n  const { rows } = await pool.query(\n    `SELECT r.*, w.name AS wf_name\n     FROM ops_runs r\n     JOIN ops_workflows w ON w.source = r.source AND w.wf_id = r.wf_id\n     WHERE w.stage_count > 0 AND r.notion_synced_at IS NULL\n     ORDER BY r.started_at DESC LIMIT 100`);\n  if (rows.length === 0) return;\n  const dbId = dbs.runs_db || await resolveDbId(pool, 'ops_runs');\n  await upsertOpsRows(pool, token, {\n    table: 'ops_runs', dbId, rows, buildProps: (r) => buildOpsRunNotionProperties(r, r.wf_name),\n  });\n}\n/** 给有召唤权限的 agent 补 CanCall relation（同库自关联，反向=CalledBy）。目标页未建则下轮自愈。 */\nasync function syncOpsMembersRelation(pool, token) {\n  const { rows } = await pool.query(\n    `SELECT name, meta, notion_id FROM ops_agents WHERE notion_id IS NOT NULL`);\n  const idByName = new Map(rows.map((r) => [r.name, r.notion_id]));\n  const orchestrators = rows.filter((r) => (r.meta?.orchestrates || []).length > 0);\n  for (const o of orchestrators) {\n    try {\n      const props = buildOpsRelationProperties({ name: o.name, orchestrates: o.meta.orchestrates }, idByName);\n      if (!props.CanCall.relation.length) continue; // 下级页全未建，等下轮\n      await notionReq(token, `/pages/${o.notion_id}`, 'PATCH', { properties: props });\n    } catch (err) {\n      if (isMissingDatabaseError(err)) return;      // 库没了，停推（终止态）\n      console.warn(`[notion-push-sync] ops relation ${o.name} 失败: ${err.message}`);\n      await logSyncError(pool, err.message);\n    }\n  }\n}\n\n/**\n * task_runs 行 → Notion 「Runs」库 properties：一次执行一行，开始/结束/exit/产物人可见。\n * 没发生的事不编造：running 行无 EndedAt/ExitCode/Minutes。\n */\nexport function buildTaskRunNotionProperties(r) {\n  const observed = observedRun(r, { script: r.script });\n  const started = r.started_at ? new Date(r.started_at) : null;\n  const ended = r.ended_at ? new Date(r.ended_at) : null;\n  const source = r.context?.source || null;\n  const label = `${r.task_title || r.task_id} · ${started ? started.toISOString().slice(5, 16).replace('T', ' ') : r.run_id}`;\n  const p = {\n    Name: { title: [{ text: { content: label.slice(0, 200) } }] },\n    Status: { select: { name: r.status || 'unknown' } },\n    TaskId: { rich_text: buildRichText(String(r.task_id)) },\n    RunId: { rich_text: buildRichText(String(r.run_id)) },\n  };\n  if (source) p.Source = { select: { name: String(source).slice(0, 100) } };\n  if (started) p.StartedAt = { date: { start: started.toISOString() } };\n  if (ended) p.EndedAt = { date: { start: ended.toISOString() } };\n  const exit = r.result?.exit_code;\n  if (exit !== undefined && exit !== null && Number.isFinite(Number(exit))) p.ExitCode = { number: Number(exit) };\n  const artifacts = Array.isArray(r.result?.artifacts) ? r.result.artifacts : [];\n  if (artifacts.length) p.Artifacts = { rich_text: buildRichText(artifacts.join(', ').slice(0, 1900)) };\n  if (started && ended) p.Minutes = { number: Math.round((ended.getTime() - started.getTime()) / 60000) };\n  const failureText=formatWorkflowFailure(observed.failure);\n  const historicalError=[r.error_message?String(r.error_message).slice(0,500):null,\n    ['failed','timeout'].includes(observed.status)&&!observed.failure?'具体原因未知（该次运行未保存失败证据）':null].filter(Boolean).join(' · ');\n  if (failureText||historicalError) p.Error = { rich_text: buildRichText(failureText||historicalError) };\n  if (r.workflow_page_id) p.Workflow = { relation: [{ id: r.workflow_page_id }] };\n  if (r.task_page_id) p.Task = { relation: [{ id: r.task_page_id }] };\n  p['业务状态'] = { select: { name: observed.status } };\n  for (const [column, key] of Object.entries({ '流程版本': 'workflow_version', '定义版本': 'definition_version_id',\n    '源码版本': 'source_revision', '辅助源码版本': 'control_source_revision', '设备': 'phone_serial', '批次任务': 'batch_task_id' })) {\n    p[column] = { rich_text: buildRichText(String(observed[key] || '未知')) };\n  }\n  p['尝试'] = { number: Number.isFinite(Number(observed.attempt)) && observed.attempt != null ? Number(observed.attempt) : null };\n  return p;\n}\n\nconst RUN_SOURCE_MARKER='🤖 运行源码（机器维护';\n/** 只展示该Run冻结事实；绝不用当前Workflow填补历史。 */\nexport function buildTaskRunNotionBodyBlock(row){\n const run=observedRun(row,{script:row.script});\n const sources={...run,control_source_revision:row.context?.workflow_snapshot?.control_source_revision||'未知'};\n const lines=[`定义版本：${run.definition_version_id}`,`流程版本：${run.workflow_version}`,\n  ...Object.entries({'执行入口源码':'entry_source_revision','手机执行源码':'phone_source_revision','控制器源码':'control_source_revision','定义来源':'definition_source_revision'})\n   .map(([label,key])=>`${label}：${sources[key]}`)].join('\\n');\n return {object:'block',type:'toggle',toggle:{rich_text:buildRichText(`${RUN_SOURCE_MARKER}：改事实请改 Brain）`),\n  children:[{object:'block',type:'paragraph',paragraph:{rich_text:buildRichText(lines)}}]}};\n}\n\n/**\n * task_runs 投影面（链 bf5088a3 棒1）：库在 notion_projection_map 登记为 push+active 才推，\n * 未登记（Notion「Runs」库尚未建，占位行为 pending_vessel）→ 整个跳过（flag-off 安全）。\n * 推前缺列即补（Notion 缺列 400 的血训）；失败只记日志，DB（task_runs）才是真相源。\n */\nasync function pushTaskRuns(pool, token) {\n  const dbId = await resolveDbId(pool, 'task_runs');\n  if (!dbId) return;\n  const directory = (await pool.query(\"SELECT config FROM projection_targets WHERE target='notion-directory' AND enabled=true\")).rows[0];\n  const taskTargets = (await pool.query(`SELECT notion_db_id FROM notion_projection_map\n    WHERE brain_table = 'tasks' AND title = 'Tasks' AND face = 'inlet' AND direction = 'both' AND status = 'active'`)).rows;\n  if (taskTargets.length > 1) throw new Error('Tasks 正式投影库身份不唯一');\n  const workflowsDb = directory?.config?.dbs?.workflows;\n  const tasksDb = taskTargets[0]?.notion_db_id;\n  const props = buildTaskRunDbProps({ workflowsDb, tasksDb });\n  try {\n    const checkSchemaReq = async (...args) => {\n      const response = await notionReq(...args);\n      if (args[1] === `/databases/${dbId}` && args[2] === 'GET') {\n        for (const [name, expected] of Object.entries(props)) {\n          const existing = response.properties?.[name];\n          if (!existing) continue;\n          const type = Object.keys(expected)[0];\n          if (existing.type !== type || type === 'relation' &&\n            String(existing.relation?.database_id || '').replaceAll('-', '') !== expected.relation.database_id.replaceAll('-', '')) {\n            throw new Error(`Runs 属性身份冲突：${name}`);\n          }\n        }\n      }\n      return response;\n    };\n    const { added } = await ensureOpsDbProps(token, dbId, props, { notionReq: checkSchemaReq });\n    if (added.length) console.log(`[task-runs-push] Runs 库补列: ${added.join(', ')}`);\n  } catch (err) {\n    await logSyncError(pool, `[task-runs-push] Runs 库补列失败: ${err.message}`);\n    return; // schema身份未证实，禁止把Run写进错误关系目标。\n  }\n  const { rows } = await pool.query(\n    `SELECT r.*, t.title AS task_title, t.notion_id AS task_page_id, pl.external_id AS workflow_page_id,\n            jsonb_build_object('id',v.id,'version',v.payload->'contract'->>'version','source_commit',v.source_commit) AS definition_version,\n            jsonb_build_object('run_id',t.result->'script'->>'run_id','stdout',t.result->'script'->>'stdout') AS script\n       FROM task_runs r\n       JOIN tasks t ON t.id = r.task_id\n       LEFT JOIN run_definition_bindings b ON b.run_id=r.run_id AND b.workflow_id=r.workflow_id\n       LEFT JOIN workflow_definition_versions v ON v.id=b.workflow_definition_version_id AND v.workflow_id=b.workflow_id\n       LEFT JOIN projection_links pl ON pl.target='notion-directory' AND pl.entity_type='workflows'\n         AND (pl.entity_id=r.workflow_id OR (r.workflow_id IS NULL AND pl.entity_id::text=t.payload->>'workflow_id'\n           AND (NOT COALESCE(r.context->'workflow_snapshot' ? 'workflow_id',false) OR lower(r.context->'workflow_snapshot'->>'workflow_id')=pl.entity_id::text)))\n      WHERE r.notion_id IS NULL OR r.notion_synced_at IS NULL OR r.updated_at > r.notion_synced_at\n         OR pl.external_id IS NOT NULL\n      ORDER BY r.notion_synced_at ASC NULLS FIRST, r.started_at DESC\n      LIMIT 100`);\n  if (rows.length === 0) return;\n  // 直接走统一引擎、不经 upsertOpsRows：后者的 onFatal 会把「库不可达」写成 ops_notion_dbs.disabled，\n  // 那是运行舱四库的终止开关，Runs 库出问题不许连坐运行舱推送。\n  const bodyDeadline=Date.now()+45000;\n  await pushRegisteredRows(pool, token, {\n    table: 'task_runs', dbId, rows, buildProps: r => buildTaskRunNotionProperties({ ...r,\n      workflow_page_id: workflowsDb ? r.workflow_page_id : null, task_page_id: tasksDb ? r.task_page_id : null }),\n    notionReq, logSyncError, isStaleRelationError, isWrongDatabaseError, label: 'task_run',budgetMs:45000,\n    syncBody:(row,pageId)=>syncManagedBodyBlock(token,pageId,buildTaskRunNotionBodyBlock(row),\n      (...args)=>{if(Date.now()>=bodyDeadline)throw Error('Run来源正文同步预算耗尽');return notionReq(...args);},RUN_SOURCE_MARKER),\n  });\n\n}\n\n/** 吞错壳：投影失败绝不连坐同轮其它推送。 */\nasync function pushTaskRunsSafe(pool, token) {\n  try {\n    await pushTaskRuns(pool, token);\n  } catch (err) {\n    console.warn(`[notion-push-sync] task_runs 投影失败（非阻断）: ${err.message}`);\n  }\n}\n\nexport async function pushTaskRunsForTest(pool, token) {\n  return pushTaskRuns(pool, token);\n}\n\nexport async function runNotionPushSync(pool) {\n  let token;\n  try {\n    token = getToken();\n  } catch {\n    return;\n  }\n\n  await pushJourneys(pool, token);\n  await pushJourneyFeatures(pool, token);\n  await pushIssues(pool, token);\n  await pushTasks(pool, token);\n  await pushJourneyStepLinks(pool, token);\n  await pushDecisions(pool, token);\n  await pushInitiativeContracts(pool, token);\n  await pushAdvancementItems(pool, token);\n  await pushOpsGraph(pool, token);\n  await pushTaskRunsSafe(pool, token);\n  // 接力棒投影：project 根 → Projects 库；待拍板 → 「决策」库草案（吞错，不连坐前面的推送）\n  try {\n    const { runRelayProjection } = await import('./notion-relay-projection.js');\n    await runRelayProjection(pool, { token });\n  } catch (err) {\n    console.warn(`[notion-push-sync] relay projection 失败（非阻断）: ${err.message}`);\n  }\n  // 验证层投影（棒4-2）：探针库 + 判定回执库；库未登记自跳过，吞错不连坐\n  try {\n    const { runProbeProjection } = await import('./notion-probe-projection.js');\n    await runProbeProjection(pool, { token, logSyncError });\n  } catch (err) {\n    console.warn(`[notion-push-sync] probe projection 失败（非阻断）: ${err.message}`);\n  }\n  // 仓库物件库 + 用料库（v3.0 第 3 刀 c 段）：缺库自建并登记，前提不足自跳过，吞错不连坐\n  try {\n    const { runWarehouseProjection } = await import('./notion-warehouse-projection.js');\n    await runWarehouseProjection(pool, { token, logSyncError });\n  } catch (err) {\n    console.warn(`[notion-push-sync] warehouse projection 失败（非阻断）: ${err.message}`);\n  }\n  // 「价值流 Value Streams」库已由六层目录投影接管（Brain value_streams 为准）；结构地图镜子不再写这个库\n}\n",
  "packages/brain/src/lib/openclaw-dispatch-template.js": "import { openSync, closeSync, fstatSync, readFileSync, constants } from 'node:fs';\nimport { join, basename } from 'node:path';\nimport { homedir } from 'node:os';\nimport { DISPATCH_DEFAULTS } from './openclaw-dispatch-defaults.js';\n\nfunction readJson(path, secret = false) {\n  const fd = openSync(path, constants.O_RDONLY | constants.O_NOFOLLOW);\n  try {\n    const stat = fstatSync(fd);\n    if (!stat.isFile() || stat.size > 65536\n        || (secret && ((stat.mode & 0o077) !== 0 || stat.uid !== process.getuid()))) throw Error('untrusted_file');\n    return JSON.parse(readFileSync(fd, 'utf8'));\n  } finally { closeSync(fd); }\n}\nconst object = v => v && typeof v === 'object' && !Array.isArray(v);\nfunction inlineToken(v) {\n  if (!v || typeof v !== 'object') return false;\n  return Object.entries(v).some(([key, value]) => key === 'control_token' || inlineToken(value));\n}\n\n/** 模板与凭据分离；不使用归档/旧 JSON 的 token，不把错误内容带到 Notion。 */\nexport function readDispatchTemplate(dir, file, { secretPath = join(homedir(), '.credentials', 'openclaw-dispatch.json') } = {}) {\n  let template;\n  try {\n    if (typeof file !== 'string' || basename(file) !== file || file.includes('..')\n        || !/^[a-zA-Z0-9][a-zA-Z0-9_.-]*\\.json$/.test(file)) throw Error('invalid_name');\n    template = dir ? readJson(join(dir, file)) : structuredClone(DISPATCH_DEFAULTS[file]);\n    if (!object(template) || !/^[a-zA-Z0-9_-]{1,128}$/.test(template.tenant_id ?? '')\n        || inlineToken(template) || !object(template.task_request)\n        || (template.task_request.tenant_id !== undefined && template.task_request.tenant_id !== template.tenant_id)) {\n      throw Error('invalid_template');\n    }\n  } catch { throw Error('dispatch_template_invalid'); }\n  let token;\n  try {\n    const tokens = readJson(secretPath, true);\n    if (!object(tokens) || !Object.hasOwn(tokens, template.tenant_id)) throw Error('unknown_tenant');\n    token = tokens[template.tenant_id];\n    if (typeof token !== 'string' || !token.trim()) throw Error('empty_token');\n  } catch { throw Error('dispatch_credentials_unavailable'); }\n  return { ...template, control_token: token };\n}\n",
  "packages/brain/src/lib/openclaw-dispatch-defaults.js": "// 原 US dispatch 模板的非敏感参数；凭据仅在读取时由 1Password 缓存注入。\nexport const DISPATCH_DEFAULTS = Object.freeze({\n  \"jinoshengyuan-daily.json\": {\n    \"mode\": \"run\",\n    \"tenant_id\": \"jinoshengyuan\",\n    \"task_name\": \"金诺盛源｜西安AI训练师获客｜日增量\",\n    \"task_request\": {\n      \"task_name\": \"金诺盛源｜西安AI训练师获客｜日增量\",\n      \"tenant_id\": \"jinoshengyuan\",\n      \"audience\": \"西安及陕西省内，想学习人工智能训练师并了解报考、上课、补贴、就业的人\",\n      \"keywords\": [\n        \"西安 人工智能训练师\"\n      ],\n      \"search_policy\": {\n        \"sort\": \"latest\",\n        \"time_layers\": [\n          \"one_day\"\n        ],\n        \"duration\": \"unlimited\",\n        \"scope\": \"unlimited\",\n        \"location\": \"same_city\",\n        \"exhaust_visible_results\": true\n      },\n      \"qualification_policy\": {\n        \"transcript_coverage\": \"full\",\n        \"verdict_mode\": \"single_full_transcript\",\n        \"low_confidence\": \"review\"\n      },\n      \"comment_policy\": {\n        \"mode\": \"top_n\",\n        \"window\": \"follow_video_layer\",\n        \"batch_size\": 5,\n        \"scheduler\": \"round_robin\",\n        \"per_video_limit\": 5\n      },\n      \"scoring_policy\": {\n        \"deliver_categories\": [\n          \"strong_intent\",\n          \"weak_intent\"\n        ],\n        \"low_confidence\": \"review\"\n      },\n      \"delivery_policy\": {\n        \"destination\": \"tenant_final_leads\",\n        \"dedupe\": [\n          \"video\",\n          \"comment\",\n          \"person\",\n          \"prior_runs\"\n        ],\n        \"external_outreach\": false\n      },\n      \"card_target\": {\n        \"audience_key\": \"vps-status\",\n        \"chat_id\": \"oc_ef60d6e3f199d90dd695b6ecc213d662\",\n        \"visibility\": \"internal\"\n      }\n    }\n  },\n  \"yueshengyun-daily.json\": {\n    \"mode\": \"run\",\n    \"tenant_id\": \"yueshengyun\",\n    \"task_request\": {\n      \"task_name\": \"悦升云端｜西安企业 AI 办公获客｜日增量\",\n      \"audience\": \"西安及陕西省内，重点西安及周边城市，想用 AI 办公、OPC、一人公司和 AI 智能化实现降本增效的企业老板与管理者\",\n      \"keywords\": [\n        \"西安企业AI办公\"\n      ],\n      \"search_policy\": {\n        \"sort\": \"latest\",\n        \"time_layers\": [\n          \"one_day\"\n        ],\n        \"duration\": \"unlimited\",\n        \"scope\": \"unlimited\",\n        \"location\": \"unlimited\",\n        \"exhaust_visible_results\": true\n      }\n    }\n  }\n});\n",
  "packages/brain/src/feishu-task-ledger.js": "/**\n * feishu-task-ledger.js — 飞书群交办入账\n *\n * 主理人在飞书群派给秋米的活 → Cecelia tasks 账 → 自动投影 Notion。\n * 决策：方向 1c6679cd / 判定点 398d5f36。\n *\n * 为什么不从 OpenClaw sqlite 搬（前序方案作废）：实勘发现 OpenClaw 不持久化群消息原文\n * （channel_ingress_events.payload_json 完成后清空、transcript 表 0 行、飞书群在\n * task_runs 只留 13 行 CLI 噪音），唯一可信源是飞书开放平台 API。\n *\n * 三道判据（主理人 2026-09-16 拍板）：\n *   ① @ 的必须是秋米不是人（实测 14 天 232 条带 @ 消息里仅 81 条 @秋米）\n *   ② 秋米能即答、没调 agent 去干的不算任务（规则法不可分，必须语义判）\n *   ③ 重发去重（实测同一任务因无响应被重发 3 次）\n * 全部纯函数内核 + 注入式 IO，可单测。\n */\nimport { existsSync } from 'node:fs';\nimport { defaultExecAsync, buildHostCmd } from './host-exec.js';\nimport { buildMmvCmd, parseSqliteJson } from './openclaw-run-ingest.js';\n\nimport { createRoutedTask as defaultCreateRoutedTask } from './work-routing-store.js';\n\n/** 在册群（来源：OpenClaw clawdbot.json channels.feishu.accounts.main，此处固化，运行时不读第三方配置） */\nexport const GROUPS = Object.freeze([\n  Object.freeze({ chatId: 'oc_ee3fe04cf2541c4187f0fc054ae826de', name: '悦升云端', requireMention: true, agentId: 'zenithjoy-router' }),\n  Object.freeze({ chatId: 'oc_ef60d6e3f199d90dd695b6ecc213d662', name: 'VPS 状态', requireMention: false, agentId: 'zenithjoy-router' }),\n  Object.freeze({ chatId: 'oc_e5ff09de4c2e30a332df0d3cf87f41ae', name: '外部Ai体验区', requireMention: true, agentId: 'zenithjoy-router' }),\n]);\n\n/** 从飞书消息体里取纯文本（text / post 两种 msg_type） */\nexport function messageText(m) {\n  try {\n    const c = JSON.parse(m?.body?.content ?? '{}');\n    if (typeof c.text === 'string') return c.text;\n    if (Array.isArray(c.content)) {\n      return c.content.flat().map((seg) => seg?.text ?? '').join('');\n    }\n    return '';\n  } catch {\n    return '';\n  }\n}\n\n/**\n * 取 mention 对象里的 open_id。\n * 飞书两套形态：历史消息 API(im/v1/messages) 返回扁平 {\"id\":\"ou_xxx\",\"id_type\":\"open_id\"}，\n * webhook 事件返回嵌套 {\"id\":{\"open_id\":\"ou_xxx\"}}。\n * 2026-09-16 生产实证：只认嵌套形态 → requireMention 群候选恒空 → 一条都入不了账。\n */\nexport function mentionOpenId(mention) {\n  const id = mention?.id;\n  if (typeof id === 'string') return id;\n  return id?.open_id ?? null;\n}\n\n/**\n * 判据 1：这条消息是不是\"给秋米的\"\n * requireMention 群必须 @ 到 bot 的 open_id（禁按显示名匹配——名字可改，open_id 不会）；\n * 非 requireMention 群（如 VPS 状态）所有人发消息都算。\n */\nexport function selectCandidates(messages, group, botOpenId) {\n  return (messages ?? []).filter((m) => {\n    if (m?.sender?.sender_type !== 'user') return false;\n    if (!messageText(m).trim()) return false;\n    if (!group.requireMention) return true;\n    return (m.mentions ?? []).some((x) => mentionOpenId(x) === botOpenId);\n  });\n}\n\n/** 归一化文本用于重发比对：去空白、去标点、截断 */\nfunction normalizeForDedupe(text) {\n  return text.replace(/\\s+/g, '').replace(/[，。！？、,.!?~…]/g, '').slice(0, 60);\n}\n\n/**\n * 判据 3：重发去重\n * 实测同一任务因秋米无响应被重发 3 次（「整理商品表格」06:30/06:52/06:54）；\n * 不去重则一个活记三行。同发送人 + 归一化文本相同 + 窗口内 → 合并，保留最早一条为 head。\n */\nexport function dedupeResends(candidates, windowMs = 30 * 60 * 1000) {\n  const sorted = [...(candidates ?? [])].sort(\n    (a, b) => Number(a.create_time) - Number(b.create_time),\n  );\n  const groups = [];\n  for (const m of sorted) {\n    const key = `${m.sender?.id}::${normalizeForDedupe(messageText(m))}`;\n    const hit = groups.find(\n      (g) => g.key === key && Number(m.create_time) - Number(g.head.create_time) <= windowMs,\n    );\n    if (hit) hit.messageIds.push(m.message_id);\n    else groups.push({ key, head: m, messageIds: [m.message_id] });\n  }\n  return groups.map(({ head, messageIds }) => ({ head, messageIds }));\n}\n\nconst REPLY_WINDOW_MS = 30 * 60 * 1000;\n\n/**\n * 执行回执（主理人拍板：用机器回复当凭据）\n * 交办后 windowMs 内同群出现机器人消息 = 已响应。\n */\nexport function resolveReplyEvidence(head, allMessages, windowMs = REPLY_WINDOW_MS) {\n  const t0 = Number(head.create_time);\n  return (allMessages ?? []).some((m) => {\n    if (m?.sender?.sender_type !== 'app') return false;\n    const dt = Number(m.create_time) - t0;\n    return dt > 0 && dt <= windowMs;\n  });\n}\n\n/**\n * 组装 createRoutedTask 入参。\n * 铁律：status 只能是 completed / blocked，绝不 queued——\n * queued + claimed_by IS NULL 会被 Brain tick 每 2 分钟捡走，真去\"执行\"群里的客户对话。\n */\nexport function buildTaskRequest({ head, messageIds, group, botReplied, contextText, disposition }) {\n  const text = cleanTitle(messageText(head));\n  const status = outcomeToStatus(disposition)\n    ?? (botReplied ? 'completed' : 'blocked');\n  return {\n    source: 'inbox',\n    source_id: head.message_id,\n    title: text.replace(/\\s+/g, ' ').slice(0, 60),\n    description: contextText ? `${text}\\n\\n--- 群内上下文 ---\\n${contextText}` : text,\n    mutation_intent: 'none',\n    declared_domain: 'operations',\n    requested_task_type: 'workflow_run',\n    metadata: {\n      feishu_message_id: head.message_id,\n      feishu_message_ids: messageIds,\n      chat_id: group.chatId,\n      chat_name: group.name,\n      sender_open_id: head.sender?.id ?? null,\n      create_time: head.create_time,\n      bot_replied: botReplied,\n      disposition: disposition ?? null,\n      ledger_only: true,\n    },\n    task: {\n      status,\n      priority: 'P2',\n      // DB 约束 chk_blocked_at_not_null：status=blocked 时 blocked_at 必须非空，\n      // 缺了会让整批入账在 INSERT 处报错、created 恒为 0（2026-09-16 E2E 实证）\n      ...(status === 'blocked' ? { blocked_at: new Date().toISOString() } : {}),\n    },\n  };\n}\n\nconst FEISHU_BASE = 'https://open.feishu.cn/open-apis';\n\nasync function feishuJson(fetchFn, url, init) {\n  const res = await fetchFn(url, init);\n  const body = await res.json();\n  if (body?.code !== 0) {\n    throw new Error(`feishu_api_error: ${body?.msg ?? 'unknown'} (code=${body?.code})`);\n  }\n  return body;\n}\n\nexport async function fetchTenantToken({ fetchFn, appId, appSecret }) {\n  const body = await feishuJson(fetchFn, `${FEISHU_BASE}/auth/v3/tenant_access_token/internal`, {\n    method: 'POST',\n    headers: { 'Content-Type': 'application/json' },\n    body: JSON.stringify({ app_id: appId, app_secret: appSecret }),\n  });\n  return body.tenant_access_token;\n}\n\n/** bot 自身 open_id——身份判定只认它，显示名可被改 */\nexport async function fetchBotOpenId({ fetchFn, token }) {\n  const body = await feishuJson(fetchFn, `${FEISHU_BASE}/bot/v3/info`, {\n    headers: { Authorization: `Bearer ${token}` },\n  });\n  return body?.bot?.open_id ?? null;\n}\n\nexport async function fetchGroupMessages({ fetchFn, token, chatId, startTimeSec }) {\n  const out = [];\n  let pageToken = null;\n  do {\n    let url = `${FEISHU_BASE}/im/v1/messages?container_id_type=chat&container_id=${chatId}`\n      + `&page_size=50&sort_type=ByCreateTimeDesc&start_time=${startTimeSec}`;\n    if (pageToken) url += `&page_token=${pageToken}`;\n    const body = await feishuJson(fetchFn, url, { headers: { Authorization: `Bearer ${token}` } });\n    out.push(...(body.data?.items ?? []));\n    pageToken = body.data?.has_more ? body.data?.page_token : null;\n  } while (pageToken);\n  return out;\n}\n\nconst EXEC_WINDOW_MS = 10 * 60 * 1000;\n\n/** 解析 sqlite3 -json 输出；任何异常一律返回空数组（第三方库出问题不能拖垮守卫） */\nexport function parseRunRows(raw) {\n  const t = String(raw ?? '').trim();\n  if (!t) return [];\n  const a = t.indexOf('[');\n  const b = t.lastIndexOf(']');\n  if (a < 0 || b <= a) return [];\n  try {\n    const parsed = JSON.parse(t.slice(a, b + 1));\n    return Array.isArray(parsed) ? parsed : [];\n  } catch {\n    return [];\n  }\n}\n\n/** 远端只读事实：复用现行 MMV 通道，查询全部 runtime；读取失败不是“无执行”。 */\nexport async function loadAgentRuns({ agentId, sinceMs, execFn = defaultExecAsync,\n  inContainer = existsSync('/.dockerenv') }) {\n  if (typeof agentId !== 'string' || !/^[a-zA-Z0-9_-]{1,128}$/.test(agentId)\n      || !Number.isSafeInteger(sinceMs) || sinceMs < 0) throw new Error('invalid_evidence_query');\n  const sql = `SELECT created_at, COALESCE(task_kind,'') AS task_kind, runtime\n               FROM task_runs WHERE agent_id='${agentId}' AND created_at > ${sinceMs}\n               ORDER BY created_at`;\n  try {\n    const out = await execFn(buildHostCmd(buildMmvCmd(sql), inContainer), { timeoutMs: 30_000 });\n    const rows = parseSqliteJson(out);\n    if (rows.some(row => !row || !Number.isSafeInteger(row.created_at) || row.created_at <= sinceMs\n        || typeof row.task_kind !== 'string' || typeof row.runtime !== 'string')) throw new Error('invalid_rows');\n    return rows;\n  } catch {\n    // 不传播 SSH stderr（可能含主机私有信息）；由调用方记 unknown，绝不回退 US 旧库。\n    throw new Error('openclaw_evidence_unavailable');\n  }\n}\n\n// ── 根因识别：秋米\"为什么没干\"，答案就在它自己的回复里 ──────────────────────\n// 2026-09-16 实证：机器回复有固定套话，用关键词就能分根因，不需要 LLM 去猜人说的话。\n// 顺序即优先级：故障 > 等补料 > 已完成 > 普通答复。\n\n/** 系统故障：认证失效、设备离线、上游报错——这类要起告警，是真坏了 */\nconst FAULT_PATTERNS = [\n  /\\b40[13]\\b/, /invalid api key/i, /authentication_error/i, /unauthorized/i,\n  /internal error/i, /temporary .*error/i, /rate.?limit/i,\n  /(还没能|无法|未能|不能)(连接|访问|读取|获取)/, /(离线|不在线|连不上)/,\n  /credit balance is too low/i, /quota|用量上限/,\n];\n/** 等主理人补东西：球在人那边，不是系统的问题 */\nconst WAITING_PATTERNS = [\n  /(请|先)?(把|将).{0,12}(发来|发给我|提供|上传)/, /(需要|还需)(你|您)?(确认|提供|补充)/,\n  /还需要确认/, /请确认/, /等(你|您)(的)?(确认|回复|资料)/,\n  // 注意：不要匹配裸的「缺少 X」——秋米说「问题不是安装失败，而是缺少输入文件」\n  // 是在做诊断，不是在等主理人补料（2026-09-16 实测边界）。只认带请求语气的。\n];\n/** 已经干完了：即使没留 run 记录（用 MCP 直接做的） */\nconst DONE_PATTERNS = [\n  /已(创建|整理|生成|完成|建好|写好|同步|上传|发布)/, /已回读核验/, /创建(成功|完毕)/,\n];\n\n/**\n * 从秋米的一条回复判断根因。\n * 返回 fault | waiting | done | answer | none\n */\nexport function classifyBotReply(text) {\n  const t = String(text ?? '').trim();\n  if (!t) return 'none';\n  if (FAULT_PATTERNS.some((re) => re.test(t))) return 'fault';\n  if (WAITING_PATTERNS.some((re) => re.test(t))) return 'waiting';\n  if (DONE_PATTERNS.some((re) => re.test(t))) return 'done';\n  return 'answer';\n}\n\n/** 去掉飞书 @ 占位符（历史消息 API 把 @某人 渲染成 @_user_N）与多余空白 */\nexport function cleanTitle(text) {\n  return String(text ?? '').replace(/@_user_\\d+/g, '').replace(/\\s+/g, ' ').trim();\n}\n\nconst OUTCOME_PRIORITY = Object.freeze(['fault', 'waiting', 'done', 'answer']);\n\n/**\n * 合成最终判定：执行记录 + 秋米回复根因。\n *   done    —— 有 run，或回复说已完成（MCP 直接干的不留 run）→ 入账 completed\n *   fault   —— 回复是系统故障 → 入账 blocked，附故障原文，可直接起告警\n *   waiting —— 回复在等主理人补料 → 入账 blocked，球在主理人\n *   answer  —— 普通答复（咨询答完即止）→ 不入账\n *   silent  —— 完全没回（实测全是闲聊碎片）→ 不入账\n *   unknown —— 早于 run 证据覆盖范围，无从判断 → 不入账\n */\nexport function resolveOutcome({\n  head, messageIds, messages, runs, windowMs = EXEC_WINDOW_MS, evidenceFloorMs = null,\n}) {\n  const ids = new Set(messageIds ?? [head.message_id]);\n  const groupMsgs = (messages ?? []).filter((m) => ids.has(m.message_id));\n  const stamps = (groupMsgs.length ? groupMsgs : [head]).map((m) => Number(m.create_time));\n  if (evidenceFloorMs != null && Math.max(...stamps) < evidenceFloorMs) return 'unknown';\n\n  const executed = (runs ?? []).some((r) => {\n    if (r?.task_kind === 'automation_run') return false;\n    const t = Number(r?.created_at);\n    return stamps.some((t0) => t - t0 > 0 && t - t0 <= windowMs);\n  });\n\n  // 回复归属：以重发组最后一条为起点（重发后秋米才会回），到下一条人发消息为止\n  const lastStamp = Math.max(...stamps);\n  const anchor = (groupMsgs.length ? groupMsgs : [head])\n    .find((m) => Number(m.create_time) === lastStamp) ?? head;\n  const replies = repliesFor(anchor, messages, windowMs === EXEC_WINDOW_MS ? REPLY_WINDOW_MS : windowMs);\n  if (replies.length === 0) return executed ? 'done' : 'silent';\n\n  const kinds = replies.map((m) => classifyBotReply(messageText(m)));\n  for (const k of OUTCOME_PRIORITY) {\n    if (kinds.includes(k)) return (k === 'answer' && executed) ? 'done' : k;\n  }\n  return executed ? 'done' : 'answer';\n}\n\n/**\n * 取属于这条交办的秋米回复：从交办时刻起，到「下一条人发的消息」为止（或 windowMs 封顶）。\n * 2026-09-16 实测：群里消息密集，只按 30min 窗口取会串台——「表在哪」会把 17 分钟后\n * 另一件事的 401 回复认成自己的，于是被误判成系统故障。\n */\nexport function repliesFor(head, messages, windowMs = REPLY_WINDOW_MS) {\n  const t0 = Number(head.create_time);\n  const sorted = [...(messages ?? [])].sort((a, b) => Number(a.create_time) - Number(b.create_time));\n  const nextUser = sorted.find((m) => m?.sender?.sender_type === 'user' && Number(m.create_time) > t0);\n  const ceiling = Math.min(\n    t0 + windowMs,\n    nextUser ? Number(nextUser.create_time) : Number.POSITIVE_INFINITY,\n  );\n  return sorted.filter((m) => m?.sender?.sender_type === 'app'\n    && Number(m.create_time) > t0\n    && Number(m.create_time) < ceiling);\n}\n\n/** 取交办后第一条秋米回复的摘录，作为\"为什么卡住\"的证据附在账目上 */\nexport function firstBotReplyExcerpt(head, messages, windowMs = REPLY_WINDOW_MS, maxLen = 200) {\n  const reply = repliesFor(head, messages, windowMs)[0];\n  return reply ? cleanTitle(messageText(reply)).slice(0, maxLen) : null;\n}\n\n/** 判定 → 入账状态；只有 done/fault/waiting 入账，其余返回 null。任何一态都不得产出 queued。 */\nexport function outcomeToStatus(outcome) {\n  if (outcome === 'done') return 'completed';\n  if (outcome === 'fault' || outcome === 'waiting') return 'blocked';\n  return null;\n}\n\n/**\n * 三态机械判定（主理人 2026-09-16 拍板，零 LLM）：\n *   executed —— 交办后窗口内秋米真产生了执行记录 → 是任务，已办\n *   answered —— 没执行记录但秋米回了话 → 当场答完的提问，不是任务\n *   dropped  —— 既没执行也没回话 → 派了没人管的活，正是主理人最该看见的\n * 重发组内任一条命中即算 executed（实测 run 常挂在后一次重发上，而 head 取最早那条）。\n * automation_run 是 cron 定时的自主动作，与群消息无关，不算响应。\n */\n/**\n * 证据覆盖下界：OpenClaw 会清理老 run（实测只保 7 天），早于最早一条 run 的消息，\n * \"没有 run\" 可能只是记录被清了，不能据此判定\"没人干\"。取 run 最早时间戳为下界；\n * 一条 run 都没有时回退到扫描起点（此时整段都不可信，全判 unknown）。\n */\nexport function resolveEvidenceFloor(runs, fallbackMs) {\n  const stamps = (runs ?? []).map((r) => Number(r?.created_at)).filter((n) => Number.isFinite(n));\n  return stamps.length ? Math.min(...stamps) : fallbackMs;\n}\n\n// 与 OpenClaw task_runs 保留期对齐（实测只保 7 天）；扫更早的消息也无证据可判\nconst LOOKBACK_SEC = 7 * 24 * 3600;\n\n/** 取 head 前后各 radius 条做上下文——「你拉个会议」这类短指令离开上下文不可解 */\nexport function buildContextText(head, messages, radius = 3) {\n  const sorted = [...messages].sort((a, b) => Number(a.create_time) - Number(b.create_time));\n  const idx = sorted.findIndex((m) => m.message_id === head.message_id);\n  if (idx < 0) return '';\n  return sorted\n    .slice(Math.max(0, idx - radius), idx + radius + 1)\n    .map((m) => {\n      const who = m.sender?.sender_type === 'app' ? '秋米' : '人';\n      const mark = m.message_id === head.message_id ? '>>> ' : '    ';\n      return `${mark}[${who}] ${messageText(m).replace(/\\s+/g, ' ').slice(0, 120)}`;\n    })\n    .join('\\n');\n}\n\n/**\n * scheduler 入口：拉群消息 → 机械判据 → 入账\n * 全程零 LLM：@对象靠 open_id 比对，\"是不是真派了活\"靠 OpenClaw 执行流水，都是查表。\n */\nexport async function runFeishuTaskLedger(pool, deps = {}) {\n  const env = deps.env ?? process.env;\n  const appId = env.FEISHU_APP_ID;\n  const appSecret = env.FEISHU_APP_SECRET;\n  if (!appId || !appSecret) {\n    console.warn('[feishu-task-ledger] 缺 FEISHU_APP_ID/FEISHU_APP_SECRET，跳过');\n    return { skipped: 'missing_credentials', scanned: 0, created: 0 };\n  }\n  const fetchFn = deps.fetchFn ?? globalThis.fetch;\n  const fetchToken = deps.fetchTokenFn ?? (() => fetchTenantToken({ fetchFn, appId, appSecret }));\n  const fetchBot = deps.fetchBotOpenIdFn ?? ((token) => fetchBotOpenId({ fetchFn, token }));\n  const fetchMessages = deps.fetchMessagesFn\n    ?? (({ token, chatId, startTimeSec }) => fetchGroupMessages({\n      fetchFn, token, chatId, startTimeSec,\n    }));\n  const loadRuns = deps.loadAgentRunsFn\n    ?? ((args) => loadAgentRuns({ ...args, execFn: deps.execFn, inContainer: deps.inContainer }));\n  const createTask = deps.createRoutedTaskFn ?? defaultCreateRoutedTask;\n  const sinceSec = deps.sinceSec ?? Math.floor(Date.now() / 1000) - LOOKBACK_SEC;\n\n  const token = await fetchToken();\n  const botOpenId = await fetchBot(token);\n  let scanned = 0;\n  let created = 0;\n  const stats = { done: 0, fault: 0, waiting: 0, answer: 0, silent: 0, unknown: 0 };\n  const errors = [];\n  const evidence_errors = [];\n\n  for (const group of GROUPS) {\n    try {\n      const messages = await fetchMessages({ token, chatId: group.chatId, startTimeSec: sinceSec });\n      scanned += messages.length;\n      const candidates = selectCandidates(messages, group, botOpenId);\n      const deduped = dedupeResends(candidates);\n      if (deduped.length === 0) continue;\n\n      let runs;\n      try {\n        runs = await loadRuns({ agentId: group.agentId, sinceMs: sinceSec * 1000 });\n      } catch {\n        stats.unknown += deduped.length;\n        errors.push(group.chatId);\n        evidence_errors.push({ chat_id: group.chatId, reason: 'openclaw_evidence_unavailable' });\n        continue;\n      }\n      const evidenceFloorMs = resolveEvidenceFloor(runs, sinceSec * 1000);\n\n      for (const c of deduped) {\n        const outcome = resolveOutcome({\n          head: c.head, messageIds: c.messageIds, messages, runs, evidenceFloorMs,\n        });\n        stats[outcome] = (stats[outcome] ?? 0) + 1;\n        const status = outcomeToStatus(outcome);\n        if (!status) continue; // answer/silent/unknown 不入账\n\n        const req = buildTaskRequest({\n          head: c.head,\n          messageIds: c.messageIds,\n          group,\n          botReplied: resolveReplyEvidence(c.head, messages),\n          contextText: buildContextText(c.head, messages),\n          disposition: outcome,\n        });\n        // 故障/等待类附上秋米原话，主理人一眼看到卡在哪，不用回群里翻\n        req.metadata.bot_reply_excerpt = firstBotReplyExcerpt(c.head, messages);\n        await createTask(pool, req);\n        created += 1;\n      }\n    } catch (err) {\n      console.error(`[feishu-task-ledger] 群 ${group.chatId} 处理失败: ${err.message}`);\n      errors.push(group.chatId);\n    }\n  }\n  console.log(`[feishu-task-ledger] scanned=${scanned} created=${created} `\n    + `done=${stats.done} fault=${stats.fault} waiting=${stats.waiting} `\n    + `answer=${stats.answer} silent=${stats.silent} unknown=${stats.unknown}`);\n  return { scanned, created, stats, errors, evidence_errors };\n}\n\nconst GATE_INTERVAL_MS = 60 * 60 * 1000;\nlet _lastRunAt = 0;\n\n/** 测试用：重置 gate 状态 */\nexport function _resetFeishuLedgerGate() { _lastRunAt = 0; }\n\n/** scheduler 每 60s 调一次，本函数自 gate 到 60min 一跑 */\nexport async function maybeRunFeishuTaskLedger(pool, deps = {}) {\n  const now = (deps.now ?? Date.now)();\n  if (_lastRunAt && now - _lastRunAt < GATE_INTERVAL_MS) return { skipped: 'cooldown' };\n  _lastRunAt = now;\n  return runFeishuTaskLedger(pool, deps);\n}\n",
  "packages/brain/src/openclaw-run-ingest.js": "/**\n * OpenClaw 运行记录采集（Brain 定时任务 openclaw-run-ingest，每 300s）\n *\n * 决策：\n *   - c7ff6e02：运行记录落库并同步 Notion，不再推飞书\n *   - 9ec7a010：本功能三点拍板（采集 / 连败升级 / 近 30 天回填）\n * 判定点：\n *   - b7be0e26：结果按 OpenClaw task_runs.status 判（succeeded/failed/timed_out/running/queued）\n *   - 6d4b7ed5：任务名取 cron_jobs.name，缺失回退 `openclaw-job:<job_id 前 8 位>`\n *\n * 本文件含纯函数（SQL 构造 / ssh 命令构造 / 输出解析 / 行映射）、DB 层（游标读取 / upsert / 连败告警）\n * 与主入口 runOpenclawRunIngest（ssh 经 deps.exec 注入，测试从不真连 mmv）。\n *\n * 数据源：MMV ~/.openclaw/state/openclaw.sqlite（只读），task_runs WHERE runtime='cron'。\n */\n\nimport { existsSync } from 'fs';\nimport { defaultExecAsync, buildHostCmd } from './host-exec.js';\nimport { sendBark as defaultSendBark } from './notifier.js';\n\nconst DAY_MS = 86400_000;\nconst BACKFILL_DAYS = 30;\nconst ERROR_MAX = 2000;\nconst SUMMARY_MAX = 4000;\nconst LIMIT_MAX = 2000;\nconst SQLITE_PATH = '~/.openclaw/state/openclaw.sqlite';\n\n/** task_runs.status → runs.outcome（判定点 b7be0e26），其余一律 unknown */\nexport const OUTCOME_BY_STATUS = {\n  succeeded: 'pass',\n  failed: 'fail',\n  timed_out: 'timeout',\n  running: 'running',\n  queued: 'running',\n};\n\nfunction assertInt(name, v) {\n  if (typeof v !== 'number' || !Number.isSafeInteger(v)) {\n    throw new Error(`invalid_${name}: ${String(v)}`);\n  }\n  return v;\n}\n\n/**\n * 构造增量查询 SQL。数字直接内插，故只接受有限整数。\n * sinceMs 为 null/undefined（首轮）→ 回填 nowMs 往前 30 天。\n */\nexport function buildIngestSql({ sinceMs, nowMs, limit = 2000 }) {\n  const now = assertInt('nowMs', nowMs);\n  const lim = assertInt('limit', limit);\n  // 越界（尤其 -1，sqlite 视为不限行）一律拒绝\n  if (lim < 1 || lim > LIMIT_MAX) throw new Error(`invalid_limit: ${lim}`);\n  const since = sinceMs == null ? now - BACKFILL_DAYS * DAY_MS : assertInt('sinceMs', sinceMs);\n  return [\n    'SELECT t.task_id,t.source_id,t.agent_id,t.status,t.created_at,t.started_at,t.ended_at,',\n    't.terminal_summary,t.error,j.name,j.payload_kind',\n    'FROM task_runs t LEFT JOIN cron_jobs j ON j.job_id=t.source_id',\n    \"WHERE t.runtime='cron'\",\n    `AND (coalesce(t.last_event_at,t.ended_at,t.created_at) >= ${since} OR t.status IN ('running','queued'))`,\n    `ORDER BY t.created_at LIMIT ${lim}`,\n  ].join(' ');\n}\n\n/** SQL 经 base64 编码拼进 ssh 命令，规避多层引号转义；~ 由远端 shell 展开 */\nexport function buildMmvCmd(sql) {\n  const b64 = Buffer.from(sql, 'utf8').toString('base64');\n  return `ssh -o BatchMode=yes -o ConnectTimeout=20 mmv 'echo ${b64} | base64 -d | sqlite3 -readonly -json ${SQLITE_PATH}'`;\n}\n\n/** sqlite3 -json 对空结果输出空串；其余必须是 JSON 数组 */\nexport function parseSqliteJson(stdout) {\n  const text = String(stdout ?? '').trim();\n  if (text === '') return [];\n  let parsed;\n  try {\n    parsed = JSON.parse(text);\n  } catch (e) {\n    throw new Error(`parse_error: ${e.message}`);\n  }\n  if (!Array.isArray(parsed)) {\n    throw new Error('parse_error: expected JSON array');\n  }\n  return parsed;\n}\n\nfunction toMs(v) {\n  if (v === null || v === undefined || v === '') return null;\n  const n = typeof v === 'number' ? v : Number(v);\n  return Number.isFinite(n) ? n : null;\n}\n\n/**\n * 按 UTF-16 码元截断到 max；若末码元是高代理项（代理对被从中间切开）再去掉一位，\n * 避免写入 jsonb 时被 Postgres 以孤立代理项拒收。长度上限仍按码元计，始终 <= max。\n */\nexport function truncateText(v, max) {\n  if (v === null || v === undefined) return null;\n  let out = String(v).slice(0, max);\n  if (out.length > 0) {\n    const last = out.charCodeAt(out.length - 1);\n    if (last >= 0xd800 && last <= 0xdbff) out = out.slice(0, -1);\n  }\n  return out;\n}\n\n/**\n * task_runs 行 → runs 行（不含 trigger_kind/header_source/schedule 关联，由 upsert 层补）。\n * task_id 缺失或起止时间都不可用 → null（调用方跳过）。\n */\nexport function mapOpenclawRow(row) {\n  if (!row || row.task_id === null || row.task_id === undefined || row.task_id === '') return null;\n\n  const startMs = toMs(row.started_at) ?? toMs(row.created_at);\n  if (startMs === null) return null;\n\n  const outcome = OUTCOME_BY_STATUS[row.status] ?? 'unknown';\n\n  let endedAt = null;\n  const endMs = toMs(row.ended_at);\n  if (outcome !== 'running' && endMs !== null) {\n    endedAt = new Date(Math.max(endMs, startMs));\n  }\n\n  const jobId = row.source_id ?? null;\n  const triggerRef = row.name\n    ? String(row.name)\n    : `openclaw-job:${jobId ? String(jobId).slice(0, 8) : 'unknown'}`;\n\n  return {\n    run_id: `openclaw:${row.task_id}`,\n    trigger_ref: triggerRef,\n    executor_kind: row.payload_kind === 'command' ? 'code' : 'agent',\n    executor_id: row.agent_id ? `openclaw:${row.agent_id}` : 'openclaw',\n    started_at: new Date(startMs),\n    ended_at: endedAt,\n    outcome,\n    error: truncateText(row.error, ERROR_MAX),\n    detail: {\n      source: 'openclaw',\n      job_id: jobId,\n      task_id: row.task_id,\n      summary: truncateText(row.terminal_summary, SUMMARY_MAX),\n      status: row.status ?? null,\n    },\n  };\n}\n\nconst CURSOR_SQL = \"SELECT max(started_at) AS max_started FROM runs WHERE run_id LIKE 'openclaw:%'\";\nconst CURSOR_OVERLAP_MS = 3600_000;\n\n/** 增量游标：已采集运行的最大 started_at 回退 1 小时（覆盖状态迟到变化）；首轮无行返回 null */\nexport async function readCursorMs(db) {\n  const { rows } = await db.query(CURSOR_SQL);\n  const max = rows[0]?.max_started;\n  return max ? new Date(max).getTime() - CURSOR_OVERLAP_MS : null;\n}\n\n// LATERAL 写法同 lib/workflow-runs.js 的 INSERT_SCHEDULER_RUN；\n// WHERE 子句保证无变化的行不被改写（rowCount 不计入）。\nconst UPSERT_SQL = `\n  INSERT INTO runs (run_id, workflow_id, trigger_kind, trigger_ref, schedule_entry_id, executor_kind, executor_id,\n                    started_at, ended_at, outcome, error, detail, header_source)\n  SELECT $1, e.workflow_id, 'schedule', $2, e.id, $3, $4, $5, $6, $7, $8, $9::jsonb, 'owner'\n    FROM (SELECT 1) one\n    LEFT JOIN LATERAL (\n      SELECT id, workflow_id FROM ops_schedule_entries\n       WHERE source = 'openclaw' AND label = $2\n       ORDER BY active DESC, id LIMIT 1\n    ) e ON true\n  ON CONFLICT (run_id) DO UPDATE SET\n    ended_at = EXCLUDED.ended_at,\n    outcome = EXCLUDED.outcome,\n    error = EXCLUDED.error,\n    detail = EXCLUDED.detail,\n    updated_at = now()\n  WHERE runs.outcome IS DISTINCT FROM EXCLUDED.outcome\n     OR runs.ended_at IS DISTINCT FROM EXCLUDED.ended_at\n     OR runs.detail IS DISTINCT FROM EXCLUDED.detail`;\n\nconst WARN_ROWS_MAX = 5;\n\n/**\n * 逐行幂等写入 runs；返回实际插入/更新的行数与写失败的行数。\n * 单行失败只计入 failed_rows、不中断整批：游标 = 已写入的最大 started_at，\n * 若一条坏行让整批中断，游标会永久卡在坏行之前。\n */\nexport async function upsertRuns(db, rows, { onError } = {}) {\n  let written = 0;\n  let failedRows = 0;\n  for (const r of rows) {\n    try {\n      const res = await db.query(UPSERT_SQL, [\n        r.run_id, r.trigger_ref, r.executor_kind, r.executor_id,\n        r.started_at, r.ended_at, r.outcome, r.error,\n        r.detail === null || r.detail === undefined ? null : JSON.stringify(r.detail),\n      ]);\n      written += res.rowCount;\n    } catch (e) {\n      failedRows += 1;\n      if (onError) onError(e);\n      // 逐行日志只打前 N 条，避免整批失败时刷出上千行\n      if (failedRows <= WARN_ROWS_MAX) {\n        console.warn(`[openclaw-run-ingest] 写入失败 ${r.run_id}:`, String(e?.message).slice(0, 160));\n      }\n    }\n  }\n  if (failedRows > WARN_ROWS_MAX) {\n    console.warn(`[openclaw-run-ingest] 另有 ${failedRows - WARN_ROWS_MAX} 行写入失败（共 ${failedRows} 行，已省略逐行日志）`);\n  }\n  return { written, failed_rows: failedRows };\n}\n\nconst STREAK_MIN = 3;\nconst STREAK_BODY_MAX = 120;\nconst STREAK_DEDUPE_TTL_SEC = 7 * 86400;\n\n// 连败段 = 最近一次「已结束且非失败」运行之后的全部 fail/timeout（不设窗口，起点不随行数增长漂移）。\n// count / first_run_id（最早一条，同时刻按 run_id）/ error+summary（最近一条）一次求出。\nconst STREAK_SQL = `\n  WITH last_ok AS (\n    SELECT max(started_at) AS t FROM runs\n     WHERE run_id LIKE 'openclaw:%' AND trigger_ref = $1\n       AND outcome NOT IN ('fail','timeout','running')\n  ), streak AS (\n    SELECT r.run_id, r.error, r.detail->>'summary' AS summary, r.started_at\n      FROM runs r, last_ok\n     WHERE r.run_id LIKE 'openclaw:%' AND r.trigger_ref = $1\n       AND r.outcome IN ('fail','timeout')\n       AND (last_ok.t IS NULL OR r.started_at > last_ok.t)\n  )\n  SELECT (SELECT count(*)::int FROM streak) AS count,\n         (SELECT run_id FROM streak ORDER BY started_at ASC, run_id ASC LIMIT 1) AS first_run_id,\n         (SELECT error FROM streak ORDER BY started_at DESC, run_id DESC LIMIT 1) AS error,\n         (SELECT summary FROM streak ORDER BY started_at DESC, run_id DESC LIMIT 1) AS summary`;\n\n/**\n * 对给定任务名判定连败并发 Bark（同一连败段由 dedupeKey 保证只发一次）。\n * 首轮回填（firstRound）不发，避免历史连败一次性炸出来。sendBark 由调用方注入。\n */\nexport async function notifyFailureStreaks(db, triggerRefs, { sendBark, firstRound }) {\n  if (firstRound) return { notified: 0 };\n  let notified = 0;\n  for (const name of triggerRefs) {\n    const { rows } = await db.query(STREAK_SQL, [name]);\n    const streak = rows[0];\n    if (!streak || streak.count < STREAK_MIN || !streak.first_run_id) continue;\n    const detail = truncateText(streak.error || streak.summary || '', STREAK_BODY_MAX);\n    await sendBark('OpenClaw 任务连续失败', `${name} 连续 ${streak.count} 次失败：${detail}`, {\n      dedupeKey: `openclaw-run-streak:${name}:${streak.first_run_id}`,\n      dedupeTtlSec: STREAK_DEDUPE_TTL_SEC,\n    });\n    notified += 1;\n  }\n  return { notified };\n}\n\nconst EXEC_TIMEOUT_MS = 60_000;\nconst CATCHUP_MS = 24 * 3600_000;\nconst GATE_INTERVAL_MS = 300_000;\nlet lastRunAt = 0;\n\n/** 测试用：重置自 gate 状态 */\nexport function _resetOpenclawIngestGate() { lastRunAt = 0; }\n\n/**\n * 主入口：读游标 → 拉增量 → 映射 → upsert → 连败告警。\n * ssh/解析失败直接抛错（让调度器记 fail，且不写库）；连败告警失败只告警不抛。\n * @param {{query: Function}} db\n * @param {{exec?: Function, inContainer?: boolean, sendBark?: Function, now?: () => number}} [deps]\n */\nexport async function runOpenclawRunIngest(db, deps = {}) {\n  const exec = deps.exec ?? defaultExecAsync;\n  const inContainer = deps.inContainer ?? existsSync('/.dockerenv');\n  const sendBark = deps.sendBark ?? defaultSendBark;\n  const now = deps.now ?? Date.now;\n\n  const nowMs = now();\n  // 调度器每 ~60s 调一遍全部 JOBS，自 gate 到 300s 一跑；本轮开始即记时，失败也算一轮，避免故障时每分钟重试\n  if (lastRunAt && nowMs - lastRunAt < GATE_INTERVAL_MS) return { skipped: true };\n  lastRunAt = nowMs;\n  const cursor = await readCursorMs(db);\n  const sql = buildIngestSql({ sinceMs: cursor, nowMs, limit: LIMIT_MAX });\n  const stdout = await exec(buildHostCmd(buildMmvCmd(sql), inContainer), { timeoutMs: EXEC_TIMEOUT_MS });\n  const raw = parseSqliteJson(stdout);\n\n  const rows = [];\n  let skipped = 0;\n  for (const r of raw) {\n    const mapped = mapOpenclawRow(r);\n    if (mapped) rows.push(mapped);\n    else skipped += 1;\n  }\n\n  let firstError = null;\n  const { written, failed_rows } = await upsertRuns(db, rows, { onError: (e) => { firstError ??= e; } });\n  // 整批全部写失败 = 系统性故障（schema 漂移/权限等），抛错让调度器记 fail，不能静默记 pass\n  if (rows.length > 0 && failed_rows === rows.length) {\n    throw new Error(`upsert_all_failed: ${failed_rows} 行全部写入失败，首个错误: ${String(firstError?.message).slice(0, 200)}`);\n  }\n\n  const failedNames = [...new Set(\n    rows.filter((r) => r.outcome === 'fail' || r.outcome === 'timeout').map((r) => r.trigger_ref),\n  )];\n  // 追赶模式：首轮或游标落后 now 超过 24h（30 天回填 >2000 行要多轮追平），不发连败 Bark，避免历史连败炸出来\n  const catchingUp = cursor === null || cursor < nowMs - CATCHUP_MS;\n  let notified = 0;\n  try {\n    ({ notified } = await notifyFailureStreaks(db, failedNames, { sendBark, firstRound: catchingUp }));\n  } catch (e) {\n    console.warn('[openclaw-run-ingest] 连败告警失败（不影响采集）:', String(e?.message).slice(0, 160));\n  }\n\n  return {\n    fetched: raw.length,\n    written,\n    skipped_rows: skipped,\n    failed_rows,\n    notified,\n    backlog: raw.length === LIMIT_MAX,\n  };\n}\n"
};
const compositions = {
  "remote": "# == us-vps (Linux) Production Environment ==\n# docker-compose.yml 的 Linux 专属版本（决策：Brain us-vps(Linux)部署-compose策略，\n# 拍板\"为 Linux 单建 docker-compose.us-vps.yml，与 macOS 的 docker-compose.yml 互不牵连\"）。\n# 只砍掉账号绑定类挂载（.claude / .codex-team1~5 / .grok ——\n# 按「引擎-机器绑定铁律」Claude/Codex 只在 mmv 跑，us-vps 不需要这些账号挂载，\n# 且这些宿主路径在 Linux 上本来就不存在）。其余挂载全部保留，只是把宿主路径\n# 从 /Users/administrator/... 改指 Linux 路径 /root/...（决策：...凭据挂载裁剪范围细化）。\n#\n# Build first: bash scripts/brain-build.sh\n# Deploy:      bash scripts/brain-deploy.sh（会按 uname -s 自动选到本文件）\n\nname: cecelia\n\nservices:\n  node-brain:\n    image: ${CECELIA_RELEASE_IMAGE:-cecelia-brain:${BRAIN_VERSION:-latest}}\n    container_name: cecelia-node-brain\n    # us-vps 上 Postgres 只监听 127.0.0.1（未对外开放到 docker 网桥），且现役容器一直是这样\n    # 跑的（docker inspect 实测 NetworkMode=host）——沿用 host 网络模式，不走 bridge+端口映射。\n    # host 模式下容器与宿主共享网络栈，容器内 localhost 直接就是宿主 localhost，不需要\n    # ports 段（host 模式下 compose 会拒绝一起声明），也不需要 host.docker.internal 解析。\n    network_mode: host\n    # 生产切换实测(2026-09-11)：read_only:true 会让 fleet worker 的 SSH 控制 socket\n    # 创建失败(unix_listener: cannot bind ... Read-only file system)，跨机器 SSH 多路复用\n    # 功能悄悄失效。现役容器一直以来就是 read_only:false 在跑(docker inspect 实测)，\n    # 沿用这个已验证的宽松策略，不引入这个未经验证的加固。\n    read_only: false\n    tmpfs:\n      - /tmp:size=100M\n      # ssh ControlMaster socket 目录：宿主 /root/.ssh 以 ro 挂入，宿主 ssh config 的\n      # ControlPath 指向 ~/.ssh/sockets/ → 容器内建 socket 撞 Read-only file system，\n      # ops-collector 的 hk-vps ssh 逃逸全灭（09-09 起运行舱账断更 5 天的根因）。\n      # 以 tmpfs 覆盖该子路径恢复可写，不放松 .ssh 本体的 ro。\n      - /root/.ssh/sockets:size=1M\n    volumes:\n      # Docker socket: Brain 调 dockerd spawn 兄弟 pipeline 容器\n      - /var/run/docker.sock:/var/run/docker.sock\n      # Skills SSOT（B57/B58）：.claude/skills/* 是指向这里的 symlink，不 mount 则容器内\n      # symlink 悬空 → harness SKILL 加载失败（loadSkillContent 全 miss）；dist 未 mount 则\n      # Brain 无法 dispatch relay。us-vps 上需要这两个仓库分别 clone 到 /root/ 下。\n      - /root/zenithjoy-skills:/root/zenithjoy-skills:ro\n      - /root/zenithjoy-skills-dist:/root/zenithjoy-skills-dist:ro\n      # OpenClaw 排单模板（Notion 执行方分流 → n8n V4 获客画布，2026-09-14）\n      - /opt/openclaw/dispatch:/opt/openclaw/dispatch:ro\n      # openclaw-guards（决策 95477a66 收编）：守卫 job 需要读写网关配置/路由 conf/agent 教义\n      - /opt/openclaw/state:/opt/openclaw/state\n      - /opt/openclaw/workspaces-root:/opt/openclaw/workspaces-root\n      # 凭据：DB/内部服务凭据 SSOT。下方 environment 段显式 override HOME=/root，\n      # 这样 Brain os.homedir() 才能解析到这里挂载的真实路径（Dockerfile 镜像烙入的\n      # ENV HOME=/Users/administrator 是 macOS 专属值，此前一直未被 override，\n      # 2026-09-12 生产实证：导致 os.homedir() 拼错路径，harness-credentials.js\n      # 读不到这份凭据文件 → github_token_unavailable）。\n      - /root/.credentials:/root/.credentials:ro\n      # 接入控制面唯一可写凭据子目录；宿主必须预建root:root 0700，禁止compose创建宽权限目录。\n      - type: bind\n        source: /root/.credentials/fleet-control\n        target: /run/cecelia-fleet-control\n        bind:\n          create_host_path: false\n      # packages/workflows 不再单独叠只读挂载（09-28 事故，任务 ddee8737）：部署根守卫在本容器内对部署根\n      # git checkout -f / reset --hard，只读子挂载让任何改到该目录的提交都部署失败。该目录随部署根整体可写。\n      # Config: OKR validation spec (read-only, mounted at /config for validate-okr-structure.js)\n      - /root/cecelia/packages/config:/config:ro\n      # HEARTBEAT.md (read-write for GET/PUT API)\n      - /root/cecelia/HEARTBEAT.md:/HEARTBEAT.md:rw\n      # workers.config.json (read-write for PUT /staff/workers API)\n      - /root/cecelia/packages/workflows/staff/workers.config.json:/root/cecelia/packages/workflows/staff/workers.config.json:rw\n      # Worktree 根目录（Brain spawn harness/pipeline 容器时要 mount 宿主 worktree）\n      - /root/cecelia/.claude/worktrees:/root/cecelia/.claude/worktrees:rw\n      - /root/worktrees:/root/worktrees:rw\n      # Content pipeline 产物目录（docker-executor existsFn 检查要求 Brain 可见宿主该路径，\n      # 否则不挂给 pipeline container，产物写到 ephemeral 空间 --rm 丢失。见 PR #2527 后续修）\n      - /root/content-output:/root/content-output:rw\n      - /root/claude-output:/root/claude-output:rw\n      # SSH：pipeline-export.sh 跑 \"ssh nas\" 上传 NAS，docker-executor 挂给 pipeline container\n      - /root/.ssh:/root/.ssh:ro\n      # Git + gh config（harness / pipeline container 做 git commit / gh pr 需要）\n      - /root/.gitconfig:/root/.gitconfig:ro\n      - /root/.config/gh:/root/.config/gh:ro\n      # 部署根：us-vps 只有一份 checkout（不像 macOS 区分\"活人主仓\"和\"CD 专用部署根\"，\n      # us-vps 上没有交互式开发，单一 checkout 同时充当主仓库挂载和 REPO_ROOT）。\n      - /root/cecelia:/root/cecelia:rw\n      # Prompt 文件目录：Brain 写 prompt 文件这里（docker-executor writePromptFile），\n      # 子容器 mount 源必须由宿主 docker daemon 解析 → 必须宿主路径。\n      - /root/claude-output/cecelia-prompts:/tmp/cecelia-prompts:rw\n      # Timezone (read-only)\n      - /etc/localtime:/etc/localtime:ro\n    env_file:\n      - .env.docker\n      # 所有 checkout / cron / 蓝绿部署共用宿主凭据 SSOT；首次部署自动生成。\n      - path: ${CECELIA_INTERNAL_ENV_FILE:-/root/.credentials/cecelia-internal.env}\n        required: false\n    environment:\n      - CECELIA_LINUX_POOL_DEPLOYMENTS_FILE=/run/cecelia-fleet-control/pools.json\n      - CECELIA_LINUX_SCRIPT_DEPLOYMENTS_FILE=/run/cecelia-fleet-control/scripts.json\n      - NODE_ENV=production\n      - TZ=Asia/Shanghai\n      - ENV_REGION=${ENV_REGION:-us}\n      # OpenClaw 已迁 Mac Studio：退役 US 本地控制，保留远端触达观测。\n      - OPENCLAW_GUARD_MODE=remote\n      # Universal Map repo→scope 身份绑定；拒绝仅 basename 相同的跨仓证据冒用。\n      - CECELIA_MAP_REPO_SCOPES=${CECELIA_MAP_REPO_SCOPES:-perfectuser21/cecelia=cecelia,cecelia=cecelia}\n      # Kernel controller 固定留在 US M4；Docker hostname 不是可调度机器身份。\n      - CECELIA_MACHINE_ID=${CECELIA_MACHINE_ID:-us-mac-m4}\n      # Fleet Node admission is mandatory. Brain accepts only these canonical\n      # server-owned Worker endpoints and caches their evidence for at most 90s.\n      # 2026-09-13：默认值从 host.docker.internal 改为 MMV 真实 Tailscale 地址。\n      # 原占位符在 host 网络模式的 Linux 容器里不解析，导致 Claude 类任务（铁律\n      # ca6bf8e7：Claude 只在 MMV 跑）的远程派发目标不可达。MMV 侧 fleet-worker 已于\n      # 同日修好：绑定地址从 127.0.0.1 改为 Tailscale IP，Brain 容器实测 HTTP 200、\n      # docker/container/postgres 全绿。\n      - FLEET_WORKER_US_MAC_M4_URL=${FLEET_WORKER_US_MAC_M4_URL:-http://100.71.151.105:5231}\n      # 本机执行闸（铁律 96054a8b：us-vps 只当调度器，执行全下放 Mac worker）。\n      # 拦在 harness-skill-relay.js 的 spawnSkillRelaySession 咽喉上，拒绝时不建 run。\n      # 注意：故意不用 CECELIA_MACHINE_ID 表达这件事——那个变量的语义是「fleet 可调度\n      # 节点身份 + 凭据签发权」，credential-broker.js:144 与 github-credential-broker.js:36\n      # 硬编码要求它等于 us-mac-m4，改了会掐断凭据签发导致全面 fail-closed（纠正决策\n      # 26c1e763 supersede 962281b2）。所以 CECELIA_MACHINE_ID 保持 us-mac-m4 不动。\n      - CECELIA_LOCAL_EXECUTION_ENABLED=${CECELIA_LOCAL_EXECUTION_ENABLED:-false}\n      # Notion 排单分流 OpenClaw：hk-vps n8n V4 画布（Tailscale HTTPS，实测可达）\n      - N8N_V4_WEBHOOK_URL=${N8N_V4_WEBHOOK_URL:-https://vps-hk.tailce7a8b.ts.net:8444/webhook/agentic-workflow-runner-v4/run}\n      # ops-collector 的 host-exec 逃逸目标：MMV 时代默认 administrator@host.docker.internal\n      # （ssh 回 Mac 宿主），us-vps 是 Linux 该域名不解析且宿主无 launchctl/gh——五条采集腿\n      # 全灭致运行舱账断更（09-09~14 实证）。指到 primary worker MMV（launchctl/gh/hk-vps\n      # 跳板本来就在 Mac）。IP 见 machine-registry.js us-mac-m4.tailscaleIp；Mac Studio 迁移时同步改。\n      - CECELIA_HOST_EXEC_SSH=${CECELIA_HOST_EXEC_SSH:-administrator@100.71.151.105}\n      - FLEET_WORKER_XIAN_MAC_M4_URL=${FLEET_WORKER_XIAN_MAC_M4_URL:-http://100.86.57.69:5231}\n      - FLEET_WORKER_XIAN_MAC_M1_URL=${FLEET_WORKER_XIAN_MAC_M1_URL:-http://100.88.166.55:5231}\n      - FLEET_NODE_ADMISSION_CACHE_TTL_MS=${FLEET_NODE_ADMISSION_CACHE_TTL_MS:-1000}\n      # Phase 4B: all canonical machines use the authenticated Fleet Worker\n      # Attempt API. An absent/short token remains fail-closed in the transport.\n      - KERNEL_FLEET_REMOTE_ENABLED=${KERNEL_FLEET_REMOTE_ENABLED:-true}\n      # KERNEL_FLEET_BRIDGE_TOKEN 只来自 env_file(.env.docker)——不要在这里写\n      # `${KERNEL_FLEET_BRIDGE_TOKEN:-}`：environment 优先级高于 env_file，任何不带\n      # --env-file 的 compose up 都会把 token 盖成空串（2026-08-16 09:38Z 生产实证，\n      # 守卫 scripts/smoke/brain-compose-envfile-authority-smoke.sh）。\n      # Workspace + PostgreSQL + stopped Runner preparation is intentionally\n      # heavier than inspect/start/cancel, so it has an independent budget.\n      - KERNEL_FLEET_PREPARE_TIMEOUT_MS=${KERNEL_FLEET_PREPARE_TIMEOUT_MS:-180000}\n      # Xian Workers must be able to call the US Brain over Tailscale.\n      - KERNEL_FLEET_REMOTE_CALLBACK_BASE_URL=${KERNEL_FLEET_REMOTE_CALLBACK_BASE_URL:-http://100.71.151.105:5221}\n      # host 网络模式下容器与宿主共享网络栈，localhost 直接可达宿主 Postgres（listen 127.0.0.1）\n      - DB_HOST=${DB_HOST:-localhost}\n      - DB_PORT=${DB_PORT:-5432}\n      - DB_NAME=${DB_NAME:-cecelia}\n      - DB_USER=${DB_USER:-cecelia}\n      - DB_PASSWORD=${DB_PASSWORD:-cecelia}\n      # review 门审批 token（issue afc50c30）：只注入 Brain 本容器，relay/harness 执行体\n      # 容器不挂载——执行体物理上无法伪造人工批准。值从部署机根 .env（gitignored）/\n      # ~/.credentials/cecelia-brain.env 注入；缺省空 → 路由 503 fail-closed。\n      - HARNESS_REVIEW_APPROVER_TOKEN=${HARNESS_REVIEW_APPROVER_TOKEN:-}\n      - BRAIN_PORT=5221\n      - CECELIA_TICK_ENABLED=${CECELIA_TICK_ENABLED:-true}\n      # Concurrency: auto-calculated from hardware (CPU/memory) via slot-allocator.js\n      # CECELIA_MAX_SEATS: hard cap on concurrent slots (overrides auto-calc, set 0 to disable)\n      - CECELIA_MAX_SEATS=10\n      # CECELIA_BUDGET_SLOTS: budget-layer cap (< MAX_SEATS), reserves 3 slots for burst buffer + INTERACTIVE_RESERVE\n      - CECELIA_BUDGET_SLOTS=7\n      - CECELIA_TICK_INTERVAL_MS=${CECELIA_TICK_INTERVAL_MS:-5000}\n      - DISPATCH_TIMEOUT_MINUTES=${DISPATCH_TIMEOUT_MINUTES:-60}\n      - FEISHU_BOT_WEBHOOK=${FEISHU_BOT_WEBHOOK:-}\n      # BARK_TOKEN only comes from env_file (.env.docker) — 不要在这里写\n      # `${BARK_TOKEN:-}`：environment 优先级高于 env_file，任何不带宿主 shell\n      # 预先 export BARK_TOKEN 的 `compose up` 都会把 .env.docker 里的真实 token\n      # 盖成空串 → Bark 告警静默失效（2026-09-11 us-vps 生产实证）。\n      # us-vps 上没有交互式 Claude Code（引擎-机器绑定铁律），此路径不会被真正调用，\n      # 保留字段结构一致性，值指向本机 REPO_ROOT 对应位置。\n      - CECELIA_RUN_PATH=/root/cecelia/packages/brain/scripts/cecelia-run.sh\n      # Dockerfile 镜像烙入 ENV HOME=/Users/administrator（macOS 专属，供 macOS 侧\n      # os.homedir()/docker-executor 子容器 mount 路径对齐用）。Linux 上必须显式\n      # override 成真实宿主 home，否则容器内所有直接调用 os.homedir() 的代码\n      # （如 harness-credentials.js 解析 GitHub token 文件路径）都会拼错成一个\n      # 容器内不存在的路径。2026-09-12 生产实证：golden_path_proposal 任务因此\n      # 报 github_token_unavailable。\n      - HOME=/root\n      - HOST_HOME=/root\n      # 部署根：us-vps 单一 checkout 同时充当 REPO_ROOT（见上方 volumes 注释）\n      - REPO_ROOT=/root/cecelia\n      # 专用部署根，deploy-local.sh 守卫自愈到 origin/main（脏/落后时硬 reset 而非静默降级）\n      - CECELIA_DEPLOY_AUTORESET=1\n      # Codex CLI 容器内位置（由 Dockerfile npm install -g @openai/codex 装到 /usr/local/bin/codex）\n      # us-vps 上不会有 codex relay 子容器被派发（Codex 只在 mmv 跑），保留常量避免代码里\n      # 读取 undefined 路径；CODEX_HOME/CODEX_RELAY_HOME 因对应挂载已裁剪，不注入。\n      - CODEX_BIN=/usr/local/bin/codex\n      # Brain 容器里 /tmp/cecelia-prompts 对应的宿主路径（docker-executor 用它构造子容器 mount 源）\n      - HOST_PROMPT_DIR=/root/claude-output/cecelia-prompts\n      # ZenithJoy API — harness-sprint-state skill 写 sprint_states/journey_steps 用\n      - BRAIN_API=http://host.docker.internal:5200\n      # ZenithJoy 蓝绿护栏：staging-e2e-runner.js 健康检查 :5201，需指向宿主（容器内 localhost 不通宿主端口）\n      - ZJ_STAGING_HOST=host.docker.internal\n      # P0-fix: Brain 写发布回执到独立 zenithjoy 库（zenithjoy-db.js 依赖此变量）\n      # 未设 → 静默落回 cecelia.zenithjoy schema（拆库目的失效）\n      - ZENITHJOY_DB_NAME=zenithjoy\n      # Notion Inbox 采集凭据（F6加厚，notion-capture-ingest.js）\n      # 未配置时静默跳过，不影响其他 job（fail-open，非关键路径）\n      - NOTION_INBOX_TOKEN=${NOTION_INBOX_TOKEN:-}\n      - NOTION_INBOX_DB_ID=${NOTION_INBOX_DB_ID:-b45ca2cb-9c90-83f1-bc41-81ad0b86c1b1}\n      # OPENAI_API_KEY is provided via env_file (.env.docker) — do NOT override here\n      # FEISHU_OWNER_OPEN_IDS is provided via env_file (.env.docker) — same reason, do NOT override here\n      # ⚠️ 已知遗留（2026-09-13 部分消除）：BRAIN_API/ZJ_STAGING_HOST 两个默认值仍是\n      # host.docker.internal，host 网络模式下这个域名不会被解析——它们指向的服务本来就在\n      # 别的物理机（mmv/M4），跟网络模式无关，us-vps 真正需要这些功能时必须在 .env.docker\n      # 里显式覆盖成对应机器的真实 Tailscale 地址。\n      # FLEET_WORKER_US_MAC_M4_URL 已于 2026-09-13 就地改成真实地址（见上），不再属于此遗留：\n      # 实测 .env.docker 里从未定义过它，所以「必须显式覆盖」这条从来没被兑现，默认值一直生效。\n    # compose standalone cgroup 限额（deploy.resources 只在 Docker Swarm 模式生效）\n    # us-vps 零执行铁律物理闸（决策 95477a66）：宿主仅 3.8G，原 4g limit > 整机 = 零保护，\n    # Brain 失控可拖死全机。收紧至 2.5g——Brain 常态数百 MB，2.5G 已是 5 倍余量；\n    # node 堆上限仍为 3072（Dockerfile CMD），极端下堆超 2.5G 会被 cgroup 硬杀并由\n    # restart 拉起（in_progress 恢复机制已有）——宁可 Brain 单死重启，不可整机陪葬。\n    # debt: 后续把 CMD 堆参数对齐到 2048 以恢复\"先 GC 后杀\"的正常次序。\n    mem_limit: 2.5g\n    mem_reservation: 1g\n    cpus: 2.0\n    deploy:\n      resources:\n        limits:\n          memory: 2.5G\n          cpus: '2'\n        reservations:\n          memory: 1G\n    restart: unless-stopped\n    healthcheck:\n      test: [\"CMD\", \"curl\", \"-f\", \"http://localhost:5221/api/brain/tick/status\"]\n      interval: 30s\n      timeout: 10s\n      retries: 3\n      start_period: 40s\n    logging:\n      driver: \"json-file\"\n      options:\n        max-size: \"10m\"\n        max-file: \"3\"\n",
  "template": "# == us-vps (Linux) Production Environment ==\n# docker-compose.yml 的 Linux 专属版本（决策：Brain us-vps(Linux)部署-compose策略，\n# 拍板\"为 Linux 单建 docker-compose.us-vps.yml，与 macOS 的 docker-compose.yml 互不牵连\"）。\n# 只砍掉账号绑定类挂载（.claude / .codex-team1~5 / .grok ——\n# 按「引擎-机器绑定铁律」Claude/Codex 只在 mmv 跑，us-vps 不需要这些账号挂载，\n# 且这些宿主路径在 Linux 上本来就不存在）。其余挂载全部保留，只是把宿主路径\n# 从 /Users/administrator/... 改指 Linux 路径 /root/...（决策：...凭据挂载裁剪范围细化）。\n#\n# Build first: bash scripts/brain-build.sh\n# Deploy:      bash scripts/brain-deploy.sh（会按 uname -s 自动选到本文件）\n\nname: cecelia\n\nservices:\n  node-brain:\n    image: ${CECELIA_RELEASE_IMAGE:-cecelia-brain:${BRAIN_VERSION:-latest}}\n    container_name: cecelia-node-brain\n    # us-vps 上 Postgres 只监听 127.0.0.1（未对外开放到 docker 网桥），且现役容器一直是这样\n    # 跑的（docker inspect 实测 NetworkMode=host）——沿用 host 网络模式，不走 bridge+端口映射。\n    # host 模式下容器与宿主共享网络栈，容器内 localhost 直接就是宿主 localhost，不需要\n    # ports 段（host 模式下 compose 会拒绝一起声明），也不需要 host.docker.internal 解析。\n    network_mode: host\n    # 生产切换实测(2026-09-11)：read_only:true 会让 fleet worker 的 SSH 控制 socket\n    # 创建失败(unix_listener: cannot bind ... Read-only file system)，跨机器 SSH 多路复用\n    # 功能悄悄失效。现役容器一直以来就是 read_only:false 在跑(docker inspect 实测)，\n    # 沿用这个已验证的宽松策略，不引入这个未经验证的加固。\n    read_only: false\n    tmpfs:\n      - /tmp:size=100M\n      # ssh ControlMaster socket 目录：宿主 /root/.ssh 以 ro 挂入，宿主 ssh config 的\n      # ControlPath 指向 ~/.ssh/sockets/ → 容器内建 socket 撞 Read-only file system，\n      # ops-collector 的 hk-vps ssh 逃逸全灭（09-09 起运行舱账断更 5 天的根因）。\n      # 以 tmpfs 覆盖该子路径恢复可写，不放松 .ssh 本体的 ro。\n      - /root/.ssh/sockets:size=1M\n    volumes:\n      # Docker socket: Brain 调 dockerd spawn 兄弟 pipeline 容器\n      - /var/run/docker.sock:/var/run/docker.sock\n      # Skills SSOT（B57/B58）：.claude/skills/* 是指向这里的 symlink，不 mount 则容器内\n      # symlink 悬空 → harness SKILL 加载失败（loadSkillContent 全 miss）；dist 未 mount 则\n      # Brain 无法 dispatch relay。us-vps 上需要这两个仓库分别 clone 到 /root/ 下。\n      - /root/zenithjoy-skills:/root/zenithjoy-skills:ro\n      - /root/zenithjoy-skills-dist:/root/zenithjoy-skills-dist:ro\n      # 派发默认模板随 Brain 发布，凭据由现有只读 ~/.credentials 挂载注入。\n      # openclaw-guards（决策 95477a66 收编）：守卫 job 需要读写网关配置/路由 conf/agent 教义\n      - /opt/openclaw/state:/opt/openclaw/state\n      - /opt/openclaw/workspaces-root:/opt/openclaw/workspaces-root\n      # 凭据：DB/内部服务凭据 SSOT。下方 environment 段显式 override HOME=/root，\n      # 这样 Brain os.homedir() 才能解析到这里挂载的真实路径（Dockerfile 镜像烙入的\n      # ENV HOME=/Users/administrator 是 macOS 专属值，此前一直未被 override，\n      # 2026-09-12 生产实证：导致 os.homedir() 拼错路径，harness-credentials.js\n      # 读不到这份凭据文件 → github_token_unavailable）。\n      - /root/.credentials:/root/.credentials:ro\n      # 接入控制面唯一可写凭据子目录；宿主必须预建root:root 0700，禁止compose创建宽权限目录。\n      - type: bind\n        source: /root/.credentials/fleet-control\n        target: /run/cecelia-fleet-control\n        bind:\n          create_host_path: false\n      # packages/workflows 不再单独叠只读挂载（09-28 事故，任务 ddee8737）：部署根守卫在本容器内对部署根\n      # git checkout -f / reset --hard，只读子挂载让任何改到该目录的提交都部署失败。该目录随部署根整体可写。\n      # Config: OKR validation spec (read-only, mounted at /config for validate-okr-structure.js)\n      - /root/cecelia/packages/config:/config:ro\n      # HEARTBEAT.md (read-write for GET/PUT API)\n      - /root/cecelia/HEARTBEAT.md:/HEARTBEAT.md:rw\n      # workers.config.json (read-write for PUT /staff/workers API)\n      - /root/cecelia/packages/workflows/staff/workers.config.json:/root/cecelia/packages/workflows/staff/workers.config.json:rw\n      # Worktree 根目录（Brain spawn harness/pipeline 容器时要 mount 宿主 worktree）\n      - /root/cecelia/.claude/worktrees:/root/cecelia/.claude/worktrees:rw\n      - /root/worktrees:/root/worktrees:rw\n      # Content pipeline 产物目录（docker-executor existsFn 检查要求 Brain 可见宿主该路径，\n      # 否则不挂给 pipeline container，产物写到 ephemeral 空间 --rm 丢失。见 PR #2527 后续修）\n      - /root/content-output:/root/content-output:rw\n      - /root/claude-output:/root/claude-output:rw\n      # SSH：pipeline-export.sh 跑 \"ssh nas\" 上传 NAS，docker-executor 挂给 pipeline container\n      - /root/.ssh:/root/.ssh:ro\n      # Git + gh config（harness / pipeline container 做 git commit / gh pr 需要）\n      - /root/.gitconfig:/root/.gitconfig:ro\n      - /root/.config/gh:/root/.config/gh:ro\n      # 部署根：us-vps 只有一份 checkout（不像 macOS 区分\"活人主仓\"和\"CD 专用部署根\"，\n      # us-vps 上没有交互式开发，单一 checkout 同时充当主仓库挂载和 REPO_ROOT）。\n      - /root/cecelia:/root/cecelia:rw\n      # Prompt 文件目录：Brain 写 prompt 文件这里（docker-executor writePromptFile），\n      # 子容器 mount 源必须由宿主 docker daemon 解析 → 必须宿主路径。\n      - /root/claude-output/cecelia-prompts:/tmp/cecelia-prompts:rw\n      # Timezone (read-only)\n      - /etc/localtime:/etc/localtime:ro\n    env_file:\n      - .env.docker\n      # 所有 checkout / cron / 蓝绿部署共用宿主凭据 SSOT；首次部署自动生成。\n      - path: ${CECELIA_INTERNAL_ENV_FILE:-/root/.credentials/cecelia-internal.env}\n        required: false\n    environment:\n      - CECELIA_LINUX_POOL_DEPLOYMENTS_FILE=/run/cecelia-fleet-control/pools.json\n      - CECELIA_LINUX_SCRIPT_DEPLOYMENTS_FILE=/run/cecelia-fleet-control/scripts.json\n      - NODE_ENV=production\n      - TZ=Asia/Shanghai\n      - ENV_REGION=${ENV_REGION:-us}\n      # Universal Map repo→scope 身份绑定；拒绝仅 basename 相同的跨仓证据冒用。\n      - CECELIA_MAP_REPO_SCOPES=${CECELIA_MAP_REPO_SCOPES:-perfectuser21/cecelia=cecelia,cecelia=cecelia}\n      # Kernel controller 固定留在 US M4；Docker hostname 不是可调度机器身份。\n      - CECELIA_MACHINE_ID=${CECELIA_MACHINE_ID:-us-mac-m4}\n      # Fleet Node admission is mandatory. Brain accepts only these canonical\n      # server-owned Worker endpoints and caches their evidence for at most 90s.\n      # 2026-09-13：默认值从 host.docker.internal 改为 MMV 真实 Tailscale 地址。\n      # 原占位符在 host 网络模式的 Linux 容器里不解析，导致 Claude 类任务（铁律\n      # ca6bf8e7：Claude 只在 MMV 跑）的远程派发目标不可达。MMV 侧 fleet-worker 已于\n      # 同日修好：绑定地址从 127.0.0.1 改为 Tailscale IP，Brain 容器实测 HTTP 200、\n      # docker/container/postgres 全绿。\n      - FLEET_WORKER_US_MAC_M4_URL=${FLEET_WORKER_US_MAC_M4_URL:-http://100.71.151.105:5231}\n      # 本机执行闸（铁律 96054a8b：us-vps 只当调度器，执行全下放 Mac worker）。\n      # 拦在 harness-skill-relay.js 的 spawnSkillRelaySession 咽喉上，拒绝时不建 run。\n      # 注意：故意不用 CECELIA_MACHINE_ID 表达这件事——那个变量的语义是「fleet 可调度\n      # 节点身份 + 凭据签发权」，credential-broker.js:144 与 github-credential-broker.js:36\n      # 硬编码要求它等于 us-mac-m4，改了会掐断凭据签发导致全面 fail-closed（纠正决策\n      # 26c1e763 supersede 962281b2）。所以 CECELIA_MACHINE_ID 保持 us-mac-m4 不动。\n      - CECELIA_LOCAL_EXECUTION_ENABLED=${CECELIA_LOCAL_EXECUTION_ENABLED:-false}\n      # Notion 排单分流 OpenClaw：hk-vps n8n V4 画布（Tailscale HTTPS，实测可达）\n      - N8N_V4_WEBHOOK_URL=${N8N_V4_WEBHOOK_URL:-https://vps-hk.tailce7a8b.ts.net:8444/webhook/agentic-workflow-runner-v4/run}\n      # ops-collector 的 host-exec 逃逸目标：MMV 时代默认 administrator@host.docker.internal\n      # （ssh 回 Mac 宿主），us-vps 是 Linux 该域名不解析且宿主无 launchctl/gh——五条采集腿\n      # 全灭致运行舱账断更（09-09~14 实证）。指到 primary worker MMV（launchctl/gh/hk-vps\n      # 跳板本来就在 Mac）。IP 见 machine-registry.js us-mac-m4.tailscaleIp；Mac Studio 迁移时同步改。\n      - CECELIA_HOST_EXEC_SSH=${CECELIA_HOST_EXEC_SSH:-administrator@100.71.151.105}\n      - FLEET_WORKER_XIAN_MAC_M4_URL=${FLEET_WORKER_XIAN_MAC_M4_URL:-http://100.86.57.69:5231}\n      - FLEET_WORKER_XIAN_MAC_M1_URL=${FLEET_WORKER_XIAN_MAC_M1_URL:-http://100.88.166.55:5231}\n      - FLEET_NODE_ADMISSION_CACHE_TTL_MS=${FLEET_NODE_ADMISSION_CACHE_TTL_MS:-1000}\n      # Phase 4B: all canonical machines use the authenticated Fleet Worker\n      # Attempt API. An absent/short token remains fail-closed in the transport.\n      - KERNEL_FLEET_REMOTE_ENABLED=${KERNEL_FLEET_REMOTE_ENABLED:-true}\n      # KERNEL_FLEET_BRIDGE_TOKEN 只来自 env_file(.env.docker)——不要在这里写\n      # `${KERNEL_FLEET_BRIDGE_TOKEN:-}`：environment 优先级高于 env_file，任何不带\n      # --env-file 的 compose up 都会把 token 盖成空串（2026-08-16 09:38Z 生产实证，\n      # 守卫 scripts/smoke/brain-compose-envfile-authority-smoke.sh）。\n      # Workspace + PostgreSQL + stopped Runner preparation is intentionally\n      # heavier than inspect/start/cancel, so it has an independent budget.\n      - KERNEL_FLEET_PREPARE_TIMEOUT_MS=${KERNEL_FLEET_PREPARE_TIMEOUT_MS:-180000}\n      # Xian Workers must be able to call the US Brain over Tailscale.\n      - KERNEL_FLEET_REMOTE_CALLBACK_BASE_URL=${KERNEL_FLEET_REMOTE_CALLBACK_BASE_URL:-http://100.71.151.105:5221}\n      # host 网络模式下容器与宿主共享网络栈，localhost 直接可达宿主 Postgres（listen 127.0.0.1）\n      - DB_HOST=${DB_HOST:-localhost}\n      - DB_PORT=${DB_PORT:-5432}\n      - DB_NAME=${DB_NAME:-cecelia}\n      - DB_USER=${DB_USER:-cecelia}\n      - DB_PASSWORD=${DB_PASSWORD:-cecelia}\n      # review 门审批 token（issue afc50c30）：只注入 Brain 本容器，relay/harness 执行体\n      # 容器不挂载——执行体物理上无法伪造人工批准。值从部署机根 .env（gitignored）/\n      # ~/.credentials/cecelia-brain.env 注入；缺省空 → 路由 503 fail-closed。\n      - HARNESS_REVIEW_APPROVER_TOKEN=${HARNESS_REVIEW_APPROVER_TOKEN:-}\n      - BRAIN_PORT=5221\n      - CECELIA_TICK_ENABLED=${CECELIA_TICK_ENABLED:-true}\n      # Concurrency: auto-calculated from hardware (CPU/memory) via slot-allocator.js\n      # CECELIA_MAX_SEATS: hard cap on concurrent slots (overrides auto-calc, set 0 to disable)\n      - CECELIA_MAX_SEATS=10\n      # CECELIA_BUDGET_SLOTS: budget-layer cap (< MAX_SEATS), reserves 3 slots for burst buffer + INTERACTIVE_RESERVE\n      - CECELIA_BUDGET_SLOTS=7\n      - CECELIA_TICK_INTERVAL_MS=${CECELIA_TICK_INTERVAL_MS:-5000}\n      - DISPATCH_TIMEOUT_MINUTES=${DISPATCH_TIMEOUT_MINUTES:-60}\n      - FEISHU_BOT_WEBHOOK=${FEISHU_BOT_WEBHOOK:-}\n      # BARK_TOKEN only comes from env_file (.env.docker) — 不要在这里写\n      # `${BARK_TOKEN:-}`：environment 优先级高于 env_file，任何不带宿主 shell\n      # 预先 export BARK_TOKEN 的 `compose up` 都会把 .env.docker 里的真实 token\n      # 盖成空串 → Bark 告警静默失效（2026-09-11 us-vps 生产实证）。\n      # us-vps 上没有交互式 Claude Code（引擎-机器绑定铁律），此路径不会被真正调用，\n      # 保留字段结构一致性，值指向本机 REPO_ROOT 对应位置。\n      - CECELIA_RUN_PATH=/root/cecelia/packages/brain/scripts/cecelia-run.sh\n      # Dockerfile 镜像烙入 ENV HOME=/Users/administrator（macOS 专属，供 macOS 侧\n      # os.homedir()/docker-executor 子容器 mount 路径对齐用）。Linux 上必须显式\n      # override 成真实宿主 home，否则容器内所有直接调用 os.homedir() 的代码\n      # （如 harness-credentials.js 解析 GitHub token 文件路径）都会拼错成一个\n      # 容器内不存在的路径。2026-09-12 生产实证：golden_path_proposal 任务因此\n      # 报 github_token_unavailable。\n      - HOME=/root\n      - HOST_HOME=/root\n      # 部署根：us-vps 单一 checkout 同时充当 REPO_ROOT（见上方 volumes 注释）\n      - REPO_ROOT=/root/cecelia\n      # 专用部署根，deploy-local.sh 守卫自愈到 origin/main（脏/落后时硬 reset 而非静默降级）\n      - CECELIA_DEPLOY_AUTORESET=1\n      # Codex CLI 容器内位置（由 Dockerfile npm install -g @openai/codex 装到 /usr/local/bin/codex）\n      # us-vps 上不会有 codex relay 子容器被派发（Codex 只在 mmv 跑），保留常量避免代码里\n      # 读取 undefined 路径；CODEX_HOME/CODEX_RELAY_HOME 因对应挂载已裁剪，不注入。\n      - CODEX_BIN=/usr/local/bin/codex\n      # Brain 容器里 /tmp/cecelia-prompts 对应的宿主路径（docker-executor 用它构造子容器 mount 源）\n      - HOST_PROMPT_DIR=/root/claude-output/cecelia-prompts\n      # ZenithJoy API — harness-sprint-state skill 写 sprint_states/journey_steps 用\n      - BRAIN_API=http://host.docker.internal:5200\n      # ZenithJoy 蓝绿护栏：staging-e2e-runner.js 健康检查 :5201，需指向宿主（容器内 localhost 不通宿主端口）\n      - ZJ_STAGING_HOST=host.docker.internal\n      # P0-fix: Brain 写发布回执到独立 zenithjoy 库（zenithjoy-db.js 依赖此变量）\n      # 未设 → 静默落回 cecelia.zenithjoy schema（拆库目的失效）\n      - ZENITHJOY_DB_NAME=zenithjoy\n      # Notion Inbox 采集凭据（F6加厚，notion-capture-ingest.js）\n      # 未配置时静默跳过，不影响其他 job（fail-open，非关键路径）\n      - NOTION_INBOX_TOKEN=${NOTION_INBOX_TOKEN:-}\n      - NOTION_INBOX_DB_ID=${NOTION_INBOX_DB_ID:-b45ca2cb-9c90-83f1-bc41-81ad0b86c1b1}\n      # OPENAI_API_KEY is provided via env_file (.env.docker) — do NOT override here\n      # FEISHU_OWNER_OPEN_IDS is provided via env_file (.env.docker) — same reason, do NOT override here\n      # ⚠️ 已知遗留（2026-09-13 部分消除）：BRAIN_API/ZJ_STAGING_HOST 两个默认值仍是\n      # host.docker.internal，host 网络模式下这个域名不会被解析——它们指向的服务本来就在\n      # 别的物理机（mmv/M4），跟网络模式无关，us-vps 真正需要这些功能时必须在 .env.docker\n      # 里显式覆盖成对应机器的真实 Tailscale 地址。\n      # FLEET_WORKER_US_MAC_M4_URL 已于 2026-09-13 就地改成真实地址（见上），不再属于此遗留：\n      # 实测 .env.docker 里从未定义过它，所以「必须显式覆盖」这条从来没被兑现，默认值一直生效。\n    # compose standalone cgroup 限额（deploy.resources 只在 Docker Swarm 模式生效）\n    # us-vps 零执行铁律物理闸（决策 95477a66）：宿主仅 3.8G，原 4g limit > 整机 = 零保护，\n    # Brain 失控可拖死全机。收紧至 2.5g——Brain 常态数百 MB，2.5G 已是 5 倍余量；\n    # node 堆上限仍为 3072（Dockerfile CMD），极端下堆超 2.5G 会被 cgroup 硬杀并由\n    # restart 拉起（in_progress 恢复机制已有）——宁可 Brain 单死重启，不可整机陪葬。\n    # debt: 后续把 CMD 堆参数对齐到 2048 以恢复\"先 GC 后杀\"的正常次序。\n    mem_limit: 2.5g\n    mem_reservation: 1g\n    cpus: 2.0\n    deploy:\n      resources:\n        limits:\n          memory: 2.5G\n          cpus: '2'\n        reservations:\n          memory: 1G\n    restart: unless-stopped\n    healthcheck:\n      test: [\"CMD\", \"curl\", \"-f\", \"http://localhost:5221/api/brain/tick/status\"]\n      interval: 30s\n      timeout: 10s\n      retries: 3\n      start_period: 40s\n    logging:\n      driver: \"json-file\"\n      options:\n        max-size: \"10m\"\n        max-file: \"3\"\n",
  "combined": "# == us-vps (Linux) Production Environment ==\n# docker-compose.yml 的 Linux 专属版本（决策：Brain us-vps(Linux)部署-compose策略，\n# 拍板\"为 Linux 单建 docker-compose.us-vps.yml，与 macOS 的 docker-compose.yml 互不牵连\"）。\n# 只砍掉账号绑定类挂载（.claude / .codex-team1~5 / .grok ——\n# 按「引擎-机器绑定铁律」Claude/Codex 只在 mmv 跑，us-vps 不需要这些账号挂载，\n# 且这些宿主路径在 Linux 上本来就不存在）。其余挂载全部保留，只是把宿主路径\n# 从 /Users/administrator/... 改指 Linux 路径 /root/...（决策：...凭据挂载裁剪范围细化）。\n#\n# Build first: bash scripts/brain-build.sh\n# Deploy:      bash scripts/brain-deploy.sh（会按 uname -s 自动选到本文件）\n\nname: cecelia\n\nservices:\n  node-brain:\n    image: ${CECELIA_RELEASE_IMAGE:-cecelia-brain:${BRAIN_VERSION:-latest}}\n    container_name: cecelia-node-brain\n    # us-vps 上 Postgres 只监听 127.0.0.1（未对外开放到 docker 网桥），且现役容器一直是这样\n    # 跑的（docker inspect 实测 NetworkMode=host）——沿用 host 网络模式，不走 bridge+端口映射。\n    # host 模式下容器与宿主共享网络栈，容器内 localhost 直接就是宿主 localhost，不需要\n    # ports 段（host 模式下 compose 会拒绝一起声明），也不需要 host.docker.internal 解析。\n    network_mode: host\n    # 生产切换实测(2026-09-11)：read_only:true 会让 fleet worker 的 SSH 控制 socket\n    # 创建失败(unix_listener: cannot bind ... Read-only file system)，跨机器 SSH 多路复用\n    # 功能悄悄失效。现役容器一直以来就是 read_only:false 在跑(docker inspect 实测)，\n    # 沿用这个已验证的宽松策略，不引入这个未经验证的加固。\n    read_only: false\n    tmpfs:\n      - /tmp:size=100M\n      # ssh ControlMaster socket 目录：宿主 /root/.ssh 以 ro 挂入，宿主 ssh config 的\n      # ControlPath 指向 ~/.ssh/sockets/ → 容器内建 socket 撞 Read-only file system，\n      # ops-collector 的 hk-vps ssh 逃逸全灭（09-09 起运行舱账断更 5 天的根因）。\n      # 以 tmpfs 覆盖该子路径恢复可写，不放松 .ssh 本体的 ro。\n      - /root/.ssh/sockets:size=1M\n    volumes:\n      # Docker socket: Brain 调 dockerd spawn 兄弟 pipeline 容器\n      - /var/run/docker.sock:/var/run/docker.sock\n      # Skills SSOT（B57/B58）：.claude/skills/* 是指向这里的 symlink，不 mount 则容器内\n      # symlink 悬空 → harness SKILL 加载失败（loadSkillContent 全 miss）；dist 未 mount 则\n      # Brain 无法 dispatch relay。us-vps 上需要这两个仓库分别 clone 到 /root/ 下。\n      - /root/zenithjoy-skills:/root/zenithjoy-skills:ro\n      - /root/zenithjoy-skills-dist:/root/zenithjoy-skills-dist:ro\n      # 派发默认模板随 Brain 发布，凭据由现有只读 ~/.credentials 挂载注入。\n      # openclaw-guards（决策 95477a66 收编）：守卫 job 需要读写网关配置/路由 conf/agent 教义\n      - /opt/openclaw/state:/opt/openclaw/state\n      - /opt/openclaw/workspaces-root:/opt/openclaw/workspaces-root\n      # 凭据：DB/内部服务凭据 SSOT。下方 environment 段显式 override HOME=/root，\n      # 这样 Brain os.homedir() 才能解析到这里挂载的真实路径（Dockerfile 镜像烙入的\n      # ENV HOME=/Users/administrator 是 macOS 专属值，此前一直未被 override，\n      # 2026-09-12 生产实证：导致 os.homedir() 拼错路径，harness-credentials.js\n      # 读不到这份凭据文件 → github_token_unavailable）。\n      - /root/.credentials:/root/.credentials:ro\n      # 接入控制面唯一可写凭据子目录；宿主必须预建root:root 0700，禁止compose创建宽权限目录。\n      - type: bind\n        source: /root/.credentials/fleet-control\n        target: /run/cecelia-fleet-control\n        bind:\n          create_host_path: false\n      # packages/workflows 不再单独叠只读挂载（09-28 事故，任务 ddee8737）：部署根守卫在本容器内对部署根\n      # git checkout -f / reset --hard，只读子挂载让任何改到该目录的提交都部署失败。该目录随部署根整体可写。\n      # Config: OKR validation spec (read-only, mounted at /config for validate-okr-structure.js)\n      - /root/cecelia/packages/config:/config:ro\n      # HEARTBEAT.md (read-write for GET/PUT API)\n      - /root/cecelia/HEARTBEAT.md:/HEARTBEAT.md:rw\n      # workers.config.json (read-write for PUT /staff/workers API)\n      - /root/cecelia/packages/workflows/staff/workers.config.json:/root/cecelia/packages/workflows/staff/workers.config.json:rw\n      # Worktree 根目录（Brain spawn harness/pipeline 容器时要 mount 宿主 worktree）\n      - /root/cecelia/.claude/worktrees:/root/cecelia/.claude/worktrees:rw\n      - /root/worktrees:/root/worktrees:rw\n      # Content pipeline 产物目录（docker-executor existsFn 检查要求 Brain 可见宿主该路径，\n      # 否则不挂给 pipeline container，产物写到 ephemeral 空间 --rm 丢失。见 PR #2527 后续修）\n      - /root/content-output:/root/content-output:rw\n      - /root/claude-output:/root/claude-output:rw\n      # SSH：pipeline-export.sh 跑 \"ssh nas\" 上传 NAS，docker-executor 挂给 pipeline container\n      - /root/.ssh:/root/.ssh:ro\n      # Git + gh config（harness / pipeline container 做 git commit / gh pr 需要）\n      - /root/.gitconfig:/root/.gitconfig:ro\n      - /root/.config/gh:/root/.config/gh:ro\n      # 部署根：us-vps 只有一份 checkout（不像 macOS 区分\"活人主仓\"和\"CD 专用部署根\"，\n      # us-vps 上没有交互式开发，单一 checkout 同时充当主仓库挂载和 REPO_ROOT）。\n      - /root/cecelia:/root/cecelia:rw\n      # Prompt 文件目录：Brain 写 prompt 文件这里（docker-executor writePromptFile），\n      # 子容器 mount 源必须由宿主 docker daemon 解析 → 必须宿主路径。\n      - /root/claude-output/cecelia-prompts:/tmp/cecelia-prompts:rw\n      # Timezone (read-only)\n      - /etc/localtime:/etc/localtime:ro\n    env_file:\n      - .env.docker\n      # 所有 checkout / cron / 蓝绿部署共用宿主凭据 SSOT；首次部署自动生成。\n      - path: ${CECELIA_INTERNAL_ENV_FILE:-/root/.credentials/cecelia-internal.env}\n        required: false\n    environment:\n      - CECELIA_LINUX_POOL_DEPLOYMENTS_FILE=/run/cecelia-fleet-control/pools.json\n      - CECELIA_LINUX_SCRIPT_DEPLOYMENTS_FILE=/run/cecelia-fleet-control/scripts.json\n      - NODE_ENV=production\n      - TZ=Asia/Shanghai\n      - ENV_REGION=${ENV_REGION:-us}\n      # OpenClaw 已迁 Mac Studio：退役 US 本地控制，保留远端触达观测。\n      - OPENCLAW_GUARD_MODE=remote\n      # Universal Map repo→scope 身份绑定；拒绝仅 basename 相同的跨仓证据冒用。\n      - CECELIA_MAP_REPO_SCOPES=${CECELIA_MAP_REPO_SCOPES:-perfectuser21/cecelia=cecelia,cecelia=cecelia}\n      # Kernel controller 固定留在 US M4；Docker hostname 不是可调度机器身份。\n      - CECELIA_MACHINE_ID=${CECELIA_MACHINE_ID:-us-mac-m4}\n      # Fleet Node admission is mandatory. Brain accepts only these canonical\n      # server-owned Worker endpoints and caches their evidence for at most 90s.\n      # 2026-09-13：默认值从 host.docker.internal 改为 MMV 真实 Tailscale 地址。\n      # 原占位符在 host 网络模式的 Linux 容器里不解析，导致 Claude 类任务（铁律\n      # ca6bf8e7：Claude 只在 MMV 跑）的远程派发目标不可达。MMV 侧 fleet-worker 已于\n      # 同日修好：绑定地址从 127.0.0.1 改为 Tailscale IP，Brain 容器实测 HTTP 200、\n      # docker/container/postgres 全绿。\n      - FLEET_WORKER_US_MAC_M4_URL=${FLEET_WORKER_US_MAC_M4_URL:-http://100.71.151.105:5231}\n      # 本机执行闸（铁律 96054a8b：us-vps 只当调度器，执行全下放 Mac worker）。\n      # 拦在 harness-skill-relay.js 的 spawnSkillRelaySession 咽喉上，拒绝时不建 run。\n      # 注意：故意不用 CECELIA_MACHINE_ID 表达这件事——那个变量的语义是「fleet 可调度\n      # 节点身份 + 凭据签发权」，credential-broker.js:144 与 github-credential-broker.js:36\n      # 硬编码要求它等于 us-mac-m4，改了会掐断凭据签发导致全面 fail-closed（纠正决策\n      # 26c1e763 supersede 962281b2）。所以 CECELIA_MACHINE_ID 保持 us-mac-m4 不动。\n      - CECELIA_LOCAL_EXECUTION_ENABLED=${CECELIA_LOCAL_EXECUTION_ENABLED:-false}\n      # Notion 排单分流 OpenClaw：hk-vps n8n V4 画布（Tailscale HTTPS，实测可达）\n      - N8N_V4_WEBHOOK_URL=${N8N_V4_WEBHOOK_URL:-https://vps-hk.tailce7a8b.ts.net:8444/webhook/agentic-workflow-runner-v4/run}\n      # ops-collector 的 host-exec 逃逸目标：MMV 时代默认 administrator@host.docker.internal\n      # （ssh 回 Mac 宿主），us-vps 是 Linux 该域名不解析且宿主无 launchctl/gh——五条采集腿\n      # 全灭致运行舱账断更（09-09~14 实证）。指到 primary worker MMV（launchctl/gh/hk-vps\n      # 跳板本来就在 Mac）。IP 见 machine-registry.js us-mac-m4.tailscaleIp；Mac Studio 迁移时同步改。\n      - CECELIA_HOST_EXEC_SSH=${CECELIA_HOST_EXEC_SSH:-administrator@100.71.151.105}\n      - FLEET_WORKER_XIAN_MAC_M4_URL=${FLEET_WORKER_XIAN_MAC_M4_URL:-http://100.86.57.69:5231}\n      - FLEET_WORKER_XIAN_MAC_M1_URL=${FLEET_WORKER_XIAN_MAC_M1_URL:-http://100.88.166.55:5231}\n      - FLEET_NODE_ADMISSION_CACHE_TTL_MS=${FLEET_NODE_ADMISSION_CACHE_TTL_MS:-1000}\n      # Phase 4B: all canonical machines use the authenticated Fleet Worker\n      # Attempt API. An absent/short token remains fail-closed in the transport.\n      - KERNEL_FLEET_REMOTE_ENABLED=${KERNEL_FLEET_REMOTE_ENABLED:-true}\n      # KERNEL_FLEET_BRIDGE_TOKEN 只来自 env_file(.env.docker)——不要在这里写\n      # `${KERNEL_FLEET_BRIDGE_TOKEN:-}`：environment 优先级高于 env_file，任何不带\n      # --env-file 的 compose up 都会把 token 盖成空串（2026-08-16 09:38Z 生产实证，\n      # 守卫 scripts/smoke/brain-compose-envfile-authority-smoke.sh）。\n      # Workspace + PostgreSQL + stopped Runner preparation is intentionally\n      # heavier than inspect/start/cancel, so it has an independent budget.\n      - KERNEL_FLEET_PREPARE_TIMEOUT_MS=${KERNEL_FLEET_PREPARE_TIMEOUT_MS:-180000}\n      # Xian Workers must be able to call the US Brain over Tailscale.\n      - KERNEL_FLEET_REMOTE_CALLBACK_BASE_URL=${KERNEL_FLEET_REMOTE_CALLBACK_BASE_URL:-http://100.71.151.105:5221}\n      # host 网络模式下容器与宿主共享网络栈，localhost 直接可达宿主 Postgres（listen 127.0.0.1）\n      - DB_HOST=${DB_HOST:-localhost}\n      - DB_PORT=${DB_PORT:-5432}\n      - DB_NAME=${DB_NAME:-cecelia}\n      - DB_USER=${DB_USER:-cecelia}\n      - DB_PASSWORD=${DB_PASSWORD:-cecelia}\n      # review 门审批 token（issue afc50c30）：只注入 Brain 本容器，relay/harness 执行体\n      # 容器不挂载——执行体物理上无法伪造人工批准。值从部署机根 .env（gitignored）/\n      # ~/.credentials/cecelia-brain.env 注入；缺省空 → 路由 503 fail-closed。\n      - HARNESS_REVIEW_APPROVER_TOKEN=${HARNESS_REVIEW_APPROVER_TOKEN:-}\n      - BRAIN_PORT=5221\n      - CECELIA_TICK_ENABLED=${CECELIA_TICK_ENABLED:-true}\n      # Concurrency: auto-calculated from hardware (CPU/memory) via slot-allocator.js\n      # CECELIA_MAX_SEATS: hard cap on concurrent slots (overrides auto-calc, set 0 to disable)\n      - CECELIA_MAX_SEATS=10\n      # CECELIA_BUDGET_SLOTS: budget-layer cap (< MAX_SEATS), reserves 3 slots for burst buffer + INTERACTIVE_RESERVE\n      - CECELIA_BUDGET_SLOTS=7\n      - CECELIA_TICK_INTERVAL_MS=${CECELIA_TICK_INTERVAL_MS:-5000}\n      - DISPATCH_TIMEOUT_MINUTES=${DISPATCH_TIMEOUT_MINUTES:-60}\n      - FEISHU_BOT_WEBHOOK=${FEISHU_BOT_WEBHOOK:-}\n      # BARK_TOKEN only comes from env_file (.env.docker) — 不要在这里写\n      # `${BARK_TOKEN:-}`：environment 优先级高于 env_file，任何不带宿主 shell\n      # 预先 export BARK_TOKEN 的 `compose up` 都会把 .env.docker 里的真实 token\n      # 盖成空串 → Bark 告警静默失效（2026-09-11 us-vps 生产实证）。\n      # us-vps 上没有交互式 Claude Code（引擎-机器绑定铁律），此路径不会被真正调用，\n      # 保留字段结构一致性，值指向本机 REPO_ROOT 对应位置。\n      - CECELIA_RUN_PATH=/root/cecelia/packages/brain/scripts/cecelia-run.sh\n      # Dockerfile 镜像烙入 ENV HOME=/Users/administrator（macOS 专属，供 macOS 侧\n      # os.homedir()/docker-executor 子容器 mount 路径对齐用）。Linux 上必须显式\n      # override 成真实宿主 home，否则容器内所有直接调用 os.homedir() 的代码\n      # （如 harness-credentials.js 解析 GitHub token 文件路径）都会拼错成一个\n      # 容器内不存在的路径。2026-09-12 生产实证：golden_path_proposal 任务因此\n      # 报 github_token_unavailable。\n      - HOME=/root\n      - HOST_HOME=/root\n      # 部署根：us-vps 单一 checkout 同时充当 REPO_ROOT（见上方 volumes 注释）\n      - REPO_ROOT=/root/cecelia\n      # 专用部署根，deploy-local.sh 守卫自愈到 origin/main（脏/落后时硬 reset 而非静默降级）\n      - CECELIA_DEPLOY_AUTORESET=1\n      # Codex CLI 容器内位置（由 Dockerfile npm install -g @openai/codex 装到 /usr/local/bin/codex）\n      # us-vps 上不会有 codex relay 子容器被派发（Codex 只在 mmv 跑），保留常量避免代码里\n      # 读取 undefined 路径；CODEX_HOME/CODEX_RELAY_HOME 因对应挂载已裁剪，不注入。\n      - CODEX_BIN=/usr/local/bin/codex\n      # Brain 容器里 /tmp/cecelia-prompts 对应的宿主路径（docker-executor 用它构造子容器 mount 源）\n      - HOST_PROMPT_DIR=/root/claude-output/cecelia-prompts\n      # ZenithJoy API — harness-sprint-state skill 写 sprint_states/journey_steps 用\n      - BRAIN_API=http://host.docker.internal:5200\n      # ZenithJoy 蓝绿护栏：staging-e2e-runner.js 健康检查 :5201，需指向宿主（容器内 localhost 不通宿主端口）\n      - ZJ_STAGING_HOST=host.docker.internal\n      # P0-fix: Brain 写发布回执到独立 zenithjoy 库（zenithjoy-db.js 依赖此变量）\n      # 未设 → 静默落回 cecelia.zenithjoy schema（拆库目的失效）\n      - ZENITHJOY_DB_NAME=zenithjoy\n      # Notion Inbox 采集凭据（F6加厚，notion-capture-ingest.js）\n      # 未配置时静默跳过，不影响其他 job（fail-open，非关键路径）\n      - NOTION_INBOX_TOKEN=${NOTION_INBOX_TOKEN:-}\n      - NOTION_INBOX_DB_ID=${NOTION_INBOX_DB_ID:-b45ca2cb-9c90-83f1-bc41-81ad0b86c1b1}\n      # OPENAI_API_KEY is provided via env_file (.env.docker) — do NOT override here\n      # FEISHU_OWNER_OPEN_IDS is provided via env_file (.env.docker) — same reason, do NOT override here\n      # ⚠️ 已知遗留（2026-09-13 部分消除）：BRAIN_API/ZJ_STAGING_HOST 两个默认值仍是\n      # host.docker.internal，host 网络模式下这个域名不会被解析——它们指向的服务本来就在\n      # 别的物理机（mmv/M4），跟网络模式无关，us-vps 真正需要这些功能时必须在 .env.docker\n      # 里显式覆盖成对应机器的真实 Tailscale 地址。\n      # FLEET_WORKER_US_MAC_M4_URL 已于 2026-09-13 就地改成真实地址（见上），不再属于此遗留：\n      # 实测 .env.docker 里从未定义过它，所以「必须显式覆盖」这条从来没被兑现，默认值一直生效。\n    # compose standalone cgroup 限额（deploy.resources 只在 Docker Swarm 模式生效）\n    # us-vps 零执行铁律物理闸（决策 95477a66）：宿主仅 3.8G，原 4g limit > 整机 = 零保护，\n    # Brain 失控可拖死全机。收紧至 2.5g——Brain 常态数百 MB，2.5G 已是 5 倍余量；\n    # node 堆上限仍为 3072（Dockerfile CMD），极端下堆超 2.5G 会被 cgroup 硬杀并由\n    # restart 拉起（in_progress 恢复机制已有）——宁可 Brain 单死重启，不可整机陪葬。\n    # debt: 后续把 CMD 堆参数对齐到 2048 以恢复\"先 GC 后杀\"的正常次序。\n    mem_limit: 2.5g\n    mem_reservation: 1g\n    cpus: 2.0\n    deploy:\n      resources:\n        limits:\n          memory: 2.5G\n          cpus: '2'\n        reservations:\n          memory: 1G\n    restart: unless-stopped\n    healthcheck:\n      test: [\"CMD\", \"curl\", \"-f\", \"http://localhost:5221/api/brain/tick/status\"]\n      interval: 30s\n      timeout: 10s\n      retries: 3\n      start_period: 40s\n    logging:\n      driver: \"json-file\"\n      options:\n        max-size: \"10m\"\n        max-file: \"3\"\n",
  "final": "# == us-vps (Linux) Production Environment ==\n# docker-compose.yml 的 Linux 专属版本（决策：Brain us-vps(Linux)部署-compose策略，\n# 拍板\"为 Linux 单建 docker-compose.us-vps.yml，与 macOS 的 docker-compose.yml 互不牵连\"）。\n# 只砍掉账号绑定类挂载（.claude / .codex-team1~5 / .grok ——\n# 按「引擎-机器绑定铁律」Claude/Codex 只在 mmv 跑，us-vps 不需要这些账号挂载，\n# 且这些宿主路径在 Linux 上本来就不存在）。其余挂载全部保留，只是把宿主路径\n# 从 /Users/administrator/... 改指 Linux 路径 /root/...（决策：...凭据挂载裁剪范围细化）。\n#\n# Build first: bash scripts/brain-build.sh\n# Deploy:      bash scripts/brain-deploy.sh（会按 uname -s 自动选到本文件）\n\nname: cecelia\n\nservices:\n  node-brain:\n    image: ${CECELIA_RELEASE_IMAGE:-cecelia-brain:${BRAIN_VERSION:-latest}}\n    container_name: cecelia-node-brain\n    # us-vps 上 Postgres 只监听 127.0.0.1（未对外开放到 docker 网桥），且现役容器一直是这样\n    # 跑的（docker inspect 实测 NetworkMode=host）——沿用 host 网络模式，不走 bridge+端口映射。\n    # host 模式下容器与宿主共享网络栈，容器内 localhost 直接就是宿主 localhost，不需要\n    # ports 段（host 模式下 compose 会拒绝一起声明），也不需要 host.docker.internal 解析。\n    network_mode: host\n    # 生产切换实测(2026-09-11)：read_only:true 会让 fleet worker 的 SSH 控制 socket\n    # 创建失败(unix_listener: cannot bind ... Read-only file system)，跨机器 SSH 多路复用\n    # 功能悄悄失效。现役容器一直以来就是 read_only:false 在跑(docker inspect 实测)，\n    # 沿用这个已验证的宽松策略，不引入这个未经验证的加固。\n    read_only: false\n    tmpfs:\n      - /tmp:size=100M\n      # ssh ControlMaster socket 目录：宿主 /root/.ssh 以 ro 挂入，宿主 ssh config 的\n      # ControlPath 指向 ~/.ssh/sockets/ → 容器内建 socket 撞 Read-only file system，\n      # ops-collector 的 hk-vps ssh 逃逸全灭（09-09 起运行舱账断更 5 天的根因）。\n      # 以 tmpfs 覆盖该子路径恢复可写，不放松 .ssh 本体的 ro。\n      - /root/.ssh/sockets:size=1M\n    volumes:\n      # Docker socket: Brain 调 dockerd spawn 兄弟 pipeline 容器\n      - /var/run/docker.sock:/var/run/docker.sock\n      # Skills SSOT（B57/B58）：.claude/skills/* 是指向这里的 symlink，不 mount 则容器内\n      # symlink 悬空 → harness SKILL 加载失败（loadSkillContent 全 miss）；dist 未 mount 则\n      # Brain 无法 dispatch relay。us-vps 上需要这两个仓库分别 clone 到 /root/ 下。\n      - /root/zenithjoy-skills:/root/zenithjoy-skills:ro\n      - /root/zenithjoy-skills-dist:/root/zenithjoy-skills-dist:ro\n      # 派发默认模板随 Brain 发布，凭据由现有只读 ~/.credentials 挂载注入。\n      # OpenClaw 运行事实和守卫从 Mac Studio 读取，不挂载 US 历史状态或工作区。\n      # 凭据：DB/内部服务凭据 SSOT。下方 environment 段显式 override HOME=/root，\n      # 这样 Brain os.homedir() 才能解析到这里挂载的真实路径（Dockerfile 镜像烙入的\n      # ENV HOME=/Users/administrator 是 macOS 专属值，此前一直未被 override，\n      # 2026-09-12 生产实证：导致 os.homedir() 拼错路径，harness-credentials.js\n      # 读不到这份凭据文件 → github_token_unavailable）。\n      - /root/.credentials:/root/.credentials:ro\n      # 接入控制面唯一可写凭据子目录；宿主必须预建root:root 0700，禁止compose创建宽权限目录。\n      - type: bind\n        source: /root/.credentials/fleet-control\n        target: /run/cecelia-fleet-control\n        bind:\n          create_host_path: false\n      # packages/workflows 不再单独叠只读挂载（09-28 事故，任务 ddee8737）：部署根守卫在本容器内对部署根\n      # git checkout -f / reset --hard，只读子挂载让任何改到该目录的提交都部署失败。该目录随部署根整体可写。\n      # Config: OKR validation spec (read-only, mounted at /config for validate-okr-structure.js)\n      - /root/cecelia/packages/config:/config:ro\n      # HEARTBEAT.md (read-write for GET/PUT API)\n      - /root/cecelia/HEARTBEAT.md:/HEARTBEAT.md:rw\n      # workers.config.json (read-write for PUT /staff/workers API)\n      - /root/cecelia/packages/workflows/staff/workers.config.json:/root/cecelia/packages/workflows/staff/workers.config.json:rw\n      # Worktree 根目录（Brain spawn harness/pipeline 容器时要 mount 宿主 worktree）\n      - /root/cecelia/.claude/worktrees:/root/cecelia/.claude/worktrees:rw\n      - /root/worktrees:/root/worktrees:rw\n      # Content pipeline 产物目录（docker-executor existsFn 检查要求 Brain 可见宿主该路径，\n      # 否则不挂给 pipeline container，产物写到 ephemeral 空间 --rm 丢失。见 PR #2527 后续修）\n      - /root/content-output:/root/content-output:rw\n      - /root/claude-output:/root/claude-output:rw\n      # SSH：pipeline-export.sh 跑 \"ssh nas\" 上传 NAS，docker-executor 挂给 pipeline container\n      - /root/.ssh:/root/.ssh:ro\n      # Git + gh config（harness / pipeline container 做 git commit / gh pr 需要）\n      - /root/.gitconfig:/root/.gitconfig:ro\n      - /root/.config/gh:/root/.config/gh:ro\n      # 部署根：us-vps 只有一份 checkout（不像 macOS 区分\"活人主仓\"和\"CD 专用部署根\"，\n      # us-vps 上没有交互式开发，单一 checkout 同时充当主仓库挂载和 REPO_ROOT）。\n      - /root/cecelia:/root/cecelia:rw\n      # Prompt 文件目录：Brain 写 prompt 文件这里（docker-executor writePromptFile），\n      # 子容器 mount 源必须由宿主 docker daemon 解析 → 必须宿主路径。\n      - /root/claude-output/cecelia-prompts:/tmp/cecelia-prompts:rw\n      # Timezone (read-only)\n      - /etc/localtime:/etc/localtime:ro\n    env_file:\n      - .env.docker\n      # 所有 checkout / cron / 蓝绿部署共用宿主凭据 SSOT；首次部署自动生成。\n      - path: ${CECELIA_INTERNAL_ENV_FILE:-/root/.credentials/cecelia-internal.env}\n        required: false\n    environment:\n      - CECELIA_LINUX_POOL_DEPLOYMENTS_FILE=/run/cecelia-fleet-control/pools.json\n      - CECELIA_LINUX_SCRIPT_DEPLOYMENTS_FILE=/run/cecelia-fleet-control/scripts.json\n      - NODE_ENV=production\n      - TZ=Asia/Shanghai\n      - ENV_REGION=${ENV_REGION:-us}\n      # OpenClaw 已迁 Mac Studio：退役 US 本地控制，保留远端触达观测。\n      - OPENCLAW_GUARD_MODE=remote\n      # Universal Map repo→scope 身份绑定；拒绝仅 basename 相同的跨仓证据冒用。\n      - CECELIA_MAP_REPO_SCOPES=${CECELIA_MAP_REPO_SCOPES:-perfectuser21/cecelia=cecelia,cecelia=cecelia}\n      # Kernel controller 固定留在 US M4；Docker hostname 不是可调度机器身份。\n      - CECELIA_MACHINE_ID=${CECELIA_MACHINE_ID:-us-mac-m4}\n      # Fleet Node admission is mandatory. Brain accepts only these canonical\n      # server-owned Worker endpoints and caches their evidence for at most 90s.\n      # 2026-09-13：默认值从 host.docker.internal 改为 MMV 真实 Tailscale 地址。\n      # 原占位符在 host 网络模式的 Linux 容器里不解析，导致 Claude 类任务（铁律\n      # ca6bf8e7：Claude 只在 MMV 跑）的远程派发目标不可达。MMV 侧 fleet-worker 已于\n      # 同日修好：绑定地址从 127.0.0.1 改为 Tailscale IP，Brain 容器实测 HTTP 200、\n      # docker/container/postgres 全绿。\n      - FLEET_WORKER_US_MAC_M4_URL=${FLEET_WORKER_US_MAC_M4_URL:-http://100.71.151.105:5231}\n      # 本机执行闸（铁律 96054a8b：us-vps 只当调度器，执行全下放 Mac worker）。\n      # 拦在 harness-skill-relay.js 的 spawnSkillRelaySession 咽喉上，拒绝时不建 run。\n      # 注意：故意不用 CECELIA_MACHINE_ID 表达这件事——那个变量的语义是「fleet 可调度\n      # 节点身份 + 凭据签发权」，credential-broker.js:144 与 github-credential-broker.js:36\n      # 硬编码要求它等于 us-mac-m4，改了会掐断凭据签发导致全面 fail-closed（纠正决策\n      # 26c1e763 supersede 962281b2）。所以 CECELIA_MACHINE_ID 保持 us-mac-m4 不动。\n      - CECELIA_LOCAL_EXECUTION_ENABLED=${CECELIA_LOCAL_EXECUTION_ENABLED:-false}\n      # Notion 排单分流 OpenClaw：hk-vps n8n V4 画布（Tailscale HTTPS，实测可达）\n      - N8N_V4_WEBHOOK_URL=${N8N_V4_WEBHOOK_URL:-https://vps-hk.tailce7a8b.ts.net:8444/webhook/agentic-workflow-runner-v4/run}\n      # ops-collector 的 host-exec 逃逸目标：MMV 时代默认 administrator@host.docker.internal\n      # （ssh 回 Mac 宿主），us-vps 是 Linux 该域名不解析且宿主无 launchctl/gh——五条采集腿\n      # 全灭致运行舱账断更（09-09~14 实证）。指到 primary worker MMV（launchctl/gh/hk-vps\n      # 跳板本来就在 Mac）。IP 见 machine-registry.js us-mac-m4.tailscaleIp；Mac Studio 迁移时同步改。\n      - CECELIA_HOST_EXEC_SSH=${CECELIA_HOST_EXEC_SSH:-administrator@100.71.151.105}\n      - FLEET_WORKER_XIAN_MAC_M4_URL=${FLEET_WORKER_XIAN_MAC_M4_URL:-http://100.86.57.69:5231}\n      - FLEET_WORKER_XIAN_MAC_M1_URL=${FLEET_WORKER_XIAN_MAC_M1_URL:-http://100.88.166.55:5231}\n      - FLEET_NODE_ADMISSION_CACHE_TTL_MS=${FLEET_NODE_ADMISSION_CACHE_TTL_MS:-1000}\n      # Phase 4B: all canonical machines use the authenticated Fleet Worker\n      # Attempt API. An absent/short token remains fail-closed in the transport.\n      - KERNEL_FLEET_REMOTE_ENABLED=${KERNEL_FLEET_REMOTE_ENABLED:-true}\n      # KERNEL_FLEET_BRIDGE_TOKEN 只来自 env_file(.env.docker)——不要在这里写\n      # `${KERNEL_FLEET_BRIDGE_TOKEN:-}`：environment 优先级高于 env_file，任何不带\n      # --env-file 的 compose up 都会把 token 盖成空串（2026-08-16 09:38Z 生产实证，\n      # 守卫 scripts/smoke/brain-compose-envfile-authority-smoke.sh）。\n      # Workspace + PostgreSQL + stopped Runner preparation is intentionally\n      # heavier than inspect/start/cancel, so it has an independent budget.\n      - KERNEL_FLEET_PREPARE_TIMEOUT_MS=${KERNEL_FLEET_PREPARE_TIMEOUT_MS:-180000}\n      # Xian Workers must be able to call the US Brain over Tailscale.\n      - KERNEL_FLEET_REMOTE_CALLBACK_BASE_URL=${KERNEL_FLEET_REMOTE_CALLBACK_BASE_URL:-http://100.71.151.105:5221}\n      # host 网络模式下容器与宿主共享网络栈，localhost 直接可达宿主 Postgres（listen 127.0.0.1）\n      - DB_HOST=${DB_HOST:-localhost}\n      - DB_PORT=${DB_PORT:-5432}\n      - DB_NAME=${DB_NAME:-cecelia}\n      - DB_USER=${DB_USER:-cecelia}\n      - DB_PASSWORD=${DB_PASSWORD:-cecelia}\n      # review 门审批 token（issue afc50c30）：只注入 Brain 本容器，relay/harness 执行体\n      # 容器不挂载——执行体物理上无法伪造人工批准。值从部署机根 .env（gitignored）/\n      # ~/.credentials/cecelia-brain.env 注入；缺省空 → 路由 503 fail-closed。\n      - HARNESS_REVIEW_APPROVER_TOKEN=${HARNESS_REVIEW_APPROVER_TOKEN:-}\n      - BRAIN_PORT=5221\n      - CECELIA_TICK_ENABLED=${CECELIA_TICK_ENABLED:-true}\n      # Concurrency: auto-calculated from hardware (CPU/memory) via slot-allocator.js\n      # CECELIA_MAX_SEATS: hard cap on concurrent slots (overrides auto-calc, set 0 to disable)\n      - CECELIA_MAX_SEATS=10\n      # CECELIA_BUDGET_SLOTS: budget-layer cap (< MAX_SEATS), reserves 3 slots for burst buffer + INTERACTIVE_RESERVE\n      - CECELIA_BUDGET_SLOTS=7\n      - CECELIA_TICK_INTERVAL_MS=${CECELIA_TICK_INTERVAL_MS:-5000}\n      - DISPATCH_TIMEOUT_MINUTES=${DISPATCH_TIMEOUT_MINUTES:-60}\n      - FEISHU_BOT_WEBHOOK=${FEISHU_BOT_WEBHOOK:-}\n      # BARK_TOKEN only comes from env_file (.env.docker) — 不要在这里写\n      # `${BARK_TOKEN:-}`：environment 优先级高于 env_file，任何不带宿主 shell\n      # 预先 export BARK_TOKEN 的 `compose up` 都会把 .env.docker 里的真实 token\n      # 盖成空串 → Bark 告警静默失效（2026-09-11 us-vps 生产实证）。\n      # us-vps 上没有交互式 Claude Code（引擎-机器绑定铁律），此路径不会被真正调用，\n      # 保留字段结构一致性，值指向本机 REPO_ROOT 对应位置。\n      - CECELIA_RUN_PATH=/root/cecelia/packages/brain/scripts/cecelia-run.sh\n      # Dockerfile 镜像烙入 ENV HOME=/Users/administrator（macOS 专属，供 macOS 侧\n      # os.homedir()/docker-executor 子容器 mount 路径对齐用）。Linux 上必须显式\n      # override 成真实宿主 home，否则容器内所有直接调用 os.homedir() 的代码\n      # （如 harness-credentials.js 解析 GitHub token 文件路径）都会拼错成一个\n      # 容器内不存在的路径。2026-09-12 生产实证：golden_path_proposal 任务因此\n      # 报 github_token_unavailable。\n      - HOME=/root\n      - HOST_HOME=/root\n      # 部署根：us-vps 单一 checkout 同时充当 REPO_ROOT（见上方 volumes 注释）\n      - REPO_ROOT=/root/cecelia\n      # 专用部署根，deploy-local.sh 守卫自愈到 origin/main（脏/落后时硬 reset 而非静默降级）\n      - CECELIA_DEPLOY_AUTORESET=1\n      # Codex CLI 容器内位置（由 Dockerfile npm install -g @openai/codex 装到 /usr/local/bin/codex）\n      # us-vps 上不会有 codex relay 子容器被派发（Codex 只在 mmv 跑），保留常量避免代码里\n      # 读取 undefined 路径；CODEX_HOME/CODEX_RELAY_HOME 因对应挂载已裁剪，不注入。\n      - CODEX_BIN=/usr/local/bin/codex\n      # Brain 容器里 /tmp/cecelia-prompts 对应的宿主路径（docker-executor 用它构造子容器 mount 源）\n      - HOST_PROMPT_DIR=/root/claude-output/cecelia-prompts\n      # ZenithJoy API — harness-sprint-state skill 写 sprint_states/journey_steps 用\n      - BRAIN_API=http://host.docker.internal:5200\n      # ZenithJoy 蓝绿护栏：staging-e2e-runner.js 健康检查 :5201，需指向宿主（容器内 localhost 不通宿主端口）\n      - ZJ_STAGING_HOST=host.docker.internal\n      # P0-fix: Brain 写发布回执到独立 zenithjoy 库（zenithjoy-db.js 依赖此变量）\n      # 未设 → 静默落回 cecelia.zenithjoy schema（拆库目的失效）\n      - ZENITHJOY_DB_NAME=zenithjoy\n      # Notion Inbox 采集凭据（F6加厚，notion-capture-ingest.js）\n      # 未配置时静默跳过，不影响其他 job（fail-open，非关键路径）\n      - NOTION_INBOX_TOKEN=${NOTION_INBOX_TOKEN:-}\n      - NOTION_INBOX_DB_ID=${NOTION_INBOX_DB_ID:-b45ca2cb-9c90-83f1-bc41-81ad0b86c1b1}\n      # OPENAI_API_KEY is provided via env_file (.env.docker) — do NOT override here\n      # FEISHU_OWNER_OPEN_IDS is provided via env_file (.env.docker) — same reason, do NOT override here\n      # ⚠️ 已知遗留（2026-09-13 部分消除）：BRAIN_API/ZJ_STAGING_HOST 两个默认值仍是\n      # host.docker.internal，host 网络模式下这个域名不会被解析——它们指向的服务本来就在\n      # 别的物理机（mmv/M4），跟网络模式无关，us-vps 真正需要这些功能时必须在 .env.docker\n      # 里显式覆盖成对应机器的真实 Tailscale 地址。\n      # FLEET_WORKER_US_MAC_M4_URL 已于 2026-09-13 就地改成真实地址（见上），不再属于此遗留：\n      # 实测 .env.docker 里从未定义过它，所以「必须显式覆盖」这条从来没被兑现，默认值一直生效。\n    # compose standalone cgroup 限额（deploy.resources 只在 Docker Swarm 模式生效）\n    # us-vps 零执行铁律物理闸（决策 95477a66）：宿主仅 3.8G，原 4g limit > 整机 = 零保护，\n    # Brain 失控可拖死全机。收紧至 2.5g——Brain 常态数百 MB，2.5G 已是 5 倍余量；\n    # node 堆上限仍为 3072（Dockerfile CMD），极端下堆超 2.5G 会被 cgroup 硬杀并由\n    # restart 拉起（in_progress 恢复机制已有）——宁可 Brain 单死重启，不可整机陪葬。\n    # debt: 后续把 CMD 堆参数对齐到 2048 以恢复\"先 GC 后杀\"的正常次序。\n    mem_limit: 2.5g\n    mem_reservation: 1g\n    cpus: 2.0\n    deploy:\n      resources:\n        limits:\n          memory: 2.5G\n          cpus: '2'\n        reservations:\n          memory: 1G\n    restart: unless-stopped\n    healthcheck:\n      test: [\"CMD\", \"curl\", \"-f\", \"http://localhost:5221/api/brain/tick/status\"]\n      interval: 30s\n      timeout: 10s\n      retries: 3\n      start_period: 40s\n    logging:\n      driver: \"json-file\"\n      options:\n        max-size: \"10m\"\n        max-file: \"3\"\n"
};
const hashes = {
  "packages/brain/src/openclaw-guards.js": "9d6933a6d7ed61955c5ebd920357c5d08500e2a2e665d5bc3f08958cb0202063",
  "packages/brain/src/host-exec.js": "11d58722a08d8b4c4d0fb9afa107c5840c3845302dcead62d4653a501c182daf",
  "packages/brain/src/notion-push-sync.js": "22cbe332597cfe00cba9c5950d81b6ce267dbaa9e78f081403053713630a659c",
  "packages/brain/src/lib/openclaw-dispatch-template.js": "0c964c2d5e81c1feeb7ed5ea72ef8a3e0272da48ee72e53174b11d3ae8a17fe4",
  "packages/brain/src/lib/openclaw-dispatch-defaults.js": "0572c1c9dcd5e9b31ac49c2ea3355c0c0c2e0b7fdd30117c559b6bbeb97e3a7a",
  "packages/brain/src/feishu-task-ledger.js": "7c749eb053dc5eabe6160dcf5ec854857fc27eb215832823599079fd23ae29bc",
  "packages/brain/src/openclaw-run-ingest.js": "f12d790cdb7e7cf61e97e0e1d85034fccf1a2ab1c73296b8e736dbff9a39e709"
};
const composeHashes = {
  "remote": "7d152cec3fea0f50cab0a707bd7830a01c620953ffcc99851be27e384aca405b",
  "template": "81621e0bac0ae54045b5c4d2973c15ca7e960c87cf4406028d03c45d3e9a8d5a",
  "combined": "ed11f478e6ca21f997fb26c0fc4e7baddfd5a17a36789aa3e5da17a56f26d617",
  "final": "ef7b77ce25f3d91e8be933fd604bbbd3dd0457fab6a5c1bd1a72f8d6fb10baf2"
};
const fixture = readFixedExistingOpsGitFixture();
const { revision, read: original } = fixture;
const paths = [...new Set([...fixture.paths, ...Object.keys(samples)])];
const hash = text => createHash('sha256').update(text).digest('hex');
async function build(stage, patch = {}) {
 const input = { ...samples, 'docker-compose.us-vps.yml': compositions[stage], ...patch };
 const out = await buildExistingOpsSources({scope:'cecelia-factory',repo:'perfectuser21/cecelia',revision,paths,
  readSource:p=>Object.hasOwn(input,p)?input[p]:original(p)});
 return out.consumers.find(c=>c.workflow_key==='factory_f2_ops');
}
it('固定已审阶段原字节来源独立摘要一致',()=>{
 for(const [p,text]of Object.entries(samples))expect(hash(text)).toBe(hashes[p]);
 for(const [stage,text]of Object.entries(compositions))expect(hash(text)).toBe(composeHashes[stage]);
});
for(const stage of ['remote','template','combined','final'])it('已知历史Git fixture 的已审US '+stage+'组合collector来源成立',async()=>{
 const f2=await build(stage);expect(f2.status,JSON.stringify(f2.gaps)).toBe('verified');
 expect(f2.bindings.find(b=>b.path==='docker-compose.us-vps.yml')?.content_sha256).toBe(composeHashes[stage]);
 expect(f2.input_relations.some(r=>r.consumer_path==='docker-compose.us-vps.yml'&&r.kind==='reviewed_us_openclaw_prerequisite')).toBe(true);
 if(stage==='final')expect(f2.input_relations.some(r=>r.consumer_path==='packages/brain/src/openclaw-run-ingest.js'&&r.input_path==='packages/brain/src/host-exec.js'&&r.kind==='reviewed_us_openclaw_static_import')).toBe(true);
},120000);
it('final卸挂载不能搭配旧本地读取器，失败清空绑定',async()=>{
 const f2=await build('final',{'packages/brain/src/feishu-task-ledger.js':'export const localState="/opt/openclaw/state";'});
 expect(f2.status).toBe('unknown');expect(f2.bindings).toEqual([]);expect(f2.input_relations).toEqual([]);
},120000);

import { proveReviewedUsCompose } from '../existing-ops-us-compose-source.js';
for(const missing of Object.keys(samples))it('final每个真实前置缺失/变化拒绝且不留关系 '+missing,async()=>{
 for(const invalid of [null, samples[missing]+'\n// unreviewed']){
  const relations=[];
  expect(await proveReviewedUsCompose({text:compositions.final,read:p=>p===missing?invalid:samples[p],relations,revision})).toBe(false);
  expect(relations).toEqual([]);
 }
});
it('非审定compose不能借相同关键字或任意组合获得证明',async()=>{
 for(const text of [compositions.final+'\n# unknown',compositions.remote.replace('OPENCLAW_GUARD_MODE=remote','OPENCLAW_GUARD_MODE=local'),compositions.template.replace('      - /opt/openclaw/state:/opt/openclaw/state\n','')]){
  const seen=[],relations=[];
  expect(await proveReviewedUsCompose({text,read:p=>{seen.push(p);return samples[p];},relations,revision})).toBe(false);
  expect(seen).toEqual([]);expect(relations).toEqual([]);
 }
});
it('remote/template阶段仅绑定各自真实前置，不提前认领另一阶段',async()=>{
 for(const [stage,expected]of [['remote',['openclaw-guards.js','host-exec.js']],['template',['notion-push-sync.js','lib/openclaw-dispatch-template.js','lib/openclaw-dispatch-defaults.js']]]){
  const seen=[],relations=[];
  expect(await proveReviewedUsCompose({text:compositions[stage],read:p=>{seen.push(p);return samples[p];},relations,revision})).toBe(true);
  expect(seen.sort()).toEqual(expected.map(p=>'packages/brain/src/'+p).sort());
  expect(relations.every(r=>r.revision===revision)).toBe(true);
 }
});
it('读取失败向上报告，不能生成成功关系',async()=>{
 const relations=[];
 await expect(proveReviewedUsCompose({text:compositions.final,read:()=>{throw Error('missing');},relations,revision})).rejects.toThrow('missing');
 expect(relations).toEqual([]);
});
